INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e02db1c-907d-4fc9-b9e7-89c49e71373b', '送虞道士', '送虞道士', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["煙霞聚散通三島，星斗分明在一壺。","笑說餘杭沽酒去，蔡家重要會麻姑。"]', '["煙霞聚散通三島，星斗分明在一壺。","笑说餘杭沽酒去，蔡家重要會麻姑。"]', '诗', 'shi', '', NULL, '送虞道士 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('462425f0-cf8d-44fc-a925-bf83135ffefd', '懷舊夜吟寄趙杞', '懷旧夜吟寄趙杞', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["長笛聲中海月飛，桃花零落滿庭墀。","魂銷事去無尋處，酒醒孤吟不寐時。","萱草豈能忘積恨，尺書誰與達相思。","悠悠方寸何因解，明日江樓望渺瀰。"]', '["长笛声中海月飞，桃花零落满庭墀。","魂銷事去無尋处，酒醒孤吟不寐时。","萱草豈能忘積恨，尺书誰與達相思。","悠悠方寸何因解，明日江楼望渺瀰。"]', '诗', 'shi', '', NULL, '懷舊夜吟寄趙杞 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1a79355-e122-455e-a869-208928acc02a', '宿臨江驛', '宿臨江驛', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["候館寥寥輟櫂過，酒醒無奈旅愁何。","雨昏郊郭行人少，葦暗汀洲宿鴈多。","干祿已悲凋髮鬢，結茅終愧負煙蘿。","篇章早晚逢知己，苦志忘形自有魔。"]', '["候館寥寥輟櫂過，酒醒無奈旅愁何。","雨昏郊郭行人少，葦暗汀洲宿鴈多。","干祿已悲凋髮鬢，結茅終愧負煙蘿。","篇章早晚逢知己，苦志忘形自有魔。"]', '诗', 'shi', '', NULL, '宿臨江驛 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c46b37b-50fe-4238-a789-25ac7dbb0291', '途中柳', '途中柳', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["翠色晴來近，長亭路去遙。","無人折煙縷，落日拂溪橋。"]', '["翠色晴来近，长亭路去遙。","無人折煙縷，落日拂溪橋。"]', '诗', 'shi', '', NULL, '途中柳 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a748592-3985-4bd9-a645-e440a0985abb', '隔牆花', '隔牆花', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["顏色尤難近，馨香不易通。","朱門金鎖隔，空使怨春風。"]', '["顏色尤难近，馨香不易通。","朱门金鎖隔，空使怨春风。"]', '诗', 'shi', '', NULL, '隔牆花 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d31a7e7c-1104-4d54-b12b-5125642634ee', '廣陵寒食夜', '廣陵寒食夜', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["廣陵寒食夜，豪貴足佳期。","紫陌人歸後，紅樓月上時。","綺羅香未歇，絲竹韻猶遲。","明日踏青興，輸他輕薄兒。"]', '["廣陵寒食夜，豪貴足佳期。","紫陌人归後，紅楼月上时。","綺羅香未歇，絲竹韻猶遲。","明日踏青兴，輸他轻薄兒。"]', '诗', 'shi', '', NULL, '廣陵寒食夜 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27c442ed-0942-4412-8d46-561a2eee36ac', '寄廬山莊隱土', '寄廬山莊隐土', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["煙蘿擁竹關，物外自求安。","逼枕溪聲近，當簷岳色寒。","藥苗應自採，琴調對誰彈。","待了浮名後，依君共挂冠。"]', '["煙蘿擁竹关，物外自求安。","逼枕溪声近，當簷岳色寒。","藥苗應自採，琴調对誰彈。","待了浮名後，依君共挂冠。"]', '诗', 'shi', '', NULL, '寄廬山莊隱土 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4396bae-7fca-4982-beae-2af77afa7438', '吉水寄閻侍御', '吉水寄閻侍御', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["何處懷君切，令人欲白頭。","偶尋花外寺，獨立水邊樓。","不得論休戚，何因校獻酬。","吟餘興難盡，風笛起漁舟。"]', '["何处懷君切，令人欲白头。","偶尋花外寺，独立水邊楼。","不得論休戚，何因校獻酬。","吟餘兴难尽，风笛起漁舟。"]', '诗', 'shi', '', NULL, '吉水寄閻侍御 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab8452c8-aa98-43a0-b09c-00ecaacf731c', '送張惟貞少府之江陰', '送張惟貞少府之江陰', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["相送煙汀畔，酒闌登小舟。","離京梅雨歇，到邑早蟬秋。","俗必期康濟，詩誰互唱酬。","晚涼諸吏散，海月入虛樓。"]', '["相送煙汀畔，酒闌登小舟。","離京梅雨歇，到邑早蟬秋。","俗必期康濟，诗誰互唱酬。","晚涼諸吏散，海月入虛楼。"]', '诗', 'shi', '', NULL, '送張惟貞少府之江陰 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0712c64a-119f-4cf0-98e8-a04c876d25fc', '鍾陵禁煙寄從弟', '鍾陵禁煙寄從弟', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["落絮飛花日又西，踏青無侶草萋萋。","交親書斷竟不到，忍聽黃昏杜宇啼。"]', '["落絮飞花日又西，踏青無侶草萋萋。","交親书斷竟不到，忍听黄昏杜宇啼。"]', '诗', 'shi', '', NULL, '鍾陵禁煙寄從弟 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4be82751-04ae-47a6-ad2e-681527e95698', '夜泊江渚', '夜泊江渚', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["水鄉明月上晴空，汀島香生杜若風。","不是當年獨醒客，且沽村酒待漁翁。"]', '["水乡明月上晴空，汀島香生杜若风。","不是當年独醒客，且沽村酒待漁翁。"]', '诗', 'shi', '', NULL, '夜泊江渚 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('408d49a7-8fe3-4e47-a699-668cee967bfb', '吉水縣依韻酬華松秀才見寄', '吉水縣依韻酬华松秀才见寄', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["官況蕭條在水村，吏歸無事好論文。","枕欹獨聽殘春雨，夢去空尋五老雲。","竹徑每憐和蘚步，禽聲偏愛隔花聞。","詩情冷淡知音少，獨喜江臯得見君。"]', '["官況蕭條在水村，吏归無事好論文。","枕欹独听殘春雨，梦去空尋五老云。","竹徑每怜和蘚步，禽声偏愛隔花闻。","诗情冷淡知音少，独喜江臯得见君。"]', '诗', 'shi', '', NULL, '吉水縣依韻酬華松秀才見寄 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('716410db-748c-4c72-9447-fe43643c4e8b', '貽廬山清溪觀王尊師', '貽廬山清溪观王尊師', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["霞帔星冠復杖藜，積年修鍊住靈溪。","松軒睡覺冷雲起，石磴坐來春日西。","採藥每尋巖徑遠，彈琴常到月輪低。","鼎中龍虎功成後，海上三山去不迷。"]', '["霞帔星冠复杖藜，積年修鍊住靈溪。","松軒睡覺冷云起，石磴坐来春日西。","採藥每尋巖徑远，彈琴常到月輪低。","鼎中龙虎功成後，海上三山去不迷。"]', '诗', 'shi', '', NULL, '貽廬山清溪觀王尊師 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01e6936a-2e87-42c8-b1a6-6a0b23043aca', '王昭君', '王昭君', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["蛾眉翻自累，萬里陷窮邊。","滴淚胡風起，寬心漢月圓。","飛塵長翳日，白草自連天。","誰貢和親策，千秋汚簡編。"]', '["蛾眉翻自累，万里陷窮邊。","滴泪胡风起，寬心漢月圓。","飞塵长翳日，白草自連天。","誰貢和親策，千秋汚簡編。"]', '诗', 'shi', '', NULL, '王昭君 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e99c3e40-3337-402c-9095-e650d4dd6b18', '送姚端先輩歸寧', '送姚端先輩归寧', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["知君歸覲省，稱意涉通津。","解纜汀洲曉，張帆煙水春。","牽吟芳草遠，貰酒亂花新。","拜慶庭闈處，蟾枝香滿身。"]', '["知君归覲省，稱意涉通津。","解纜汀洲晓，張帆煙水春。","牽吟芳草远，貰酒亂花新。","拜慶庭闈处，蟾枝香满身。"]', '诗', 'shi', '', NULL, '送姚端先輩歸寧 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40e5ad70-4a40-4ceb-9f9c-9c996ed35f8b', '江村晚秋作', '江村晚秋作', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["高秋水村路，隔岸見人家。","好是經霜葉，紅於帶露花。","臨罾魚易得，就店酒難賒。","吟興胡能盡，風清日又斜。"]', '["高秋水村路，隔岸见人家。","好是經霜葉，紅於带露花。","臨罾鱼易得，就店酒难賒。","吟兴胡能尽，风清日又斜。"]', '诗', 'shi', '', NULL, '江村晚秋作 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('673ef2d4-f502-40b9-a97d-1676d8211504', '蛩', '蛩', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["月冷莎庭夜已深，百蟲聲外有清音。","詩情正苦無眠處，愧爾堦前相伴吟。"]', '["月冷莎庭夜已深，百蟲声外有清音。","诗情正苦無眠处，愧爾堦前相伴吟。"]', '诗', 'shi', '', NULL, '蛩 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bd5130a-0f47-49ea-8efa-2f78aa9e5d05', '感秋書事', '感秋书事', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["宦途憔悴雪生頭，家計相牽未得休。","紅寥白蘋消息斷，舊溪煙月負漁舟。"]', '["宦途憔悴雪生头，家計相牽未得休。","紅寥白蘋消息斷，旧溪煙月負漁舟。"]', '诗', 'shi', '', NULL, '感秋書事 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1abf9344-171b-465c-b44c-aff4b97f8f5c', '訪廬山歸章禪伯', '訪廬山归章禪伯', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["沈沈石室疎鐘後，寂寂莎池片月明。","多少學徒求妙法，要於言下悟無生。"]', '["沈沈石室疎鐘後，寂寂莎池片月明。","多少学徒求妙法，要於言下悟無生。"]', '诗', 'shi', '', NULL, '訪廬山歸章禪伯 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60b298cc-aae8-4b30-8db7-ede9af387035', '廬山棲隱洞譚先生院留題', '廬山棲隐洞譚先生院留題', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["壇畔歸雲冷濕襟，拂苔移石坐花陰。","偶然醒得莊周夢，始覺玄門興味深。"]', '["壇畔归云冷濕襟，拂苔移石坐花陰。","偶然醒得莊周梦，始覺玄门兴味深。"]', '诗', 'shi', '', NULL, '廬山棲隱洞譚先生院留題 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e7f30a2-5ff5-4faa-b7fe-fe218e9bdd12', '江行值暴風雨', '江行值暴风雨', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["風狂雨暗舟人懼，自委神明志不邪。","投得葦灣波浪息，岸頭煙火近人家。"]', '["风狂雨暗舟人懼，自委神明志不邪。","投得葦灣波浪息，岸头煙火近人家。"]', '诗', 'shi', '', NULL, '江行值暴風雨 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d793181-0d9a-4e40-8d5e-90e8e889988a', '杪秋夕吟懷寄宋維先輩', '杪秋夕吟懷寄宋維先輩', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["江島窮秋木葉稀，月高何處搗寒衣。","苦嗟不見登龍客，此夜悠悠一夢飛。"]', '["江島窮秋木葉稀，月高何处捣寒衣。","苦嗟不见登龙客，此夜悠悠一梦飞。"]', '诗', 'shi', '', NULL, '杪秋夕吟懷寄宋維先輩 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca87a1e1-7656-4ebf-84f5-aa614ce60efc', '七夕', '七夕', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["星河耿耿正新秋，絲竹千家列綵樓。","可惜穿針方有興，纖纖初月苦難留。"]', '["星河耿耿正新秋，絲竹千家列綵楼。","可惜穿針方有兴，纖纖初月苦难留。"]', '诗', 'shi', '', NULL, '七夕 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45debebc-c4da-41b2-80c5-21de62edfda9', '吉水作尉時酬閻侍御見寄', '吉水作尉时酬閻侍御见寄', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["謬佐驅雞任，常思賦鵩人。","未諧林下約，空感病來身。","鏁徑青苔老，鋪階紅葉新。","相思不可見，猶喜得書頻。"]', '["謬佐驱雞任，常思賦鵩人。","未諧林下約，空感病来身。","鏁徑青苔老，鋪階紅葉新。","相思不可见，猶喜得书頻。"]', '诗', 'shi', '', NULL, '吉水作尉時酬閻侍御見寄 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88111b0a-ef31-44e1-8a63-45806c105500', '清溪逢張惟貞秀才', '清溪逢張惟貞秀才', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["洞隱紅霞外，房開碧嶂根。","昔年同鍊句，幾夜共聽猨。","考古書千卷，忘憂酒一樽。","如今歸建業，雅道喜重論。"]', '["洞隐紅霞外，房开碧嶂根。","昔年同鍊句，幾夜共听猨。","考古书千卷，忘憂酒一樽。","如今归建業，雅道喜重論。"]', '诗', 'shi', '', NULL, '清溪逢張惟貞秀才 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d13660f-e06a-4084-98ab-45415c9269b4', '送閻侍御歸闕', '送閻侍御归闕', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["羨君乘紫詔，歸路指通津。","鼓櫂煙波暖，還京雨露新。","趨朝丹禁曉，聳轡九衢春。","自愧湮沈者，隨軒未有因。"]', '["羨君乘紫詔，归路指通津。","鼓櫂煙波暖，還京雨露新。","趨朝丹禁晓，聳轡九衢春。","自愧湮沈者，隨軒未有因。"]', '诗', 'shi', '', NULL, '送閻侍御歸闕 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9314f4a8-71db-49fe-9a84-20ae8287fbd5', '甲子歲罷吉水縣過鍾陵時暮春維舟江渚謁柴太尉席上作', '甲子歲罷吉水縣過鍾陵时暮春維舟江渚謁柴太尉席上作', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["公侯延駐暫踟躕，況值風光三月初。","亂落杯盤花片小，靜籠池閣柳陰疎。","舟維南浦程雖阻，飲預西園興有餘。","却笑田家門下客，當時容易歎車魚。"]', '["公侯延駐暫踟躕，況值风光三月初。","亂落杯盤花片小，静籠池閣柳陰疎。","舟維南浦程雖阻，饮預西园兴有餘。","却笑田家门下客，當时容易歎车鱼。"]', '诗', 'shi', '', NULL, '甲子歲罷吉水縣過鍾陵時暮春維舟江渚謁柴太尉席上作 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('727b1536-893f-440f-ab98-f809fb1a177e', '海上春夕旅懷寄左偃', '海上春夕旅懷寄左偃', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["柳過清明絮亂飛，感時懷舊思悽悽。","月生樓閣雲初散，家在汀洲夢去迷。","髮白每慙清鑑啓，酒醒長怯子規啼。","北山高臥風騷客，安得同吟復杖藜。"]', '["柳過清明絮亂飞，感时懷旧思悽悽。","月生楼閣云初散，家在汀洲梦去迷。","髮白每慙清鑑啓，酒醒长怯子規啼。","北山高臥风騷客，安得同吟复杖藜。"]', '诗', 'shi', '', NULL, '海上春夕旅懷寄左偃 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5db77384-9b45-4120-82da-ac1179d31444', '江次維舟登古寺', '江次維舟登古寺', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["輟櫂因過古梵宮，荒涼門徑鏁苔茸。","綠陰滿地前朝樹，清韻含風後殿鐘。","童子縱慵眠壞榻，老僧耽話指諸峰。","吟餘却返來時路，迴首盤桓尚駐筇。"]', '["輟櫂因過古梵宮，荒涼门徑鏁苔茸。","綠陰满地前朝樹，清韻含风後殿鐘。","童子縱慵眠壞榻，老僧耽話指諸峰。","吟餘却返来时路，迴首盤桓尚駐筇。"]', '诗', 'shi', '', NULL, '江次維舟登古寺 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('853a3691-e5b2-4307-aa40-5047768a68c0', '春日招宋維先輩', '春日招宋維先輩', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["甕中竹葉今朝熟，鑑裏桃花昨日開。","爲報廣寒攀桂客，莫辭相訪共銜杯。"]', '["甕中竹葉今朝熟，鑑裏桃花昨日开。","爲報廣寒攀桂客，莫辞相訪共銜杯。"]', '诗', 'shi', '', NULL, '春日招宋維先輩 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c6068d4-682e-466c-9204-63b3e8347af7', '吹笛兒', '吹笛兒', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["隴頭休聽月明中，妙竹嘉音際會逢。","見爾樽前吹一首，令人重憶許雲封。"]', '["隴头休听月明中，妙竹嘉音際會逢。","见爾樽前吹一首，令人重憶許云封。"]', '诗', 'shi', '', NULL, '吹笛兒 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b2b74d8-6197-4b41-954c-fc158f20b7da', '所思', '所思', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["解珮當時在洛濱，悠悠疑是夢中身。","自從物外無消息，花謝鶯啼近十春。"]', '["解珮當时在洛濱，悠悠疑是梦中身。","自從物外無消息，花謝鶯啼近十春。"]', '诗', 'shi', '', NULL, '所思 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db8c0b69-51a6-490a-a192-71ff8e5f1fe1', '吉水縣酬夏侯秀才見寄', '吉水縣酬夏侯秀才见寄', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["啓鑑悠悠兩鬢蒼，病來心緒易淒涼。","知音不到吟還懶，鏁印開簾又夕陽。"]', '["啓鑑悠悠兩鬢蒼，病来心緒易淒涼。","知音不到吟還懶，鏁印开簾又夕陽。"]', '诗', 'shi', '', NULL, '吉水縣酬夏侯秀才見寄 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33d9e05f-2807-44d0-b346-c2a87e50f2e9', '和友人喜雪', '和友人喜雪', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["臘雪頻頻降，成堆不可除。","伴吟花莫並，銷瘴藥何如。","謝女詩成處，袁安睡起初。","深迷樵子徑，冷逼旅人居。","惹砌催罇俎，飄窗入簿書。","最宜樓上望，散亂滿空虛。"]', '["臘雪頻頻降，成堆不可除。","伴吟花莫並，銷瘴藥何如。","謝女诗成处，袁安睡起初。","深迷樵子徑，冷逼旅人居。","惹砌催罇俎，飄窗入簿书。","最宜楼上望，散亂满空虛。"]', '诗', 'shi', '', NULL, '和友人喜雪 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f46b503d-d2b0-4e14-aa02-32ca0932294e', '感事呈所知', '感事呈所知', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["競愛松筠翠，皆憐桃李芳。","如求濟世廣，桑柘願商量。"]', '["競愛松筠翠，皆怜桃李芳。","如求濟世廣，桑柘願商量。"]', '诗', 'shi', '', NULL, '感事呈所知 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31596998-4055-45fa-ab31-b5f4af167be1', '送汪濤', '送汪濤', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["知君別家後，不免淚霑襟。","芳草千里路，夕陽孤客心。","花飛當野渡，猨叫在煙岑。","霄漢知音在，何須恨陸沈。"]', '["知君別家後，不免泪霑襟。","芳草千里路，夕陽孤客心。","花飞當野渡，猨叫在煙岑。","霄漢知音在，何須恨陸沈。"]', '诗', 'shi', '', NULL, '送汪濤 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df99118c-649d-4a44-b9a6-2b1176f017c4', '言志寄劉鈞秀才', '言志寄劉鈞秀才', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["童稚親儒墨，時平喜道存。","酬身指書劒，賦命委乾坤。","秋爽鼓琴興，月清搜句魂。","與君同此志，終待至公論。"]', '["童稚親儒墨，时平喜道存。","酬身指书劒，賦命委乾坤。","秋爽鼓琴兴，月清搜句魂。","與君同此志，終待至公論。"]', '诗', 'shi', '', NULL, '言志寄劉鈞秀才 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54620419-d9b8-4b6f-86bc-52cf647dbfa5', '訪澄上人', '訪澄上人', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["尋師來靜境，神骨覺清涼。","一餉逢秋雨，相留坐竹堂。","石渠堆敗葉，莎砌咽寒螿。","話到南能旨，怡然萬慮忘。"]', '["尋師来静境，神骨覺清涼。","一餉逢秋雨，相留坐竹堂。","石渠堆敗葉，莎砌咽寒螿。","話到南能旨，怡然万慮忘。"]', '诗', 'shi', '', NULL, '訪澄上人 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a476cc7-abe5-44aa-9ce0-c476bd16ea9e', '經古寺', '經古寺', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["殿宇半隳摧，門臨野水開。","雲凝何代樹，草蔽此時臺。","遶塔堆黃葉，沿階積綠苔。","踟躕日將暮，棲鳥入巢來。"]', '["殿宇半隳摧，门臨野水开。","云凝何代樹，草蔽此时台。","遶塔堆黄葉，沿階積綠苔。","踟躕日將暮，棲鸟入巢来。"]', '诗', 'shi', '', NULL, '經古寺 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f28508b-402c-4d34-9a60-afa88d1d0448', '送王道士遊東海', '送王道士游东海', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["巨浸常牽夢，雲遊豈覺勞。","遙空收晚雨，虛閣看秋濤。","必若思三島，應須釣六鼇。","如通十洲去，誰信碧天高。"]', '["巨浸常牽梦，云游豈覺勞。","遙空收晚雨，虛閣看秋濤。","必若思三島，應須釣六鼇。","如通十洲去，誰信碧天高。"]', '诗', 'shi', '', NULL, '送王道士遊東海 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18849016-0cea-4634-95e2-b1f193bed42b', '貽青陽宰', '貽青陽宰', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["徵賦常登限，名山管最多。","吏閑民訟少，時得訪煙蘿。"]', '["徵賦常登限，名山管最多。","吏闲民訟少，时得訪煙蘿。"]', '诗', 'shi', '', NULL, '貽青陽宰 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fda2cb8-360e-47cd-ba79-3ed0ed55596f', '哭故主人陳太師', '哭故主人陳太師', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["十年孤跡寄侯門，入室升堂忝厚恩。","遊遍春郊隨茜斾，飲殘秋月待金尊。","車魚鄭重知難報，吐握周旋不可論。","長慟裴回逝川上，白楊蕭颯又黃昏。"]', '["十年孤跡寄侯门，入室升堂忝厚恩。","游遍春郊隨茜斾，饮殘秋月待金尊。","车鱼鄭重知难報，吐握周旋不可論。","长慟裴回逝川上，白楊蕭颯又黄昏。"]', '诗', 'shi', '', NULL, '哭故主人陳太師 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78ee78bf-2f15-41d6-8bf2-730f090339c8', '秋江夜泊寄劉鈞', '秋江夜泊寄劉鈞', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["萬里江山歛暮煙，旅情當此獨悠然。","沙汀月冷帆初卸，葦岸風多人未眠。","已聽漁翁歌別浦，更堪邊鴈過遙天。","與君共俟酬身了，結侶波中寄釣船。"]', '["万里江山歛暮煙，旅情當此独悠然。","沙汀月冷帆初卸，葦岸风多人未眠。","已听漁翁歌別浦，更堪邊鴈過遙天。","與君共俟酬身了，結侶波中寄釣船。"]', '诗', 'shi', '', NULL, '秋江夜泊寄劉鈞 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d490812-fde6-4481-9faf-e128f7a89ac1', '和潯陽宰感舊絕句五首 一', '和潯陽宰感旧絕句五首 一', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["追感古今情不已，竹軒閑取史書看。","欲親往哲無因見，空樹臨風襟袖寒。"]', '["追感古今情不已，竹軒闲取史书看。","欲親往哲無因见，空樹臨风襟袖寒。"]', '诗', 'shi', '', NULL, '和潯陽宰感舊絕句五首 一 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe3e8add-4dd6-45c6-bd61-cc32d28ba1ce', '和潯陽宰感舊絕句五首 二', '和潯陽宰感旧絕句五首 二', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["潯陽物景真難及，練瀉澄江最好看。","曾上虛樓吟倚檻，五峰擎雪照人寒。"]', '["潯陽物景真难及，練瀉澄江最好看。","曾上虛楼吟倚檻，五峰擎雪照人寒。"]', '诗', 'shi', '', NULL, '和潯陽宰感舊絕句五首 二 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b3755eb-acb6-4328-b154-29bff7623a82', '和潯陽宰感舊絕句五首 三', '和潯陽宰感旧絕句五首 三', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["園林春媚千花發，爛熳如將畫障看。","惟愛松筠多冷淡，青青偏稱雪霜寒。"]', '["园林春媚千花發，爛熳如將畫障看。","惟愛松筠多冷淡，青青偏稱雪霜寒。"]', '诗', 'shi', '', NULL, '和潯陽宰感舊絕句五首 三 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd0ad010-904e-4050-b908-f5c6a499c513', '和潯陽宰感舊絕句五首 四', '和潯陽宰感旧絕句五首 四', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["知君百里鳴琴處，公退千山盡日看。","政化有同風偃草，更將餘力拯孤寒。"]', '["知君百里鳴琴处，公退千山尽日看。","政化有同风偃草，更將餘力拯孤寒。"]', '诗', 'shi', '', NULL, '和潯陽宰感舊絕句五首 四 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95ea4bb9-b646-4bbf-b157-2ce6262ec7ac', '和潯陽宰感舊絕句五首 五', '和潯陽宰感旧絕句五首 五', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["昔歲尋芳忻得侶，江堤物景盡情看。","就中吟戀垂楊下，撼起啼鶯晚吹寒。"]', '["昔歲尋芳忻得侶，江堤物景尽情看。","就中吟戀垂楊下，撼起啼鶯晚吹寒。"]', '诗', 'shi', '', NULL, '和潯陽宰感舊絕句五首 五 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4469108d-a7d4-4ae7-8ccb-aba3eebc99d8', '哭柴郎中', '哭柴郎中', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["昔歲遭逢在海城，曾容孤跡奉雙旌。","酒邊不厭笙歌盛，花下只愁風雨生。","棊接山亭松影晚，吟陪月檻露華清。","音塵自此無因問，淚灑川波夕照明。"]', '["昔歲遭逢在海城，曾容孤跡奉雙旌。","酒邊不厭笙歌盛，花下只愁风雨生。","棊接山亭松影晚，吟陪月檻露华清。","音塵自此無因问，泪灑川波夕照明。"]', '诗', 'shi', '', NULL, '哭柴郎中 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d710214a-7722-4f6e-9fd2-b235e39165ab', '訪章禪老', '訪章禪老', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["比尋禪客叩禪機，澄却心如月在池。","松下偶然醒一夢，却成無語問吾師。"]', '["比尋禪客叩禪機，澄却心如月在池。","松下偶然醒一梦，却成無語问吾師。"]', '诗', 'shi', '', NULL, '訪章禪老 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('722ab4ce-3e4d-4f7e-bb43-2503529b8b71', '泊秋浦', '泊秋浦', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["葦岸風高宿鴈驚，維舟特地起鄉情。","漁兒隔水吹橫笛，半夜空江月正明。"]', '["葦岸风高宿鴈驚，維舟特地起乡情。","漁兒隔水吹橫笛，半夜空江月正明。"]', '诗', 'shi', '', NULL, '泊秋浦 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d3747b5-519a-4469-9a3a-40c28a9a8a78', '閑居言懷', '闲居言懷', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["未達難隨衆，從他俗所憎。","閑聽九秋雨，遠憶四明僧。","病後倦吟嘯，貧來疎友朋。","寂寥元合道，未必是無能。"]', '["未達难隨衆，從他俗所憎。","闲听九秋雨，远憶四明僧。","病後倦吟嘯，貧来疎友朋。","寂寥元合道，未必是無能。"]', '诗', 'shi', '', NULL, '閑居言懷 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8d47cae-9fb0-4f62-ab5e-28cb8247bd9c', '舟次彭澤', '舟次彭澤', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["飄泛經彭澤，扁舟思莫窮。","無人秋浪晚，一岸蓼花風。","鄉里夢漸遠，交親書未通。","今宵見圓月，難坐冷光中。"]', '["飄泛經彭澤，扁舟思莫窮。","無人秋浪晚，一岸蓼花风。","乡里梦漸远，交親书未通。","今宵见圓月，难坐冷光中。"]', '诗', 'shi', '', NULL, '舟次彭澤 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7928bb90-3612-46fc-aca9-b13dd08c1fb7', '宿鍾山知覺院', '宿鍾山知覺院', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["宿投林下寺，中夜覺神清。","磬罷僧初定，山空月又生。","籠燈吐冷豔，嵒樹起寒聲。","待曉紅塵裏，依前冒遠程。"]', '["宿投林下寺，中夜覺神清。","磬罷僧初定，山空月又生。","籠灯吐冷豔，嵒樹起寒声。","待晓紅塵裏，依前冒远程。"]', '诗', 'shi', '', NULL, '宿鍾山知覺院 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03e2546a-7b4c-4198-89aa-5918711a4670', '遊茅山二首 一', '游茅山二首 一', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["綠蘚深迎步，紅霞爛滿衣。","洞天應不遠，鸞鶴向人飛。"]', '["綠蘚深迎步，紅霞爛满衣。","洞天應不远，鸾鹤向人飞。"]', '诗', 'shi', '', NULL, '遊茅山二首 一 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa4b18fe-a8c4-4ccc-860f-46be39e45051', '遊茅山二首 二', '游茅山二首 二', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["茅許仙蹤在，煙霞一境清。","夷希何許叩，松徑月空明。"]', '["茅許仙蹤在，煙霞一境清。","夷希何許叩，松徑月空明。"]', '诗', 'shi', '', NULL, '遊茅山二首 二 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b5dfb4c-405b-4d50-992b-5f1d39a0875b', '鶴', '鹤', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["九臯羽翼下晴空，萬里心難駐玉籠。","清露滴時翹蘚徑，白雲開處唳松風。","歸當華表千年後，怨在瑤琴別操中。","好共靈龜作儔侶，十洲三島逐仙翁。"]', '["九臯羽翼下晴空，万里心难駐玉籠。","清露滴时翹蘚徑，白云开处唳松风。","归當华表千年後，怨在瑤琴別操中。","好共靈龟作儔侶，十洲三島逐仙翁。"]', '诗', 'shi', '', NULL, '鶴 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57f4c031-f473-443b-8045-f2072337fa5a', '暮春吟懷寄姚端先輩', '暮春吟懷寄姚端先輩', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["無奈詩魔旦夕生，更堪芳草滿長汀。","故人還爽花前約，新月又生江上亭。","莊夢斷時燈欲燼，蜀魂啼處酒初醒。","何時得見登龍客，隔却千山萬仞青。"]', '["無奈诗魔旦夕生，更堪芳草满长汀。","故人還爽花前約，新月又生江上亭。","莊梦斷时灯欲燼，蜀魂啼处酒初醒。","何时得见登龙客，隔却千山万仞青。"]', '诗', 'shi', '', NULL, '暮春吟懷寄姚端先輩 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2311b5d-9693-4efd-a83e-3f65bd33f57c', '送圓上人歸廬山', '送圓上人归廬山', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["蓮宮舊隱塵埃外，策杖臨風拂袖還。","踏雪獨尋青嶂下，聽猨重入白雲間。","蕭騷紅樹當門老，斑駮蒼苔鏁徑閑。","預想松軒夜禪處，虎溪圓月照空山。"]', '["蓮宮旧隐塵埃外，策杖臨风拂袖還。","踏雪独尋青嶂下，听猨重入白云间。","蕭騷紅樹當门老，斑駮蒼苔鏁徑闲。","預想松軒夜禪处，虎溪圓月照空山。"]', '诗', 'shi', '', NULL, '送圓上人歸廬山 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ac75fe4-a9c1-4597-84f1-d8213ace27c6', '送相里秀才之匡山國子監', '送相里秀才之匡山国子監', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["氣秀情閑杳莫羣，廬山遊去志求文。","已能探虎窮騷雅，又欲囊螢就典墳。","目豁乍窺千里浪，夢寒初宿五峰雲。","業成早赴春闈約，要使嘉名海內聞。"]', '["氣秀情闲杳莫羣，廬山游去志求文。","已能探虎窮騷雅，又欲囊螢就典墳。","目豁乍窺千里浪，梦寒初宿五峰云。","業成早赴春闈約，要使嘉名海內闻。"]', '诗', 'shi', '', NULL, '送相里秀才之匡山國子監 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8f2f950-17f5-47e3-8606-25731ff5ad44', '漁父二首 一', '漁父二首 一', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["偶向蘆花深處行，溪光山色晚來晴。","漁家開戶相迎接，稚子爭窺犬吠聲。"]', '["偶向蘆花深处行，溪光山色晚来晴。","漁家开戶相迎接，稚子爭窺犬吠声。"]', '诗', 'shi', '', NULL, '漁父二首 一 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d4adc40-5075-4ca3-99ec-a9652c1ce9a9', '漁父二首 二', '漁父二首 二', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["雪鬢衰髯白布袍，笑攜頳鯉換村醪。","慇懃留我宿溪上，釣艇歸來明月高。"]', '["雪鬢衰髯白布袍，笑携頳鯉換村醪。","慇懃留我宿溪上，釣艇归来明月高。"]', '诗', 'shi', '', NULL, '漁父二首 二 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac0cdaa2-80ba-4d84-8e20-4bb152c02d45', '旅次聞砧', '旅次闻砧', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["砧杵誰家夜搗衣，金風淅淅露微微。","月中獨坐不成寐，舊業經年未得歸。"]', '["砧杵誰家夜捣衣，金风淅淅露微微。","月中独坐不成寐，旧業經年未得归。"]', '诗', 'shi', '', NULL, '旅次聞砧 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c76d09f-9a06-4a16-b8bb-47bdc4fc24a9', '寄楊先生', '寄楊先生', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["仙翁別後無信，應共煙霞卜隣。","莫把壺中祕訣，輕傳塵裏遊人。","浮生日月自急，上境鶯花正春。","安得一招琴酒，與君共泛天津。"]', '["仙翁別後無信，應共煙霞卜隣。","莫把壺中祕訣，轻傳塵裏游人。","浮生日月自急，上境鶯花正春。","安得一招琴酒，與君共泛天津。"]', '诗', 'shi', '', NULL, '寄楊先生 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e170b995-4daa-4a6b-bbfa-7591ec542d5e', '對酒招陳昭用', '对酒招陳昭用', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["花開葉落堪悲，似水年光暗移。","身世都如夢役，是非空使神疲。","良圖有分終在，所欲無勞妄思。","幸有一壺清酒，且來閑語希夷。"]', '["花开葉落堪悲，似水年光暗移。","身世都如梦役，是非空使神疲。","良圖有分終在，所欲無勞妄思。","幸有一壺清酒，且来闲語希夷。"]', '诗', 'shi', '', NULL, '對酒招陳昭用 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d79bfaa4-ee69-4048-b49d-87678256b335', '旅夜聞笛', '旅夜闻笛', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["長笛起誰家，秋涼夜漏賒。","一聲來枕上，孤客在天涯。","木末風微動，窗前月漸斜。","暗牽詩思苦，不獨落梅花。"]', '["长笛起誰家，秋涼夜漏賒。","一声来枕上，孤客在天涯。","木末风微动，窗前月漸斜。","暗牽诗思苦，不独落梅花。"]', '诗', 'shi', '', NULL, '旅夜聞笛 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8b96cec-a734-461a-8892-c36de2ed30fb', '送紹明上人之毘陵', '送紹明上人之毘陵', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["忽起毘陵念，飄然不可留。","聽蟬離古寺，攜錫上扁舟。","月出沙汀冷，風高葦岸秋。","回期端的否，千里路悠悠。"]', '["忽起毘陵念，飄然不可留。","听蟬離古寺，携錫上扁舟。","月出沙汀冷，风高葦岸秋。","回期端的否，千里路悠悠。"]', '诗', 'shi', '', NULL, '送紹明上人之毘陵 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69890563-827a-4195-af62-37112cc6e1fc', '再到山陽尋故人不遇二首 一', '再到山陽尋故人不遇二首 一', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["維舟登野岸，因訪故人居。","亂後知何處，荆榛匝弊廬。"]', '["維舟登野岸，因訪故人居。","亂後知何处，荆榛匝弊廬。"]', '诗', 'shi', '', NULL, '再到山陽尋故人不遇二首 一 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5f56f0a-0020-447c-b3d8-c948215ad02c', '再到山陽尋故人不遇二首 二', '再到山陽尋故人不遇二首 二', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["欲問當年事，耕人都不知。","空餘堤上柳，依舊自垂絲。"]', '["欲问當年事，耕人都不知。","空餘堤上柳，依旧自垂絲。"]', '诗', 'shi', '', NULL, '再到山陽尋故人不遇二首 二 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff573e8f-c78d-46de-b966-cde05949c91e', '寄廬山簡寂觀重道者', '寄廬山簡寂观重道者', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["憶昔採芝廬岳頂，清宮常接絳霄人。","玉書閑展石樓曉，瑤瑟醉彈琪樹春。","惟恨仙桃遲結實，不憂滄海易成塵。","似醒一夢歸凡世，空向彤霞寄夢頻。"]', '["憶昔採芝廬岳頂，清宮常接絳霄人。","玉书闲展石楼晓，瑤瑟醉彈琪樹春。","惟恨仙桃遲結實，不憂滄海易成塵。","似醒一梦归凡世，空向彤霞寄梦頻。"]', '诗', 'shi', '', NULL, '寄廬山簡寂觀重道者 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b508fd6-df55-44c1-b913-fa556273b2b4', '思湓渚舊居', '思湓渚旧居', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["昔歲曾居湓水頭，草堂吟嘯興何幽。","迎僧常踏竹間蘚，愛月獨登溪上樓。","寒翠入簷嵐岫曉，冷聲縈枕野泉秋。","從拘宦路無由到，昨夜分明夢去遊。"]', '["昔歲曾居湓水头，草堂吟嘯兴何幽。","迎僧常踏竹间蘚，愛月独登溪上楼。","寒翠入簷嵐岫晓，冷声縈枕野泉秋。","從拘宦路無由到，昨夜分明梦去游。"]', '诗', 'shi', '', NULL, '思湓渚舊居 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d13625c5-0a52-4e07-85d3-ea6941a4fef2', '思朐陽春遊感舊寄柴司徒五首 一', '思朐陽春游感旧寄柴司徒五首 一', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["王孫昔日甚相親，共賞西園正媚春。","醉臥如茵芳草上，覺來花月影籠身。"]', '["王孫昔日甚相親，共賞西园正媚春。","醉臥如茵芳草上，覺来花月影籠身。"]', '诗', 'shi', '', NULL, '思朐陽春遊感舊寄柴司徒五首 一 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bf88eb6-51a5-4d5b-9bdb-33968ea9e0d2', '思朐陽春遊感舊寄柴司徒五首 二', '思朐陽春游感旧寄柴司徒五首 二', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["煙鋪芳草正綿綿，藉草傳杯似列仙。","暫輟笙歌且聯句，含毫花下破香牋。"]', '["煙鋪芳草正綿綿，藉草傳杯似列仙。","暫輟笙歌且聯句，含毫花下破香牋。"]', '诗', 'shi', '', NULL, '思朐陽春遊感舊寄柴司徒五首 二 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f31be9f0-026c-4786-93ce-787b214f240b', '思朐陽春遊感舊寄柴司徒五首 三', '思朐陽春游感旧寄柴司徒五首 三', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["南陌風和舞蝶狂，惜春公子戀斜陽。","高歌飲罷將迴轡，衣上花兼百草香。"]', '["南陌风和舞蝶狂，惜春公子戀斜陽。","高歌饮罷將迴轡，衣上花兼百草香。"]', '诗', 'shi', '', NULL, '思朐陽春遊感舊寄柴司徒五首 三 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23131d8f-266b-46b0-807f-ecdc1e11ecec', '思朐陽春遊感舊寄柴司徒五首 四', '思朐陽春游感旧寄柴司徒五首 四', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["春郊飲散暮煙收，却引絲簧上翠樓。","紅袖歌長金斝亂，銀蟾飛出海東頭。"]', '["春郊饮散暮煙收，却引絲簧上翠楼。","紅袖歌长金斝亂，銀蟾飞出海东头。"]', '诗', 'shi', '', NULL, '思朐陽春遊感舊寄柴司徒五首 四 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1edd9186-6010-47e2-a17d-cfeacd8c0e2d', '思朐陽春遊感舊寄柴司徒五首 五', '思朐陽春游感旧寄柴司徒五首 五', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["昔年常接五陵狂，洪飲花間數十場。","別後或驚如夢覺，音塵難問水茫茫。"]', '["昔年常接五陵狂，洪饮花间數十場。","別後或驚如梦覺，音塵难问水茫茫。"]', '诗', 'shi', '', NULL, '思朐陽春遊感舊寄柴司徒五首 五 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36a1d100-fa9e-42e1-b803-eabbdb39e865', '泉', '泉', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["潺潺青嶂底，來處一何長。","漱石苔痕滑，侵松鶴夢涼。","泛花穿竹塢，瀉月下蓮塘。","想得歸何處，天涯助渺茫。"]', '["潺潺青嶂底，来处一何长。","漱石苔痕滑，侵松鹤梦涼。","泛花穿竹塢，瀉月下蓮塘。","想得归何处，天涯助渺茫。"]', '诗', 'shi', '', NULL, '泉 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d4f3f56-0ecf-44c1-90a2-5b10653eaa0f', '題徐五教池亭', '題徐五教池亭', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["多士池塘好，塵中景恐無。","年來養鷗鷺，夢不去江湖。","泉脈通深澗，風聲起短蘆。","驚魚跳藻荇，戲蝶上菰蒲。","泛泛容漁艇，閑閑載酒壺。","漲痕山雨過，翠積岸苔鋪。","花影沈波底，煙光入座隅。","曉香憐杜若，夜浸愛[蟾]蜍。","步逸心難厭，看吟興不辜。","憑君命奇筆，爲我寫成圖。"]', '["多士池塘好，塵中景恐無。","年来養鷗鷺，梦不去江湖。","泉脈通深澗，风声起短蘆。","驚鱼跳藻荇，戲蝶上菰蒲。","泛泛容漁艇，闲闲載酒壺。","漲痕山雨過，翠積岸苔鋪。","花影沈波底，煙光入座隅。","晓香怜杜若，夜浸愛[蟾]蜍。","步逸心难厭，看吟兴不辜。","憑君命奇笔，爲我寫成圖。"]', '诗', 'shi', '', NULL, '題徐五教池亭 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3dabb46-25b6-4fc8-b85d-a9bc688dd4bb', '遙賦義興潛泉', '遙賦義兴潛泉', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["見說靈泉好，潺湲興莫窮。","誰當秋霽後，獨聽月明中。","濺石苔花潤，隨流木葉紅。","何當化霖雨，濟物顯殊功。"]', '["见说靈泉好，潺湲兴莫窮。","誰當秋霽後，独听月明中。","濺石苔花潤，隨流木葉紅。","何當化霖雨，濟物显殊功。"]', '诗', 'shi', '', NULL, '遙賦義興潛泉 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0aec44a0-f998-4f66-a393-dfbb48ed866c', '和毘陵尉曹昭用見寄', '和毘陵尉曹昭用见寄', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["決獄多餘暇，冥搜萬家空。","卷簾疎雨後，鏁印夕陽中。","還往多名士，編題尚古風。","宦途知此味，能有幾人同。"]', '["決獄多餘暇，冥搜万家空。","卷簾疎雨後，鏁印夕陽中。","還往多名士，編題尚古风。","宦途知此味，能有幾人同。"]', '诗', 'shi', '', NULL, '和毘陵尉曹昭用見寄 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50a7c838-57fd-48ae-b898-e77c81bd74ac', '梅花', '梅花', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["羣木方憎雪，開花長在先。","流鶯與舞蝶，不見許因緣。"]', '["羣木方憎雪，开花长在先。","流鶯與舞蝶，不见許因緣。"]', '诗', 'shi', '', NULL, '梅花 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cbadf48-ccd6-4a78-a930-689af07509c6', '舟次吉水逢蔡文慶秀才', '舟次吉水逢蔡文慶秀才', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["別後音塵斷，相逢又共吟。","雪霜今日鬢，煙月舊時心。","艤櫂夕陽在，聽鴻秋色深。","一尊開口笑，不必話升沈。"]', '["別後音塵斷，相逢又共吟。","雪霜今日鬢，煙月旧时心。","艤櫂夕陽在，听鴻秋色深。","一尊开口笑，不必話升沈。"]', '诗', 'shi', '', NULL, '舟次吉水逢蔡文慶秀才 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a2d1f99-7e58-424b-8aa5-9a3d734d595e', '新喻縣偶寄彭仁正字', '新喻縣偶寄彭仁正字', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["經年離象魏，孤宦在南荒。","酒醒公齋冷，雨多歸夢長。","志難酬國澤，術欠致民康。","吾子應相笑，區區道未光。"]', '["經年離象魏，孤宦在南荒。","酒醒公斋冷，雨多归梦长。","志难酬国澤，術欠致民康。","吾子應相笑，區區道未光。"]', '诗', 'shi', '', NULL, '新喻縣偶寄彭仁正字 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('119a47d7-a249-404e-a9ec-774210b35e8e', '和彭正字喜雪見寄', '和彭正字喜雪见寄', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["千門忻應瑞，偏稱上樓看。","密灑虛窗曉，狂飄大野寒。","園深宜竹樹，簾卷洽杯盤。","已作豐年兆，黎民意盡安。"]', '["千门忻應瑞，偏稱上楼看。","密灑虛窗晓，狂飄大野寒。","园深宜竹樹，簾卷洽杯盤。","已作豐年兆，黎民意尽安。"]', '诗', 'shi', '', NULL, '和彭正字喜雪見寄 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e8cb722-01dc-46fd-8325-eaf5e8d6c24d', '海上和柴軍使清明書事', '海上和柴軍使清明书事', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["清明時節好煙光，英傑高吟興味長。","捧日即應還禁衛，當春何惜醉朐陽。","千山過雨難藏翠，百卉臨風不藉香。","却是旅人悽屑甚，夜來魂夢到家鄉。"]', '["清明时節好煙光，英傑高吟兴味长。","捧日即應還禁衛，當春何惜醉朐陽。","千山過雨难藏翠，百卉臨风不藉香。","却是旅人悽屑甚，夜来魂梦到家乡。"]', '诗', 'shi', '', NULL, '海上和柴軍使清明書事 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e59ad78-3bb8-448e-8b17-350927114015', '壬申歲承命之任淦陽再過廬山國學感舊寄劉鈞明府', '壬申歲承命之任淦陽再過廬山国学感旧寄劉鈞明府', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["三十年前共苦辛，囊螢曾寄此煙岑。","讀書燈暗嫌雲重，搜句石平憐蘚深。","各歷宦途悲聚散，幾看時輩或浮沈。","再來物景還依舊，風冷松高猨狖吟。"]', '["三十年前共苦辛，囊螢曾寄此煙岑。","读书灯暗嫌云重，搜句石平怜蘚深。","各歷宦途悲聚散，幾看时輩或浮沈。","再来物景還依旧，风冷松高猨狖吟。"]', '诗', 'shi', '', NULL, '壬申歲承命之任淦陽再過廬山國學感舊寄劉鈞明府 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('246652fd-96b0-438b-8e1e-af4d3e24fdb4', '留題胡參卿秀才幽居', '留題胡參卿秀才幽居', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["竹蔭亭除蘚色濃，道心安逸寂寥中。","扣門時有棲禪客，灑酒多招採藥翁。","江近好聽菱芡雨，徑香偏愛蕙蘭風。","我慙名宦猶拘束，脫屣心情未得同。"]', '["竹蔭亭除蘚色濃，道心安逸寂寥中。","扣门时有棲禪客，灑酒多招採藥翁。","江近好听菱芡雨，徑香偏愛蕙蘭风。","我慙名宦猶拘束，脫屣心情未得同。"]', '诗', 'shi', '', NULL, '留題胡參卿秀才幽居 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d41ff93f-ae5f-4fe7-b099-b937ad850eb2', '放鷺鷥', '放鷺鷥', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["池塘多謝久淹留，長得霜翎放自由。","好去蒹葭深處宿，月明應認舊江秋。"]', '["池塘多謝久淹留，长得霜翎放自由。","好去蒹葭深处宿，月明應認旧江秋。"]', '诗', 'shi', '', NULL, '放鷺鷥 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('262acfe8-c0c8-49b4-bf63-6f9223c387d9', '柳絮', '柳絮', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["年年二月暮，散亂雜飛花。","雨過微風起，狂飄千萬家。"]', '["年年二月暮，散亂杂飞花。","雨過微风起，狂飄千万家。"]', '诗', 'shi', '', NULL, '柳絮 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d32694f9-eca2-4c35-a7fc-58ec5def8870', '早春', '早春', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["一種和風至，千花未放妍。","草心並柳眼，長是被恩先。"]', '["一種和风至，千花未放妍。","草心並柳眼，长是被恩先。"]', '诗', 'shi', '', NULL, '早春 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ee9ba83-e38d-4778-92a2-d564a109cefe', '春雲', '春云', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["陰去爲膏澤，晴來媚曉空。","無心亦無滯，舒卷在東風。"]', '["陰去爲膏澤，晴来媚晓空。","無心亦無滯，舒卷在东风。"]', '诗', 'shi', '', NULL, '春雲 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90289808-3ac4-45cc-8b5b-7f4ec5adbfaf', '送姚端秀才遊毘陵', '送姚端秀才游毘陵', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["毘陵嘉景太湖邊，才子經遊稱少年。","風弄輕帘沽酒市，月明紅袖採蓮船。","若耶罨畫應相似，越岫吳峰盡接連。","此去高吟須早返，廣寒丹桂莫遷延。"]', '["毘陵嘉景太湖邊，才子經游稱少年。","风弄轻帘沽酒市，月明紅袖採蓮船。","若耶罨畫應相似，越岫吳峰尽接連。","此去高吟須早返，廣寒丹桂莫遷延。"]', '诗', 'shi', '', NULL, '送姚端秀才遊毘陵 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c18a3b52-78c8-4bfb-ae9d-f0179b5f7c29', '和朐陽載筆魯裕見寄', '和朐陽載笔魯裕见寄', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["燕臺多事每開顏，相許論交淡薄間。","飲興共憐芳草岸，吟情同愛夕陽山。","露濃小徑蛩聲咽，月冷空庭竹影閑。","何事此時攀憶甚，與君俱是別鄉關。"]', '["燕台多事每开顏，相許論交淡薄间。","饮兴共怜芳草岸，吟情同愛夕陽山。","露濃小徑蛩声咽，月冷空庭竹影闲。","何事此时攀憶甚，與君俱是別乡关。"]', '诗', 'shi', '', NULL, '和朐陽載筆魯裕見寄 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f701b4c0-751d-432e-a716-d04b00b9d5d1', '敘吟二首 一', '敘吟二首 一', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["往哲搜羅妙入神，隋珠和璧未爲珍。","而今所得慙難繼，謬向平生著苦辛。"]', '["往哲搜羅妙入神，隋珠和璧未爲珍。","而今所得慙难繼，謬向平生著苦辛。"]', '诗', 'shi', '', NULL, '敘吟二首 一 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d30cf87-ce23-4af4-8f75-beeb2e41eae0', '敘吟二首 二', '敘吟二首 二', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["成僻成魔二雅中，每逢知己是亨通。","言之無罪終難厭，欲把風騷繼古風。"]', '["成僻成魔二雅中，每逢知己是亨通。","言之無罪終难厭，欲把风騷繼古风。"]', '诗', 'shi', '', NULL, '敘吟二首 二 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0db1fb7c-b12a-4269-aec5-23a22b3b4519', '貽毘陵正勤禪院奉長老', '貽毘陵正勤禪院奉长老', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["隨緣駐瓶錫，心已悟無生。","默坐煙霞散，閑觀水月明。","竹深風倍冷，堂迥磬偏清。","願作傳燈者，忘言學淨名。"]', '["隨緣駐瓶錫，心已悟無生。","默坐煙霞散，闲观水月明。","竹深风倍冷，堂迥磬偏清。","願作傳灯者，忘言学淨名。"]', '诗', 'shi', '', NULL, '貽毘陵正勤禪院奉長老 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('423942ed-0dd2-4d97-b825-5e517875f83b', '冬日書懷寄惟真大師', '冬日书懷寄惟真大師', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["自別吾師後，風騷道甚孤。","雪霜侵鬢髮，音信隔江湖。","擾擾悲時世，悠悠役夢途。","向公期盡節，多病怕傾壺。","賤跡雖慙滯，幽情忍使辜。","詩成天外句，棊覆夜中圖。","落壁燈花碎，飄窗雪片麤。","煮茶燒栗興，早晚復圍爐。"]', '["自別吾師後，风騷道甚孤。","雪霜侵鬢髮，音信隔江湖。","擾擾悲时世，悠悠役梦途。","向公期尽節，多病怕傾壺。","賤跡雖慙滯，幽情忍使辜。","诗成天外句，棊覆夜中圖。","落壁灯花碎，飄窗雪片麤。","煮茶燒栗兴，早晚复圍爐。"]', '诗', 'shi', '', NULL, '冬日書懷寄惟真大師 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b77dbf7e-94c1-4c72-9ebd-006acec08388', '獻中書潘舍人', '獻中书潘舍人', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["運叶半千數，天鍾許國臣。","鵬霄開羽翼，鳳闕演絲綸。","顧問當清夜，從容向紫宸。","立言成雅誥，正意敘彝倫。","樸素偕前哲，馨香越搢紳。","褒辭光萬代，優旨重千鈞。","公退誰堪接，清閑道是鄰。","世間身屬幻，物外意通津。","弔往兼春夢，文高賦復新。","琴彈三峽水，屏畫十洲春。","庭冷鋪苔色，池寒浸月輪。","竹風來枕簟，藥氣上衣巾。","茶譜傳溪叟，棊經受羽人。","清虛雖得趣，獻替不妨陳。","杞梓呈才後，神仙入侍頻。","孤寒皆有賴，中外亦同忻。","有士曾多難，無門得望塵。","忙忙罹險阻，往往耗精神。","尋果巢枝願，終全負米身。","[遭]逢敦孝治，蹇塞值通津。","最慶清朝祿，還霑白髮親。","甘柔心既遂，虛薄報何因。","遠宦聯綿歷，卑棲夙夜勤。","良時空愛惜，末路每悲辛。","骨立駒猶病，顏凋女尚貧。","而今諧顧遇，尺蠖願求伸。"]', '["運叶半千數，天鍾許国臣。","鵬霄开羽翼，鳳闕演絲綸。","顧问當清夜，從容向紫宸。","立言成雅誥，正意敘彝倫。","樸素偕前哲，馨香越搢紳。","褒辞光万代，優旨重千鈞。","公退誰堪接，清闲道是鄰。","世间身屬幻，物外意通津。","弔往兼春梦，文高賦复新。","琴彈三峽水，屏畫十洲春。","庭冷鋪苔色，池寒浸月輪。","竹风来枕簟，藥氣上衣巾。","茶譜傳溪叟，棊經受羽人。","清虛雖得趣，獻替不妨陳。","杞梓呈才後，神仙入侍頻。","孤寒皆有賴，中外亦同忻。","有士曾多难，無门得望塵。","忙忙罹險阻，往往耗精神。","尋果巢枝願，終全負米身。","[遭]逢敦孝治，蹇塞值通津。","最慶清朝祿，還霑白髮親。","甘柔心既遂，虛薄報何因。","远宦聯綿歷，卑棲夙夜勤。","良时空愛惜，末路每悲辛。","骨立駒猶病，顏凋女尚貧。","而今諧顧遇，尺蠖願求伸。"]', '诗', 'shi', '', NULL, '獻中書潘舍人 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ff2dd5d-f454-4cf7-ba55-547b4821fe1b', '早春左省寓直', '早春左省寓直', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["旭景鸞臺上，微雲象闕間。","時清政事少，日永直官閑。","遠籟飛簫管，零冰響珮環。","終軍年二十，默坐叩玄關。"]', '["旭景鸾台上，微云象闕间。","时清政事少，日永直官闲。","远籟飞簫管，零冰响珮环。","終軍年二十，默坐叩玄关。"]', '诗', 'shi', '', NULL, '早春左省寓直 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6472e5e-a2a3-4ac8-bbfe-bd6e669e510d', '寒食宿陳公塘上', '寒食宿陳公塘上', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["垂楊界官道，茅屋倚高坡。","月下春塘水，風中牧豎歌。","折花閑立久，對酒遠情多。","今夜孤亭夢，悠揚奈爾何。"]', '["垂楊界官道，茅屋倚高坡。","月下春塘水，风中牧豎歌。","折花闲立久，对酒远情多。","今夜孤亭梦，悠揚奈爾何。"]', '诗', 'shi', '', NULL, '寒食宿陳公塘上 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44b117fc-8d76-4428-8edc-191f2e89a093', '將去廣陵別史員外南齋', '將去廣陵別史員外南斋', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["家聲曾與金張輩，官署今居何宋間。","起得高齋臨靜曲，種成奇樹學他山。","鴛鸞終日同醒醉，蘿薜常時共往還。","賤子今朝獨南去，不堪迴首望清閑。"]', '["家声曾與金張輩，官署今居何宋间。","起得高斋臨静曲，種成奇樹学他山。","鴛鸾終日同醒醉，蘿薜常时共往還。","賤子今朝独南去，不堪迴首望清闲。"]', '诗', 'shi', '', NULL, '將去廣陵別史員外南齋 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2cd257f-3540-43c1-8a83-d4bee46ccce2', '將過江題白沙館', '將過江題白沙館', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["少長在維揚，依然認故鄉。","金陵佳麗地，不道少風光。","稍望吳臺遠，行登楚塞長。","殷勤語江嶺，歸夢莫相妨。"]', '["少长在維揚，依然認故乡。","金陵佳丽地，不道少风光。","稍望吳台远，行登楚塞长。","殷勤語江嶺，归梦莫相妨。"]', '诗', 'shi', '', NULL, '將過江題白沙館 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84ff2c04-2674-452c-a4d2-1ec9164614b4', '登甘露寺北望', '登甘露寺北望', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["京口潮來曲岸平，海門風起浪花生。","人行沙上見日影，舟過江中聞櫓聲。","芳草遠迷楊子渡，宿煙深映廣陵城。","游人鄉思應如橘，相望須含兩地情。"]', '["京口潮来曲岸平，海门风起浪花生。","人行沙上见日影，舟過江中闻櫓声。","芳草远迷楊子渡，宿煙深映廣陵城。","游人乡思應如橘，相望須含兩地情。"]', '诗', 'shi', '', NULL, '登甘露寺北望 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a26487e-20e8-4084-bb08-560b5384723f', '山路花', '山路花', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["不共垂楊映綺寮，倚山臨路自嬌饒。","游人過去知香遠，谷鳥飛來見影搖。","半隔煙嵐遙隱隱，可堪風雨暮蕭蕭。","城中春色還如此，幾處笙歌按舞腰。"]', '["不共垂楊映綺寮，倚山臨路自嬌饒。","游人過去知香远，谷鸟飞来见影搖。","半隔煙嵐遙隐隐，可堪风雨暮蕭蕭。","城中春色還如此，幾处笙歌按舞腰。"]', '诗', 'shi', '', NULL, '山路花 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('031a3154-5c09-49a5-b3cc-1c96465ca07b', '京口江際弄水', '京口江際弄水', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["退公求靜獨臨川，楊子江南二月天。","百尺翠屏甘露閣，數帆晴日海門船。","波澄瀨石寒如玉，草接汀蘋綠似煙。","安得乘槎更東去，十洲風外弄潺湲。"]', '["退公求静独臨川，楊子江南二月天。","百尺翠屏甘露閣，數帆晴日海门船。","波澄瀨石寒如玉，草接汀蘋綠似煙。","安得乘槎更东去，十洲风外弄潺湲。"]', '诗', 'shi', '', NULL, '京口江際弄水 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fe76500-573b-44e3-bb72-0f3f3747a49f', '早春旬假獨直寄江舍人', '早春旬假独直寄江舍人', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["省署皆歸沐，西垣公事稀。","詠詩前砌立，聽漏向申歸。","遠思風醒酒，餘寒雨濕衣。","春光已堪探，芝蓋共誰飛。"]', '["省署皆归沐，西垣公事稀。","詠诗前砌立，听漏向申归。","远思风醒酒，餘寒雨濕衣。","春光已堪探，芝蓋共誰飞。"]', '诗', 'shi', '', NULL, '早春旬假獨直寄江舍人 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbd77ce3-6700-4709-a829-33ec8afa57d0', '從駕東幸呈諸公', '從駕东幸呈諸公', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["吳公臺下舊京城，曾掩衡門過十春。","別後不知新景象，信來空問故交親。","宦游京口無高興，習隱鍾山限俗塵。","今日喜爲華表鶴，況陪鵷鷺免迷津。"]', '["吳公台下旧京城，曾掩衡门過十春。","別後不知新景象，信来空问故交親。","宦游京口無高兴，習隐鍾山限俗塵。","今日喜爲华表鹤，況陪鵷鷺免迷津。"]', '诗', 'shi', '', NULL, '從駕東幸呈諸公 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02c923a2-c7b4-4464-a46c-e5e4a1156933', '重游木蘭亭', '重游木蘭亭', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["繚繞長隄帶碧潯，昔年游此尚青衿。","蘭橈破浪城陰直，玉勒穿花苑樹深。","宦路塵埃成久別，仙家風景有誰尋。","那知年長多情後，重憑欄干一獨吟。"]', '["繚繞长隄带碧潯，昔年游此尚青衿。","蘭橈破浪城陰直，玉勒穿花苑樹深。","宦路塵埃成久別，仙家风景有誰尋。","那知年长多情後，重憑欄干一独吟。"]', '诗', 'shi', '', NULL, '重游木蘭亭 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17a9bfce-2af3-4f2a-b5ca-2469b652665d', '賦得綵鷰', '賦得綵鷰', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["縷綵成飛鷰，迎和啓蟄時。","翠翹生玉指，繡羽拂文楣。","詎費銜泥力，無勞剪爪期。","化工今在此，翻怪社來遲。"]', '["縷綵成飞鷰，迎和啓蟄时。","翠翹生玉指，繡羽拂文楣。","詎費銜泥力，無勞剪爪期。","化工今在此，翻怪社来遲。"]', '诗', 'shi', '', NULL, '賦得綵鷰 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1c3a512-1818-440c-b125-074e2098cfc6', '送魏舍人仲甫爲蘄州判官', '送魏舍人仲甫爲蘄州判官', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["從事蘄春興自長，蘄人應識紫薇郎。","山資足後拋名路，蒓菜秋來憶故鄉。","以道卷舒猶自適，臨戎談笑固無妨。","如聞郡閣吹橫笛，時望青谿憶野王。"]', '["從事蘄春兴自长，蘄人應識紫薇郎。","山資足後拋名路，蒓菜秋来憶故乡。","以道卷舒猶自適，臨戎談笑固無妨。","如闻郡閣吹橫笛，时望青谿憶野王。"]', '诗', 'shi', '', NULL, '送魏舍人仲甫爲蘄州判官 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d44a4471-c9de-4c67-b98c-87f0dbed45fc', '題殷舍人宅木芙蓉', '題殷舍人宅木芙蓉', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["憐君庭下木芙蓉，嫋嫋纖枝淡淡紅。","曉吐芳心零宿露，晚搖嬌影媚清風。","似含情態愁秋雨，暗減馨香借菊叢。","默飲數盃應未稱，不知歌管與誰同。"]', '["怜君庭下木芙蓉，嫋嫋纖枝淡淡紅。","晓吐芳心零宿露，晚搖嬌影媚清风。","似含情態愁秋雨，暗減馨香借菊叢。","默饮數盃應未稱，不知歌管與誰同。"]', '诗', 'shi', '', NULL, '題殷舍人宅木芙蓉 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce5c311d-01fa-4a30-aaba-466271c2c6f4', '送史館高員外使嶺南', '送史館高員外使嶺南', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["東觀時閑暇，還修喻蜀書。","雙旌馳縣道，百越從軺車。","桂蠹晨餐罷，貪泉訪古初。","春江多好景，莫使醉吟疎。"]', '["东观时闲暇，還修喻蜀书。","雙旌驰縣道，百越從軺车。","桂蠹晨餐罷，貪泉訪古初。","春江多好景，莫使醉吟疎。"]', '诗', 'shi', '', NULL, '送史館高員外使嶺南 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7498113-016b-4dfc-92ad-67618db85edf', '春日紫巖山期客不至', '春日紫巖山期客不至', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["郊外春華好，人家帶碧谿。","淺莎藏鴨戲，輕靄隔雞啼。","掩映紅桃谷，夤緣翠柳堤。","王孫竟不至，芳草自萋萋。"]', '["郊外春华好，人家带碧谿。","淺莎藏鴨戲，轻靄隔雞啼。","掩映紅桃谷，夤緣翠柳堤。","王孫竟不至，芳草自萋萋。"]', '诗', 'shi', '', NULL, '春日紫巖山期客不至 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91d74810-0d3e-45d1-90aa-806aa8445b3c', '宿蔣帝廟明日遊山南諸寺', '宿蔣帝廟明日游山南諸寺', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["便返城闉尚未甘，更從山北到山南。","花枝似雪春雖半，桂魄如眉日始三。","松蓋遮門寒黯黯，柳絲妨路翠𣯶𣯶。","登臨莫怪偏留戀，游宦多年事事諳。"]', '["便返城闉尚未甘，更從山北到山南。","花枝似雪春雖半，桂魄如眉日始三。","松蓋遮门寒黯黯，柳絲妨路翠𣯶𣯶。","登臨莫怪偏留戀，游宦多年事事諳。"]', '诗', 'shi', '', NULL, '宿蔣帝廟明日遊山南諸寺 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28ddc2ee-b797-4756-af2b-f7bf12dd6798', '賦得有所思', '賦得有所思', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["所思何在杳難尋，路遠山長水復深。","衰草滿庭空佇立，清風吹袂更長吟。","忘情好醉青田酒，寄恨宜調綠綺琴。","落日鮮雲偏聚散，可能知我獨傷心。"]', '["所思何在杳难尋，路远山长水复深。","衰草满庭空佇立，清风吹袂更长吟。","忘情好醉青田酒，寄恨宜調綠綺琴。","落日鲜云偏聚散，可能知我独傷心。"]', '诗', 'shi', '', NULL, '賦得有所思 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4208d61f-284b-475e-be78-848aee139efe', '贈王貞素先生', '贈王貞素先生', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["先生嘗已佩真形，紺髮朱顏骨氣清。","道祕未傳鴻寶術，院深時聽步虛聲。","遼東幾度悲城郭，吳市終應變姓名。","三十六天皆有籍，他年何處問歸程。"]', '["先生嘗已佩真形，紺髮朱顏骨氣清。","道祕未傳鴻寶術，院深时听步虛声。","遼东幾度悲城郭，吳市終應变姓名。","三十六天皆有籍，他年何处问归程。"]', '诗', 'shi', '', NULL, '贈王貞素先生 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4663ace2-fe92-448a-a9fb-d69d3efaf494', '春夜月', '春夜月', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["幽人春望本多情，況是花繁月正明。","竟夕無言亦無寐，繞堦芳草影隨行。"]', '["幽人春望本多情，況是花繁月正明。","竟夕無言亦無寐，繞堦芳草影隨行。"]', '诗', 'shi', '', NULL, '春夜月 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76d58a80-1571-4db2-ba6f-841c13efe832', '愛敬寺有老僧嘗游長安言秦雍間事歷歷可聽因贈此詩兼示同行客', '愛敬寺有老僧嘗游长安言秦雍间事歷歷可听因贈此诗兼示同行客', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["白首棲禪者，嘗談灞滻游。","能令過江客，偏起失鄉愁。","室倚桃花崦，門臨杜若洲。","城中無此景，將子剩淹留。"]', '["白首棲禪者，嘗談灞滻游。","能令過江客，偏起失乡愁。","室倚桃花崦，门臨杜若洲。","城中無此景，將子剩淹留。"]', '诗', 'shi', '', NULL, '愛敬寺有老僧嘗游長安言秦雍間事歷歷可聽因贈此詩兼示同行客 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e1cca4b-fd18-4434-af1b-8591054bb7a2', '游蔣山題辛夷花寄陳奉禮', '游蔣山題辛夷花寄陳奉禮', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["今歲游山已恨遲，山中仍喜見辛夷。","簪纓且免全爲累，桃李猶堪別作期。","晴後日高偏照灼，晚來風急漸離披。","山郎不作同行伴，折得何由寄所思。"]', '["今歲游山已恨遲，山中仍喜见辛夷。","簪纓且免全爲累，桃李猶堪別作期。","晴後日高偏照灼，晚来风急漸離披。","山郎不作同行伴，折得何由寄所思。"]', '诗', 'shi', '', NULL, '游蔣山題辛夷花寄陳奉禮 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff738be7-c3fe-46cb-961b-c4de283a1a5b', '和殷舍人蕭員外春雪', '和殷舍人蕭員外春雪', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["萬里春陰乍履端，廣庭風起玉塵乾。","梅花嶺上連天白，蕙草堦前特地寒。","晴去便爲經歲別，興來何惜徹宵看。","此時鴛侶皆閑暇，贈答詩成禁漏殘。"]', '["万里春陰乍履端，廣庭风起玉塵乾。","梅花嶺上連天白，蕙草堦前特地寒。","晴去便爲經歲別，兴来何惜徹宵看。","此时鴛侶皆闲暇，贈答诗成禁漏殘。"]', '诗', 'shi', '', NULL, '和殷舍人蕭員外春雪 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a414e00-3d63-442b-8d22-f493f41a3072', '寄蘄州高郎中', '寄蘄州高郎中', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["賈傅棲遲楚澤東，蘭皋三度換秋風。","紛紛世事來無盡，黯黯離魂去不通。","直道未能勝社鼠，孤飛徒自歎冥鴻。","知君多少思鄉恨，併在山城一笛中。"]', '["賈傅棲遲楚澤东，蘭皋三度換秋风。","紛紛世事来無尽，黯黯離魂去不通。","直道未能勝社鼠，孤飞徒自歎冥鴻。","知君多少思乡恨，併在山城一笛中。"]', '诗', 'shi', '', NULL, '寄蘄州高郎中 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d09ecd28-4f1f-4de9-9eab-a7836bec9638', '寄和州韓舍人', '寄和州韓舍人', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["急景駸駸度，遙懷處處生。","風頭乍寒暖，天色半陰晴。","久別魂空斷，終年道不行。","殷勤雲上雁，爲過歷陽城。"]', '["急景駸駸度，遙懷处处生。","风头乍寒暖，天色半陰晴。","久別魂空斷，終年道不行。","殷勤云上雁，爲過歷陽城。"]', '诗', 'shi', '', NULL, '寄和州韓舍人 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('338928c0-b7c4-4e78-8343-8ec7b47a50ad', '從兄龍武將軍沒於邊戍過舊營宅作', '從兄龙武將軍沒於邊戍過旧營宅作', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["前年都尉沒邊城，帳下何人領舊兵。","徼外瘴煙沉鼓角，山前秋日照銘旌。","笙歌却返烏衣巷，部曲皆還細柳營。","今日園林過寒食，馬蹄猶擬入門行。"]', '["前年都尉沒邊城，帳下何人領旧兵。","徼外瘴煙沉鼓角，山前秋日照銘旌。","笙歌却返烏衣巷，部曲皆還細柳營。","今日园林過寒食，马蹄猶擬入门行。"]', '诗', 'shi', '', NULL, '從兄龍武將軍沒於邊戍過舊營宅作 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3d7fac4-b17a-43f1-9780-2439d1459c9a', '景陽臺懷古', '景陽台懷古', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["後主忘家不悔，江南異代長春。","今日景陽臺上，閑人何用傷神。"]', '["後主忘家不悔，江南異代长春。","今日景陽台上，闲人何用傷神。"]', '诗', 'shi', '', NULL, '景陽臺懷古 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9010faab-12b5-4001-a7f7-0449fdaeafef', '春分日', '春分日', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["仲春初四日，春色正中分。","綠野徘徊月，晴天斷續雲。","鷰飛猶箇箇，花落已紛紛。","思婦高樓晚，歌聲不可聞。"]', '["仲春初四日，春色正中分。","綠野徘徊月，晴天斷續云。","鷰飞猶箇箇，花落已紛紛。","思婦高楼晚，歌声不可闻。"]', '诗', 'shi', '', NULL, '春分日 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24b081e5-e3f6-4779-8693-b62ad1959028', '寄駕部郎中', '寄駕部郎中', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["賤子乖慵性，頻爲省直牽。","交親每相見，多在相門前。","君獨疎名路，爲郎過十年。","炎風久成別，南望思悠然。"]', '["賤子乖慵性，頻爲省直牽。","交親每相见，多在相门前。","君独疎名路，爲郎過十年。","炎风久成別，南望思悠然。"]', '诗', 'shi', '', NULL, '寄駕部郎中 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f98aa627-faf1-45f1-9cc6-265a8c266f0e', '和王庶子寄題兄長建州廉使新亭', '和王庶子寄題兄长建州廉使新亭', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["謝守高齋結構新，一方風景萬家情。","羣賢詎減山陰會，遠俗初聞正始聲。","水檻片雲長不去，訟庭纖草轉應生。","阿連詩句偏多思，遙想池塘晝夢成。"]', '["謝守高斋結構新，一方风景万家情。","羣賢詎減山陰會，远俗初闻正始声。","水檻片云长不去，訟庭纖草轉應生。","阿連诗句偏多思，遙想池塘晝梦成。"]', '诗', 'shi', '', NULL, '和王庶子寄題兄長建州廉使新亭 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45bd7a93-acd1-474a-a273-9c453b408233', '謝文靖墓下作', '謝文靖墓下作', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["越徼稽天討，周京亂虜塵。","蒼生何可奈，江表更無人。","豈憚尋荒壟，猶思認後身。","春風白楊裏，獨步淚霑巾。"]', '["越徼稽天討，周京亂虜塵。","蒼生何可奈，江表更無人。","豈憚尋荒壟，猶思認後身。","春风白楊裏，独步泪霑巾。"]', '诗', 'shi', '', NULL, '謝文靖墓下作 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f6f5c63-04a7-453f-baed-ea7d78085059', '觀人讀春秋', '观人读春秋', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["日覺儒風薄，誰將霸道羞。","亂臣無所懼，何用讀春秋。"]', '["日覺儒风薄，誰將霸道羞。","亂臣無所懼，何用读春秋。"]', '诗', 'shi', '', NULL, '觀人讀春秋 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a138fe7f-c6fa-41b6-9e49-4248352cf1c7', '秋日雨中與蕭贊善訪殷舍人於翰林座中作', '秋日雨中與蕭贊善訪殷舍人於翰林座中作', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["野出西垣步步遲，秋光如水雨如絲。","銅龍樓下逢閑客，紅藥堦前訪舊知。","亂點乍滋承露處，碎聲因想滴蓬時。","銀臺鑰入須歸去，不惜餘歡盡酒巵。"]', '["野出西垣步步遲，秋光如水雨如絲。","銅龙楼下逢闲客，紅藥堦前訪旧知。","亂点乍滋承露处，碎声因想滴蓬时。","銀台鑰入須归去，不惜餘歡尽酒巵。"]', '诗', 'shi', '', NULL, '秋日雨中與蕭贊善訪殷舍人於翰林座中作 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ad18885-a508-421b-b0cc-921ffc92bc8c', '送和州張員外爲江都令', '送和州張員外爲江都令', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["經年相望隔重湖，一旦相逢在上都。","塞詔官班聊慰否，埋輪意氣尚存無。","由來聖代憐才子，始覺清風激懦夫。","若向西岡尋勝賞，舊題名處爲躊躇。"]', '["經年相望隔重湖，一旦相逢在上都。","塞詔官班聊慰否，埋輪意氣尚存無。","由来聖代怜才子，始覺清风激懦夫。","若向西岡尋勝賞，旧題名处爲躊躇。"]', '诗', 'shi', '', NULL, '送和州張員外爲江都令 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c374c77-43ec-4d9b-b4d1-770f6219ee31', '和明道人宿山寺', '和明道人宿山寺', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["聞道經行處，山前與水陽。","磐聲深小院，燈影逈高房。","落宿依樓角，歸雲擁殿廊。","羨師閑未得，早起逐班行。"]', '["闻道經行处，山前與水陽。","磐声深小院，灯影逈高房。","落宿依楼角，归云擁殿廊。","羨師闲未得，早起逐班行。"]', '诗', 'shi', '', NULL, '和明道人宿山寺 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb01ada0-22ad-41e3-b1b1-f40f48e61933', '晚歸', '晚归', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["暑服道情出，煙街薄暮還。","風清飄短袂，馬健弄連環。","水靜聞歸櫓，霞明見遠山。","過從本無事，從此涉旬間。"]', '["暑服道情出，煙街薄暮還。","风清飄短袂，马健弄連环。","水静闻归櫓，霞明见远山。","過從本無事，從此涉旬间。"]', '诗', 'shi', '', NULL, '晚歸 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('698cc181-ac28-4e57-b0e4-5ac453438325', '月真歌', '月真歌', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["揚州勝地多麗人，其間麗者名月真。","月真初年十四五，能彈琵琶善歌舞。","風前弱柳一枝春，花裏嬌鶯百般語。","揚州帝京多名賢，其間賢者殷德川。","德川初秉綸闈筆，職近名高常罕出。","花前月下或遊從，一見月真如舊識。","閑庭深院資賢宅，宅門嚴峻無凡客。","垂簾偶坐唯月真，調弄琵琶郎爲拍。","殷郎一旦過江去，鏡中嬾作孤鸞舞。","朝雲暮雨鎮相隨，石頭城下還相遇。","二月三月江南春，滿城濛濛起香塵。","隔牆試聽歌一曲，乃是資賢宅裏人。","綠窗繡幌天將曉，殘燭依依香褭褭。","離腸却恨苦多情，輭障薰籠空悄悄。","殷郎去冬入翰林，九霄官署轉深沉。","人間想望不可見，唯向月真存舊心。","我慙闒茸何爲者，長感餘光每相假。","陋巷蕭條正掩扉，相攜訪我衡茅下。","我本山人愚且貞，歌筵歌席常無情。","自從一見月真後，至今贏得顛狂名。","殷郎月真聽我語，少壯光陰能幾許。","良辰美景數追隨，莫教長說相思苦。"]', '["揚州勝地多丽人，其间丽者名月真。","月真初年十四五，能彈琵琶善歌舞。","风前弱柳一枝春，花裏嬌鶯百般語。","揚州帝京多名賢，其间賢者殷德川。","德川初秉綸闈笔，職近名高常罕出。","花前月下或游從，一见月真如旧識。","闲庭深院資賢宅，宅门嚴峻無凡客。","垂簾偶坐唯月真，調弄琵琶郎爲拍。","殷郎一旦過江去，镜中嬾作孤鸾舞。","朝云暮雨鎮相隨，石头城下還相遇。","二月三月江南春，满城濛濛起香塵。","隔牆試听歌一曲，乃是資賢宅裏人。","綠窗繡幌天將晓，殘燭依依香褭褭。","離腸却恨苦多情，輭障薰籠空悄悄。","殷郎去冬入翰林，九霄官署轉深沉。","人间想望不可见，唯向月真存旧心。","我慙闒茸何爲者，长感餘光每相假。","陋巷蕭條正掩扉，相携訪我衡茅下。","我本山人愚且貞，歌筵歌席常無情。","自從一见月真後，至今贏得顛狂名。","殷郎月真听我語，少壯光陰能幾許。","良辰美景數追隨，莫教长说相思苦。"]', '诗', 'shi', '', NULL, '月真歌 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7098bca-6ddb-45d8-8b0c-9e21f2487c01', '走筆送義興令趙宣輔', '走笔送義兴令趙宣輔', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["聞君孤櫂汎荆谿，隴首雲隨別恨飛。","杜牧舊居憑買取，他年藜杖願同歸。"]', '["闻君孤櫂汎荆谿，隴首云隨別恨飞。","杜牧旧居憑買取，他年藜杖願同归。"]', '诗', 'shi', '', NULL, '走筆送義興令趙宣輔 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9877e9cb-2203-455f-8e12-68fd70522f47', '天闕山絕句', '天闕山絕句', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["散誕愛山客，淒涼懷古心。","寒風天闕晚，盡日倚軒吟。"]', '["散誕愛山客，淒涼懷古心。","寒风天闕晚，尽日倚軒吟。"]', '诗', 'shi', '', NULL, '天闕山絕句 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37b79c8e-2d44-4d27-a87a-5100334e92e8', '除夜', '除夜', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["寒燈耿耿漏遲遲，送故迎新了不欺。","往事併隨殘曆日，春風寧識舊容儀。","預慙歲酒難先飲，更對鄉儺羨小兒。","吟罷明朝贈知己，便須題作去年詩。"]', '["寒灯耿耿漏遲遲，送故迎新了不欺。","往事併隨殘曆日，春风寧識旧容儀。","預慙歲酒难先饮，更对乡儺羨小兒。","吟罷明朝贈知己，便須題作去年诗。"]', '诗', 'shi', '', NULL, '除夜 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('980748f7-c4cb-4750-92ff-9eeafff2c316', '寄鍾謨', '寄鍾謨', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["看看潘鬢二毛生，昨日林梢又轉鶯。","欲對春風忘世慮，敢言尊酒召時英。","假中西閣應無事，筵上南威幸有情。","不得車公終不樂，已教紅袖出門迎。"]', '["看看潘鬢二毛生，昨日林梢又轉鶯。","欲对春风忘世慮，敢言尊酒召时英。","假中西閣應無事，筵上南威幸有情。","不得车公終不乐，已教紅袖出门迎。"]', '诗', 'shi', '', NULL, '寄鍾謨 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8238528-257d-4c66-8739-23758c421c9b', '正初答鍾郎中見招', '正初答鍾郎中见招', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["高齋遲景雪初晴，風拂喬枝待早鶯。","南省郎官名籍籍，東鄰妓女字英英。","流年倏忽成陳事，春物依稀有舊情。","新歲相思自過訪，不煩虛左遠相迎。"]', '["高斋遲景雪初晴，风拂喬枝待早鶯。","南省郎官名籍籍，东鄰妓女字英英。","流年倏忽成陳事，春物依稀有旧情。","新歲相思自過訪，不煩虛左远相迎。"]', '诗', 'shi', '', NULL, '正初答鍾郎中見招 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08037e76-570b-44c9-b01f-5847fba1c9e2', '聞雁寄故人', '闻雁寄故人', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["久作他鄉客，深慙薄宦非。","不知雲上雁，何得每年歸。","夜靜聲彌怨，天空影更微。","往年離別淚，今夕重霑衣。"]', '["久作他乡客，深慙薄宦非。","不知云上雁，何得每年归。","夜静声彌怨，天空影更微。","往年離別泪，今夕重霑衣。"]', '诗', 'shi', '', NULL, '聞雁寄故人 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('491d3756-ae5f-4e30-b20e-77b4314f582d', '江舍人宅筵上有妓唱和州韓舍人歌辭因以寄', '江舍人宅筵上有妓唱和州韓舍人歌辞因以寄', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["良宵絲竹偶成歡，中有佳人俯翠鬟。","白雪飄颻傳樂府，阮郎憔悴在人間。","清風朗月長相憶，佩蕙紉蘭早晚還。","深夜酒空筵欲散，向隅惆悵鬢堪斑。"]', '["良宵絲竹偶成歡，中有佳人俯翠鬟。","白雪飄颻傳乐府，阮郎憔悴在人间。","清风朗月长相憶，佩蕙紉蘭早晚還。","深夜酒空筵欲散，向隅惆悵鬢堪斑。"]', '诗', 'shi', '', NULL, '江舍人宅筵上有妓唱和州韓舍人歌辭因以寄 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36c557f4-367f-4063-82ae-d4ce4ad7dc09', '寒食日作', '寒食日作', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["廚冷煙初禁，門閑日更斜。","東風不好事，吹落滿庭花。","過社紛紛鷰，新晴淡淡霞。","京都盛游觀，誰訪子雲家。"]', '["廚冷煙初禁，门闲日更斜。","东风不好事，吹落满庭花。","過社紛紛鷰，新晴淡淡霞。","京都盛游观，誰訪子云家。"]', '诗', 'shi', '', NULL, '寒食日作 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f8e6169-8bcc-49a8-aae1-5e2dbe483619', '賀殷游二舍人入翰林江給事拜中丞', '賀殷游二舍人入翰林江給事拜中丞', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["清晨待漏獨徘徊，霄漢懸心不易裁。","閣老深嚴歸翰苑，夕郎威望拜霜臺。","青綾對覆蓬壺晚，赤棒前驅道路開。","猶有西垣廳記在，莫忘同草紫泥來。"]', '["清晨待漏独徘徊，霄漢懸心不易裁。","閣老深嚴归翰苑，夕郎威望拜霜台。","青綾对覆蓬壺晚，赤棒前驱道路开。","猶有西垣廳記在，莫忘同草紫泥来。"]', '诗', 'shi', '', NULL, '賀殷游二舍人入翰林江給事拜中丞 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c550d206-5233-4fb0-a38a-fd79d8772b3e', '歐陽太監雨中視決堤因墮水明日見於省中因戲之', '歐陽太監雨中視決堤因墮水明日见於省中因戲之', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["聞道張晨蓋，徘徊石首東。","濬川非伯禹，落水異三公。","衣濕仍愁雨，冠欹更怯風。","今朝復相見，疑是葛仙翁。"]', '["闻道張晨蓋，徘徊石首东。","濬川非伯禹，落水異三公。","衣濕仍愁雨，冠欹更怯风。","今朝复相见，疑是葛仙翁。"]', '诗', 'shi', '', NULL, '歐陽太監雨中視決堤因墮水明日見於省中因戲之 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3469fb45-996a-472c-b081-91b2501a42e6', '送吳郎中爲宣州推官知涇縣', '送吳郎中爲宣州推官知涇縣', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["征虜亭邊月，雞鳴伴客行。","可憐何水部，今事謝宣城。","風物聊供賞，班資莫繫情。","同心不同載，留滯爲浮名。"]', '["征虜亭邊月，雞鳴伴客行。","可怜何水部，今事謝宣城。","风物聊供賞，班資莫繫情。","同心不同載，留滯爲浮名。"]', '诗', 'shi', '', NULL, '送吳郎中爲宣州推官知涇縣 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24f564f9-490e-47c3-8640-6d4c13b43b04', '寄舒州杜員外', '寄舒州杜員外', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["信到得君書，知君已下車。","粉闈情在否，蓮幕興何如。","人望徵賢入，余思從子居。","灊山真隱地，憑爲卜茅廬。"]', '["信到得君书，知君已下车。","粉闈情在否，蓮幕兴何如。","人望徵賢入，余思從子居。","灊山真隐地，憑爲卜茅廬。"]', '诗', 'shi', '', NULL, '寄舒州杜員外 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbe2abc4-1569-4a65-8b96-60b0f5e545bf', '九月十一日寄陳郎中', '九月十一日寄陳郎中', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["我多吏事君多病，寂絕過從又幾旬。","前日龍山煙景好，風前落帽是何人。"]', '["我多吏事君多病，寂絕過從又幾旬。","前日龙山煙景好，风前落帽是何人。"]', '诗', 'shi', '', NULL, '九月十一日寄陳郎中 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0ced71f-21c8-4a86-92fe-7292e531d3a2', '和司門郎中陳彥', '和司门郎中陳彥', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["衡門寂寂逢迎少，不見仙郎向五旬。","莫問龍山前日事，菊花開却爲閑人。"]', '["衡门寂寂逢迎少，不见仙郎向五旬。","莫问龙山前日事，菊花开却爲闲人。"]', '诗', 'shi', '', NULL, '和司門郎中陳彥 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7f83c54-b0ef-4d06-8f51-205a95f37dd2', '賦得擣衣', '賦得擣衣', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["江上多離別，居人夜擣衣。","拂砧知露滴，促杵恐霜飛。","漏轉聲頻斷，愁多力自微。","裁縫依夢見，腰帶定應非。"]', '["江上多離別，居人夜擣衣。","拂砧知露滴，促杵恐霜飞。","漏轉声頻斷，愁多力自微。","裁縫依梦见，腰带定應非。"]', '诗', 'shi', '', NULL, '賦得擣衣 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49cea7d9-7f67-47f5-aa03-7c6b00ba1c65', '九月三十夜雨寄故人', '九月三十夜雨寄故人', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["獨聽空堦雨，方知愁事悲。","寂寥旬假日，蕭颯夜長時。","別念紛紛起，寒更故故遲。","情人如不醉，定是兩相思。"]', '["独听空堦雨，方知愁事悲。","寂寥旬假日，蕭颯夜长时。","別念紛紛起，寒更故故遲。","情人如不醉，定是兩相思。"]', '诗', 'shi', '', NULL, '九月三十夜雨寄故人 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('115008dc-81dc-4112-9448-e7c30f06d290', '寄撫州鍾郎中', '寄撫州鍾郎中', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["去載分襟後，尋聞在建安。","封疆正多事，尊俎若爲歡。","都護空遺鏃，明君欲舞干。","繞朝時不用，非是殺身難。"]', '["去載分襟後，尋闻在建安。","封疆正多事，尊俎若爲歡。","都護空遺鏃，明君欲舞干。","繞朝时不用，非是殺身难。"]', '诗', 'shi', '', NULL, '寄撫州鍾郎中 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1d3d081-709a-44d7-a256-386cd01b24f6', '送歐陽太監游廬山', '送歐陽太監游廬山', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["家家門外廬山路，唯有夫君乞假游。","案牘乍拋公署晚，林泉已近暑天秋。","海潮盡處逢陶石，江月圓時上庾樓。","此去蕭然好長往，人間何事不悠悠。"]', '["家家门外廬山路，唯有夫君乞假游。","案牘乍拋公署晚，林泉已近暑天秋。","海潮尽处逢陶石，江月圓时上庾楼。","此去蕭然好长往，人间何事不悠悠。"]', '诗', 'shi', '', NULL, '送歐陽太監游廬山 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79518155-2c59-4fbb-b4cf-f19930322676', '立秋後一日與朱舍人同直', '立秋後一日與朱舍人同直', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["一宿秋風未覺涼，數聲宮漏日猶長。","林泉無計消殘暑，虛向華池費稻粱。"]', '["一宿秋风未覺涼，數声宮漏日猶长。","林泉無計消殘暑，虛向华池費稻粱。"]', '诗', 'shi', '', NULL, '立秋後一日與朱舍人同直 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf1d8f48-0cc9-405f-8867-7bfd38e99403', '賦得霍將軍辭第', '賦得霍將軍辞第', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["漢將承恩久，圖勳肯顧私。","匈奴猶未滅，安用以家爲。","郢匠雖聞詔，衡門竟不移。","寧煩張老頌，無待晏嬰辭。","甲乙人徒費，親鄰我自持。","悠悠千載下，常作帥臣師。"]', '["漢將承恩久，圖勳肯顧私。","匈奴猶未滅，安用以家爲。","郢匠雖闻詔，衡门竟不移。","寧煩張老頌，無待晏嬰辞。","甲乙人徒費，親鄰我自持。","悠悠千載下，常作帥臣師。"]', '诗', 'shi', '', NULL, '賦得霍將軍辭第 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c22afa36-25cc-453c-ab4b-106c58d184a6', '和元帥書記蕭郎中觀習水師', '和元帥书記蕭郎中观習水師', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["元帥樓船出治兵，落星山外火旗明。","千帆日助江陵勢，萬里風馳下瀨聲。","殺氣曉嚴波上鷁，凱歌遙駭海邊鯨。","仲宣一作從軍詠，迴顧儒衣自不平。"]', '["元帥楼船出治兵，落星山外火旗明。","千帆日助江陵勢，万里风驰下瀨声。","殺氣晓嚴波上鷁，凱歌遙駭海邊鯨。","仲宣一作從軍詠，迴顧儒衣自不平。"]', '诗', 'shi', '', NULL, '和元帥書記蕭郎中觀習水師 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ee5e692-1758-4b76-91c8-dc9b692cf5a7', '秋日盧龍村舍', '秋日盧龙村舍', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["置却人間事，閑從野老游。","樹聲村店晚，草色古城秋。","獨鳥飛天外，閑雲度隴頭。","姓名君莫問，山木與虛舟。"]', '["置却人间事，闲從野老游。","樹声村店晚，草色古城秋。","独鸟飞天外，闲云度隴头。","姓名君莫问，山木與虛舟。"]', '诗', 'shi', '', NULL, '秋日盧龍村舍 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b468b1a2-e395-471a-98b3-b2cc382ebda4', '和蕭郎中小雪日作', '和蕭郎中小雪日作', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["征西府裏日西斜，獨試新爐自煮茶。","籬菊盡來低覆水，塞鴻飛去遠連霞。","寂寥小雪閑中過，斑駁輕霜鬢上加。","算得流年無奈處，莫將詩句祝蒼華。"]', '["征西府裏日西斜，独試新爐自煮茶。","籬菊尽来低覆水，塞鴻飞去远連霞。","寂寥小雪闲中過，斑駁轻霜鬢上加。","算得流年無奈处，莫將诗句祝蒼华。"]', '诗', 'shi', '', NULL, '和蕭郎中小雪日作 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('429cdb41-3b5e-43e4-b1a6-4a2cd48ad6a8', '中書相公谿亭閑宴依韻', '中书相公谿亭闲宴依韻', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["雨霽秋光晚，亭虛野興迴。","沙鷗掠岸去，谿水上堦來。","客傲風欹幘，筵香菊在盃。","東山長許醉，何事憶天台。"]', '["雨霽秋光晚，亭虛野兴迴。","沙鷗掠岸去，谿水上堦来。","客傲风欹幘，筵香菊在盃。","东山长許醉，何事憶天台。"]', '诗', 'shi', '', NULL, '中書相公谿亭閑宴依韻 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14abc826-a06f-41e4-b6cf-610adbe682a3', '寄饒州王郎中效李白體', '寄饒州王郎中效李白體', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["珍重王光嗣，交情尚在不。","蕪城連宅住，楚塞並車游。","別後官三改，年來歲六周。","銀鉤無一字，何以緩離愁。"]', '["珍重王光嗣，交情尚在不。","蕪城連宅住，楚塞並车游。","別後官三改，年来歲六周。","銀鉤無一字，何以緩離愁。"]', '诗', 'shi', '', NULL, '寄饒州王郎中效李白體 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2dfd91e-66de-4634-a3c4-fc0518b2c99f', '寄歙州呂判官', '寄歙州呂判官', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["任公郡占好山川，谿水縈迴路屈盤。","南國自來推勝境，故人此地作郎官。","風光適意須留戀，祿秩資貧且喜歡。","莫憶班行重迴首，是非多處是長安。"]', '["任公郡占好山川，谿水縈迴路屈盤。","南国自来推勝境，故人此地作郎官。","风光適意須留戀，祿秩資貧且喜歡。","莫憶班行重迴首，是非多处是长安。"]', '诗', 'shi', '', NULL, '寄歙州呂判官 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d2c76cd-6fe3-4ea8-a8a9-5c79a16a52d6', '宣威苗將軍貶官後重經故宅', '宣威苗將軍貶官後重經故宅', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["蔣山南望近西坊，亭館依然鎖院牆。","天子未嘗過細柳，將軍尋已戍燉煌。","敧傾怪石山無色，零落圓荷水不香。","爲將爲儒皆寂寞，門前愁殺馬中郎。"]', '["蔣山南望近西坊，亭館依然鎖院牆。","天子未嘗過細柳，將軍尋已戍燉煌。","敧傾怪石山無色，零落圓荷水不香。","爲將爲儒皆寂寞，门前愁殺马中郎。"]', '诗', 'shi', '', NULL, '宣威苗將軍貶官後重經故宅 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c0119fd-8ea8-4933-9ea0-d673f3f47a51', '附池州薛郎中書因寄歙州張員外', '附池州薛郎中书因寄歙州張員外', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["新安從事舊臺郎，直氣多才不可忘。","一旦江山馳別夢，幾年簪紱共周行。","岐分出處何方是，情共窮通此義長。","因附鄰州寄消息，接輿今日信爲狂。"]', '["新安從事旧台郎，直氣多才不可忘。","一旦江山驰別梦，幾年簪紱共周行。","岐分出处何方是，情共窮通此義长。","因附鄰州寄消息，接輿今日信爲狂。"]', '诗', 'shi', '', NULL, '附池州薛郎中書因寄歙州張員外 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27c0900d-5719-4e49-be3a-4e74a1dca0fd', '寄江都路員外', '寄江都路員外', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["吾兄失意在東都，聞說襟懷任所如。","已縱乖慵爲傲吏，有何關鍵制豪胥。","縣齋曉閉多移病，南畝秋荒憶遂初。","知道故人相憶否，嵇康不得嬾修書。"]', '["吾兄失意在东都，闻说襟懷任所如。","已縱乖慵爲傲吏，有何关鍵制豪胥。","縣斋晓閉多移病，南畝秋荒憶遂初。","知道故人相憶否，嵇康不得嬾修书。"]', '诗', 'shi', '', NULL, '寄江都路員外 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3c6c86f-5091-4dca-9ba0-b7119bf0e460', '張員外好茅山風景求爲句容令作此送', '張員外好茅山风景求爲句容令作此送', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["句曲山前縣，依依數舍程。","還同適勾漏，非是厭承明。","柳谷供詩景，華陽契道情。","金門容傲吏，官滿且還城。"]', '["句曲山前縣，依依數舍程。","還同適勾漏，非是厭承明。","柳谷供诗景，华陽契道情。","金门容傲吏，官满且還城。"]', '诗', 'shi', '', NULL, '張員外好茅山風景求爲句容令作此送 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bc0fde3-7995-4dac-a5b2-4072e23701eb', '送應之道人歸江西', '送應之道人归江西', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["曾騎竹馬傍洪厓，二十餘年變物華。","客夢等閑過驛閣，歸帆遙羨指龍沙。","名垂小篆矜垂露，詩作吳吟對綺霞。","歲暮定知迴未得，信來憑爲寄梅花。"]', '["曾騎竹马傍洪厓，二十餘年变物华。","客梦等闲過驛閣，归帆遙羨指龙沙。","名垂小篆矜垂露，诗作吳吟对綺霞。","歲暮定知迴未得，信来憑爲寄梅花。"]', '诗', 'shi', '', NULL, '送應之道人歸江西 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8674b09-516b-46e8-a884-ebe83121767c', '送元帥書記高郎中出爲婺源建威軍使', '送元帥书記高郎中出爲婺源建威軍使', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["寒風蕭瑟楚江南，記室戎裝挂錦帆。","倚馬未曾妨笑傲，斬牲先要厲威嚴。","危言昔日嘗無隱，壯節今來信不凡。","惟有杯盤思上國，酒醪甜淡菜蔬甘。"]', '["寒风蕭瑟楚江南，記室戎裝挂錦帆。","倚马未曾妨笑傲，斬牲先要厲威嚴。","危言昔日嘗無隐，壯節今来信不凡。","惟有杯盤思上国，酒醪甜淡菜蔬甘。"]', '诗', 'shi', '', NULL, '送元帥書記高郎中出爲婺源建威軍使 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('153556cc-132b-4ea6-8184-d52b005ad81f', '遊方山宿李道士房', '游方山宿李道士房', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["從來未面李先生，借我西窗臥月明。","二十三家同願識，素騾何日暫還城。"]', '["從来未面李先生，借我西窗臥月明。","二十三家同願識，素騾何日暫還城。"]', '诗', 'shi', '', NULL, '遊方山宿李道士房 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bdc0779-dfa4-4f54-8b25-516317726ab4', '題畫石山', '題畫石山', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["彼美巉巖石，誰施黼藻功。","回巖明照地，絕壁爛臨空。","錦段鮮須濯，羅屏展易窮。","不因秋蘚綠，非假晚霞紅。","羽客藏書洞，樵人取箭風。","靈蹤理難問，仙路去何通。","返駕歸塵裏，留情向此中。","迴瞻畫圖畔，遙羨面山翁。"]', '["彼美巉巖石，誰施黼藻功。","回巖明照地，絕壁爛臨空。","錦段鲜須濯，羅屏展易窮。","不因秋蘚綠，非假晚霞紅。","羽客藏书洞，樵人取箭风。","靈蹤理难问，仙路去何通。","返駕归塵裏，留情向此中。","迴瞻畫圖畔，遙羨面山翁。"]', '诗', 'shi', '', NULL, '題畫石山 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bcb03fd-0659-479d-ba0b-49ba056c39d1', '臨石步港', '臨石步港', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["碕岸墮縈帶，微風起細漣。","綠陰三月後，倒影亂峰前。","吹浪游鱗小，黏苔碎石圓。","會將腰下組，換取釣魚船。"]', '["碕岸墮縈带，微风起細漣。","綠陰三月後，倒影亂峰前。","吹浪游鱗小，黏苔碎石圓。","會將腰下組，換取釣鱼船。"]', '诗', 'shi', '', NULL, '臨石步港 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78db4949-4c9f-4fef-b446-51453e1e67cd', '病題二首 一', '病題二首 一', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["性靈慵嬾百無能，唯被朝參遣夙興。","聖主優容恩未答，丹經疎闊病相陵。","脾傷對客偏愁酒，眼暗看書每媿燈。","進與時乖不知退，可憐身計謾騰騰。"]', '["性靈慵嬾百無能，唯被朝參遣夙兴。","聖主優容恩未答，丹經疎闊病相陵。","脾傷对客偏愁酒，眼暗看书每媿灯。","進與时乖不知退，可怜身計謾腾腾。"]', '诗', 'shi', '', NULL, '病題二首 一 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0db4e706-43cc-4ac4-8085-4007eff47ae0', '病題二首 二', '病題二首 二', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["人間多事本難論，況是人間嬾慢人。","不解養生何怪病，已能知命敢辭貧。","向空咄咄煩書字，舉世滔滔莫問津。","金馬門前君識否，東方曼倩是前身。"]', '["人间多事本难論，況是人间嬾慢人。","不解養生何怪病，已能知命敢辞貧。","向空咄咄煩书字，舉世滔滔莫问津。","金马门前君識否，东方曼倩是前身。"]', '诗', 'shi', '', NULL, '病題二首 二 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e8bdf70-5797-4a26-9388-1c036ae2444c', '寄江州蕭給事', '寄江州蕭給事', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["夕郎憂國不憂身，今向天涯作逐臣。","魂夢暗馳龍闕曙，嘯吟閑繞虎谿春。","朝車載酒過山寺，諫紙題詩寄野人。","惆悵懦夫何足道，自離羣後已同塵。"]', '["夕郎憂国不憂身，今向天涯作逐臣。","魂梦暗驰龙闕曙，嘯吟闲繞虎谿春。","朝车載酒過山寺，諫紙題诗寄野人。","惆悵懦夫何足道，自離羣後已同塵。"]', '诗', 'shi', '', NULL, '寄江州蕭給事 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5779db4d-ca4a-42cb-8a4d-ffc2063e4eff', '和江州江中丞見寄', '和江州江中丞见寄', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["賈傅南遷久，江關道路遙。","北來空見雁，西去不如潮。","鼠穴依城社，鴻飛在泬寥。","高低各有處，不擬更相招。"]', '["賈傅南遷久，江关道路遙。","北来空见雁，西去不如潮。","鼠穴依城社，鴻飞在泬寥。","高低各有处，不擬更相招。"]', '诗', 'shi', '', NULL, '和江州江中丞見寄 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df59fbc4-c9ce-47e6-a03c-6c0718af2de7', '和鍾郎中送朱先輩還京垂寄', '和鍾郎中送朱先輩還京垂寄', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["分司洗馬無人問，辭客殷勤輟棹歌。","蒼蘚滿庭行徑小，高梧臨檻雨聲多。","春愁盡付千盃酒，鄉思遙聞一曲歌。","且共勝遊消永日，西岡風物近如何。"]', '["分司洗马無人问，辞客殷勤輟棹歌。","蒼蘚满庭行徑小，高梧臨檻雨声多。","春愁尽付千盃酒，乡思遙闻一曲歌。","且共勝游消永日，西岡风物近如何。"]', '诗', 'shi', '', NULL, '和鍾郎中送朱先輩還京垂寄 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3690db2b-c05a-487a-8d1c-be812521d2f3', '送郝郎中爲浙西判官', '送郝郎中爲浙西判官', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["大藩從事本優賢，幕府仍當北固前。","花繞樓臺山倚郭，寺臨江海水連天。","恐君到即忘歸日，憶我遊曾歷二年。","若許他時作閑伴，殷勤爲買釣魚船。"]', '["大藩從事本優賢，幕府仍當北固前。","花繞楼台山倚郭，寺臨江海水連天。","恐君到即忘归日，憶我游曾歷二年。","若許他时作闲伴，殷勤爲買釣鱼船。"]', '诗', 'shi', '', NULL, '送郝郎中爲浙西判官 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f4f32c1-0a14-4281-b5f3-ae7ef7cf5432', '翰林游舍人清明日入院中途見過余明日亦入西省上直因寄游君', '翰林游舍人清明日入院中途见過余明日亦入西省上直因寄游君', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["榆柳開新焰，梨花發故枝。","輜軿隘城市，圭組坐曹司。","獨對芝泥檢，遙憐白馬兒。","禁林還視草，氣味兩相知。"]', '["榆柳开新焰，梨花發故枝。","輜軿隘城市，圭組坐曹司。","独对芝泥檢，遙怜白马兒。","禁林還視草，氣味兩相知。"]', '诗', 'shi', '', NULL, '翰林游舍人清明日入院中途見過余明日亦入西省上直因寄游君 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26991ef0-4a6a-458a-ad28-093388ae8912', '陪王庶子游後湖涵虛閣', '陪王庶子游後湖涵虛閣', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["懸圃清虛乍過秋，看山尋水上茲樓。","輕鷗的的飛難沒，紅葉紛紛晚更稠。","風卷微雲分遠岫，浪搖晴日照中洲。","躋攀況有承華客，如在南皮奉勝遊。"]', '["懸圃清虛乍過秋，看山尋水上茲楼。","轻鷗的的飞难沒，紅葉紛紛晚更稠。","风卷微云分远岫，浪搖晴日照中洲。","躋攀況有承华客，如在南皮奉勝游。"]', '诗', 'shi', '', NULL, '陪王庶子游後湖涵虛閣 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33470720-7ada-4e1c-af0c-6e578f86e7c9', '柳枝辭十二首 一', '柳枝辞十二首 一', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["把酒憑君唱柳枝，也從絲管遞相隨。","逢春只合朝朝醉，記取秋風落葉時。"]', '["把酒憑君唱柳枝，也從絲管遞相隨。","逢春只合朝朝醉，記取秋风落葉时。"]', '诗', 'shi', '', NULL, '柳枝辭十二首 一 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c578615e-08cf-4ac4-aaed-c91bc97b6908', '柳枝辭十二首 二', '柳枝辞十二首 二', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["南園日暮起春風，吹散楊花雪滿空。","不惜楊花飛也得，愁君老盡臉邊紅。"]', '["南园日暮起春风，吹散楊花雪满空。","不惜楊花飞也得，愁君老尽臉邊紅。"]', '诗', 'shi', '', NULL, '柳枝辭十二首 二 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c35b8e35-cc30-497c-8d47-586a098f2d90', '柳枝辭十二首 三', '柳枝辞十二首 三', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["陌上朱門柳映花，簾鉤半捲綠陰斜。","憑郎暫駐青驄馬，此是錢塘小小家。"]', '["陌上朱门柳映花，簾鉤半捲綠陰斜。","憑郎暫駐青驄马，此是錢塘小小家。"]', '诗', 'shi', '', NULL, '柳枝辭十二首 三 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b719d33b-da81-4344-a4a7-87757ffbfa1c', '柳枝辭十二首 四', '柳枝辞十二首 四', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["夾岸朱欄柳映樓，綠波平幔帶花流。","歌聲不出長條密，忽地風迴見綵舟。"]', '["夾岸朱欄柳映楼，綠波平幔带花流。","歌声不出长條密，忽地风迴见綵舟。"]', '诗', 'shi', '', NULL, '柳枝辭十二首 四 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ae07455-d9f7-463a-b010-d6cab1fbeece', '柳枝辭十二首 五', '柳枝辞十二首 五', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["老大逢春總恨春，綠楊陰裏最愁人。","舊游一別無因見，嫩葉如眉處處新。"]', '["老大逢春總恨春，綠楊陰裏最愁人。","旧游一別無因见，嫩葉如眉处处新。"]', '诗', 'shi', '', NULL, '柳枝辭十二首 五 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('928a8f26-dca6-4e5a-a790-af305e2f964a', '柳枝辭十二首 六', '柳枝辞十二首 六', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["濛濛堤畔柳含煙，疑是陽和二月天。","醉裏不知時節改，漫隨兒女打鞦韆。"]', '["濛濛堤畔柳含煙，疑是陽和二月天。","醉裏不知时節改，漫隨兒女打鞦韆。"]', '诗', 'shi', '', NULL, '柳枝辭十二首 六 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62c1359d-d760-4722-8fae-ef18b7db5242', '柳枝辭十二首 七', '柳枝辞十二首 七', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["水閣春來乍減寒，曉妝初罷倚欄干。","長條亂拂春波動，不許佳人照影看。"]', '["水閣春来乍減寒，晓妝初罷倚欄干。","长條亂拂春波动，不許佳人照影看。"]', '诗', 'shi', '', NULL, '柳枝辭十二首 七 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19cea838-66fb-4ef2-a9aa-14009c6f27fa', '柳枝辭十二首 八', '柳枝辞十二首 八', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["柳岸煙昏醉裏歸，不知深處有芳菲。","重來已見花飄盡，唯有黃鶯囀樹飛。"]', '["柳岸煙昏醉裏归，不知深处有芳菲。","重来已见花飄尽，唯有黄鶯囀樹飞。"]', '诗', 'shi', '', NULL, '柳枝辭十二首 八 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5762a59d-15b6-43f0-ba85-e66073d73a02', '柳枝辭十二首 九', '柳枝辞十二首 九', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["此去仙源不是遙，垂楊深處有朱橋。","共君同過朱橋去，索映垂楊聽洞簫。"]', '["此去仙源不是遙，垂楊深处有朱橋。","共君同過朱橋去，索映垂楊听洞簫。"]', '诗', 'shi', '', NULL, '柳枝辭十二首 九 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c68bd289-5728-464f-9847-29d7a46f3d85', '柳枝辭十二首 十', '柳枝辞十二首 十', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["暫別揚州十度春，不知光景屬何人。","一帆歸客千條柳，腸斷東風楊子津。"]', '["暫別揚州十度春，不知光景屬何人。","一帆归客千條柳，腸斷东风楊子津。"]', '诗', 'shi', '', NULL, '柳枝辭十二首 十 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41f8bb1c-6a33-4d2f-9038-0af59408b7c7', '柳枝辭十二首 十一', '柳枝辞十二首 十一', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["仙樂春來按舞腰，清聲偏似傍嬌饒。","應緣鶯舌多情賴，長向雙成說翠條。"]', '["仙乐春来按舞腰，清声偏似傍嬌饒。","應緣鶯舌多情賴，长向雙成说翠條。"]', '诗', 'shi', '', NULL, '柳枝辭十二首 十一 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac96d445-b720-4fde-b4f0-533957859b8f', '柳枝辭十二首 十二', '柳枝辞十二首 十二', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["鳳笙臨檻不能吹，舞袖當筵亦自疑。","唯有美人多意緒，解依芳態畫雙眉。"]', '["鳳笙臨檻不能吹，舞袖當筵亦自疑。","唯有美人多意緒，解依芳態畫雙眉。"]', '诗', 'shi', '', NULL, '柳枝辭十二首 十二 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc5ef5e5-1bf9-4926-b982-3c1185f4d3cc', '貶官泰州出城作', '貶官泰州出城作', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["浮名浮利信悠悠，四海干戈痛主憂。","三諫不從爲逐客，一身無累似虛舟。","滿朝權貴皆曾忤，繞郭林泉已徧游。","惟有戀恩終不改，半程猶自望城樓。"]', '["浮名浮利信悠悠，四海干戈痛主憂。","三諫不從爲逐客，一身無累似虛舟。","满朝權貴皆曾忤，繞郭林泉已徧游。","惟有戀恩終不改，半程猶自望城楼。"]', '诗', 'shi', '', NULL, '貶官泰州出城作 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a53ce8d0-ac2a-4ecc-aa00-4653f367aca6', '過江', '過江', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["別路知何極，離腸有所思。","登艫望城遠，搖樐過江遲。","斷岸煙中失，長天水際垂。","此心非橘柚，不爲兩鄉移。"]', '["別路知何極，離腸有所思。","登艫望城远，搖樐過江遲。","斷岸煙中失，长天水際垂。","此心非橘柚，不爲兩乡移。"]', '诗', 'shi', '', NULL, '過江 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4f32b6e-4f7d-42e8-af43-080045be6e55', '經東都太子橋', '經东都太子橋', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["綸闈放逐知何道，桂苑風流且暫歸。","莫問升遷橋上客，身謀疎拙舊心違。"]', '["綸闈放逐知何道，桂苑风流且暫归。","莫问升遷橋上客，身謀疎拙旧心違。"]', '诗', 'shi', '', NULL, '經東都太子橋 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('041ff655-80c6-45c4-90fb-47e86b980400', '贈維揚故人', '贈維揚故人', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["東京少長認維桑，書劒誰教入帝鄉。","一事無成空放逐，故人相見重淒涼。","樓臺寂寞官河晚，人物稀疎驛路長。","莫怪臨風惆悵久，十年春色憶維揚。"]', '["东京少长認維桑，书劒誰教入帝乡。","一事無成空放逐，故人相见重淒涼。","楼台寂寞官河晚，人物稀疎驛路长。","莫怪臨风惆悵久，十年春色憶維揚。"]', '诗', 'shi', '', NULL, '贈維揚故人 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f641bb0-35ce-42e6-a543-00da88c2b94f', '泰州道中却寄東京故人', '泰州道中却寄东京故人', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["風緊雨淒淒，川迴岸漸低。","吳州林外近，隋苑霧中迷。","聚散紛如此，悲歡豈易齊。","料君殘酒醒，還聽子規啼。"]', '["风緊雨淒淒，川迴岸漸低。","吳州林外近，隋苑霧中迷。","聚散紛如此，悲歡豈易齊。","料君殘酒醒，還听子規啼。"]', '诗', 'shi', '', NULL, '泰州道中却寄東京故人 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e527504d-0c23-4719-8b5b-c94747ae3d51', '得浙西郝判官書未及報聞燕王移鎮京口因寄此詩問方判官田書記消息', '得浙西郝判官书未及報闻燕王移鎮京口因寄此诗问方判官田书記消息', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["秋風海上久離居，曾得劉公一紙書。","淡水心情長若此，銀鉤蹤迹更無如。","嘗憂座側飛鴞鳥，未暇江中覓鯉魚。","今日京吳建朱邸，問君誰共曳長裾。"]', '["秋风海上久離居，曾得劉公一紙书。","淡水心情长若此，銀鉤蹤迹更無如。","嘗憂座側飞鴞鸟，未暇江中覓鯉鱼。","今日京吳建朱邸，问君誰共曳长裾。"]', '诗', 'shi', '', NULL, '得浙西郝判官書未及報聞燕王移鎮京口因寄此詩問方判官田書記消息 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6c4737c-b9d3-4cf5-8410-f296cceb839a', '贈陶使君求梨', '贈陶使君求梨', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["昨宵宴罷醉如泥，惟憶張公大谷梨。","白玉花繁曾綴處，黃金色嫩乍成時。","冷侵肺腑醒偏早，香惹衣襟歇倍遲。","今旦中山方酒渴，唯應此物最相宜。"]', '["昨宵宴罷醉如泥，惟憶張公大谷梨。","白玉花繁曾綴处，黄金色嫩乍成时。","冷侵肺腑醒偏早，香惹衣襟歇倍遲。","今旦中山方酒渴，唯應此物最相宜。"]', '诗', 'shi', '', NULL, '贈陶使君求梨 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3597c41d-b221-4ea8-badc-72e04c57cb47', '陳覺放還至泰州以詩見寄作此答之', '陳覺放還至泰州以诗见寄作此答之', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["朱雲曾爲漢家憂，不怕交親作世仇。","壯氣未平空咄咄，狂言無騐信悠悠。","今朝我作傷弓鳥，却羨君爲不繫舟。","勞寄新詩平宿憾，此生心氣貫清秋。"]', '["朱云曾爲漢家憂，不怕交親作世仇。","壯氣未平空咄咄，狂言無騐信悠悠。","今朝我作傷弓鸟，却羨君爲不繫舟。","勞寄新诗平宿憾，此生心氣貫清秋。"]', '诗', 'shi', '', NULL, '陳覺放還至泰州以詩見寄作此答之 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be36ebfd-6e0b-498c-96b6-cbf92b7fde4c', '王三十七自京垂訪作此送之', '王三十七自京垂訪作此送之', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["失鄉遷客在天涯，門掩苔垣向水斜。","只就鱗鴻求遠信，敢言車馬訪貧家。","煙生柳岸將垂縷，雪壓梅園半是花。","惆悵明朝尊酒散，夢魂相送到京華。"]', '["失乡遷客在天涯，门掩苔垣向水斜。","只就鱗鴻求远信，敢言车马訪貧家。","煙生柳岸將垂縷，雪壓梅园半是花。","惆悵明朝尊酒散，梦魂相送到京华。"]', '诗', 'shi', '', NULL, '王三十七自京垂訪作此送之 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f8d275d-0224-4cb1-83e0-5ab78a32b015', '陶使君挽歌二首 一', '陶使君挽歌二首 一', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["太守今何在，行春去不歸。","筵空收管吹，郊逈儼驂騑。","營外星纔落，園中露已稀。","傷心梁上鷰，猶解向人飛。"]', '["太守今何在，行春去不归。","筵空收管吹，郊逈儼驂騑。","營外星纔落，园中露已稀。","傷心梁上鷰，猶解向人飞。"]', '诗', 'shi', '', NULL, '陶使君挽歌二首 一 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dab949d-6608-4122-8e01-dfd36a2c2ec3', '陶使君挽歌二首 二', '陶使君挽歌二首 二', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["始憶花前宴，笙歌醉夕陽。","那堪城外送，哀挽逐歸艎。","鈴閣朝猶閉，風亭日已荒。","唯餘遷客淚，霑灑後池傍。"]', '["始憶花前宴，笙歌醉夕陽。","那堪城外送，哀挽逐归艎。","鈴閣朝猶閉，风亭日已荒。","唯餘遷客泪，霑灑後池傍。"]', '诗', 'shi', '', NULL, '陶使君挽歌二首 二 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('358fdcb0-38bf-4f6d-9bbe-9c8aa534e2a3', '雪中作', '雪中作', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["賦分多情客，經年去國心。","疎鐘寒郭晚，密雪水亭深。","影逈鴻投渚，聲愁雀噪林。","他鄉一尊酒，獨坐不成斟。"]', '["賦分多情客，經年去国心。","疎鐘寒郭晚，密雪水亭深。","影逈鴻投渚，声愁雀噪林。","他乡一尊酒，独坐不成斟。"]', '诗', 'shi', '', NULL, '雪中作 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('605d770e-6091-4d79-b58a-9db0a5ebbd38', '賦得風光草際浮', '賦得风光草際浮', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["宿露依芳草，春郊古陌旁。","風輕不盡偃，日早未晞陽。","耿耿依平遠，離離入望長。","映空無定彩，飄逕有餘光。","颭若荷珠亂，紛如爝火颺。","詩人多感物，凝思繞池塘。"]', '["宿露依芳草，春郊古陌旁。","风轻不尽偃，日早未晞陽。","耿耿依平远，離離入望长。","映空無定彩，飄逕有餘光。","颭若荷珠亂，紛如爝火颺。","诗人多感物，凝思繞池塘。"]', '诗', 'shi', '', NULL, '賦得風光草際浮 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3c67c71-418b-4a51-98bd-b5354aeef578', '寒食成判官垂訪因贈', '寒食成判官垂訪因贈', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["常年寒食在京華，今歲清明在海涯。","遠巷蹋歌深夜月，隔牆吹管數枝花。","鴛鸞得路音塵闊，鴻雁分飛道里賒。","不是多情成二十，斷無人解訪貧家。"]', '["常年寒食在京华，今歲清明在海涯。","远巷蹋歌深夜月，隔牆吹管數枝花。","鴛鸾得路音塵闊，鴻雁分飞道里賒。","不是多情成二十，斷無人解訪貧家。"]', '诗', 'shi', '', NULL, '寒食成判官垂訪因贈 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4d17183-9436-4666-89a5-852c6566379f', '送客至城西望圖山因寄浙西府中', '送客至城西望圖山因寄浙西府中', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["牧叟鄒生笑語同，莫嗟江上聽秋風。","君看逐客思鄉處，猶在圖山更向東。"]', '["牧叟鄒生笑語同，莫嗟江上听秋风。","君看逐客思乡处，猶在圖山更向东。"]', '诗', 'shi', '', NULL, '送客至城西望圖山因寄浙西府中 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52b3e9a8-edb4-40e5-8b66-d9f6da5e0338', '送寫真成處士入京', '送寫真成处士入京', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["傳神蹤迹本來高，澤畔形容媿彩毫。","京邑功臣多佇望，凌煙閣上莫辭勞。"]', '["傳神蹤迹本来高，澤畔形容媿彩毫。","京邑功臣多佇望，凌煙閣上莫辞勞。"]', '诗', 'shi', '', NULL, '送寫真成處士入京 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d1ac3ce-1769-4518-acd5-3d784a3e4750', '九日雨中', '九日雨中', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["茱萸房重雨霏微，去國逢秋此恨稀。","目極暫登臺上望，心遙長向夢中歸。","荃蘪路遠愁霜早，兄弟鄉遙羨雁飛。","唯有多情一枝菊，滿杯顏色自依依。"]', '["茱萸房重雨霏微，去国逢秋此恨稀。","目極暫登台上望，心遙长向梦中归。","荃蘪路远愁霜早，兄弟乡遙羨雁飞。","唯有多情一枝菊，满杯顏色自依依。"]', '诗', 'shi', '', NULL, '九日雨中 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf2900ff-217a-4079-bc32-fcef34e43937', '寄外甥苗武仲', '寄外甥苗武仲', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["放逐今來漲海邊，親情多在鳳臺前。","且將聚散爲閑事，須信華枯是偶然。","蟬噪疎林村倚郭，鳥飛殘照水連天。","此中唯欠韓康伯，共對秋風詠數篇。"]', '["放逐今来漲海邊，親情多在鳳台前。","且將聚散爲闲事，須信华枯是偶然。","蟬噪疎林村倚郭，鸟飞殘照水連天。","此中唯欠韓康伯，共对秋风詠數篇。"]', '诗', 'shi', '', NULL, '寄外甥苗武仲 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2299b8df-e88f-499b-8c7b-803919b4ac1a', '寄從兄憲兼示二弟', '寄從兄憲兼示二弟', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["別路吳將楚，離憂弟與兄。","斷雲驚晚吹，秋色滿孤城。","信遠鴻初下，鄉遙月共明。","一枝棲未穩，迴首望三京。"]', '["別路吳將楚，離憂弟與兄。","斷云驚晚吹，秋色满孤城。","信远鴻初下，乡遙月共明。","一枝棲未穩，迴首望三京。"]', '诗', 'shi', '', NULL, '寄從兄憲兼示二弟 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9210e240-f81c-4d6c-bf3c-a2bf98164003', '附書與鍾郎中因寄京妓越賓', '附书與鍾郎中因寄京妓越賓', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["暮春橋下手封書，寄向江南問越姑。","不道諸郎少歡笑，經年相別憶儂無。"]', '["暮春橋下手封书，寄向江南问越姑。","不道諸郎少歡笑，經年相別憶儂無。"]', '诗', 'shi', '', NULL, '附書與鍾郎中因寄京妓越賓 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e33a4dd-7498-415d-abaa-c2ad2c9e7b93', '代鍾答', '代鍾答', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["一幅輕綃寄海濱，越姑長感昔時恩。","欲知別後情多少，點點憑君看淚痕。"]', '["一幅轻綃寄海濱，越姑长感昔时恩。","欲知別後情多少，点点憑君看泪痕。"]', '诗', 'shi', '', NULL, '代鍾答 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e853f33-883c-47c7-a8c9-4602a3e4b67a', '亞元舍人不替深知猥貽佳作三篇清絕不敢輕酬因爲長歌聊以爲報未竟復得子喬校書示問故兼寄陳君庶資一笑耳', '亞元舍人不替深知猥貽佳作三篇清絕不敢轻酬因爲长歌聊以爲報未竟复得子喬校书示问故兼寄陳君庶資一笑耳', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["海陵城裏春正月，海畔朝陽照殘雪。","城中有客獨登樓，遙望天邊白銀闕。","白銀闕下何英英，雕鞍繡轂趨承明。","閶門曉闢旌旗影，玉墀風細佩環聲。","此處追飛皆俊彥，當年何事容疵賤。","懷鉛晝坐紫微宮，焚香夜直明光殿。","王言簡靜官司閑，朋好殷勤多往還。","新亭風景如東洛，邙嶺林泉似北山。","光陰暗度盃盂裏，職業未妨談笑間。","有時邀賓復攜妓，造門不問都非是。","酣歌呌笑驚四鄰，賦筆縱橫動千字。","任他銀箭轉更籌，不怕金吾司夜吏。","可憐諸貴賢且才，時情物望兩無猜。","伊余獨稟狂狷性，褊量多言仍薄命。","吞舟可漏豈無恩，負乘自貽非不幸。","一朝削跡爲遷客，旦暮青雲千里隔。","離鴻別雁各分飛，折柳攀花兩無色。","盧龍渡口問迷津，瓜步山前送暮春。","白沙江上曾行路，青林花落何紛紛。","漢皇昔幸回中道，極目牛羊臥芳草。","舊宅重游盡隟荒，故人相見多衰老。","禪智寺，山光橋，風瑟瑟兮雨蕭蕭。","行盃已醒殘夢斷，征途未極離魂消。","海陵郡中陶太守，相逢本是隨行舊。","乍申拜起已開眉，却問辛勤還執手。","精廬水榭最清幽，一稅征車聊駐留。","閉門思過謝來客，知恩省分寬離憂。","郡齋勝境有後池，山亭菌閣互參差。","有時虛左來相召，舉白飛觴任所爲。","多才太守能撾鼓，醉送金船間歌舞。","酒酣耳熱眼生花，暫似京華歡會處。","歸來旅館還端居，清風朗月夜窗虛。","駸駸流景歲云暮，天涯望斷故人書。","春來憑檻方歎息，仰頭忽見南來翼。","足繫紅箋墮我前，引頸長鳴如有言。","開緘試讀相思字，乃是多情喬亞元。","短韻三篇皆麗絕，小梅寄意情偏切。","金蘭投分一何堅，銀鉤置袖終難滅。","醉後狂言何足奇，感君知己不相遺。","長卿曾作美人賦，玄成今有責躬詩。","報章欲託還京信，筆拙紙窮情未盡。","珍重芸香陳子喬，亦解貽書遠相問。","寧須買藥療羈愁，只恨無書消鄙吝。","游處當時靡不同，歡娛今日兩成空。","天子尚應憐賈誼，時人未要嘲楊雄。","曲終筆閣緘封已，翩翩驛騎行塵起。","寄向中朝謝故人，爲說相思意如此。"]', '["海陵城裏春正月，海畔朝陽照殘雪。","城中有客独登楼，遙望天邊白銀闕。","白銀闕下何英英，雕鞍繡轂趨承明。","閶门晓闢旌旗影，玉墀风細佩环声。","此处追飞皆俊彥，當年何事容疵賤。","懷鉛晝坐紫微宮，焚香夜直明光殿。","王言簡静官司闲，朋好殷勤多往還。","新亭风景如东洛，邙嶺林泉似北山。","光陰暗度盃盂裏，職業未妨談笑间。","有时邀賓复携妓，造门不问都非是。","酣歌呌笑驚四鄰，賦笔縱橫动千字。","任他銀箭轉更籌，不怕金吾司夜吏。","可怜諸貴賢且才，时情物望兩無猜。","伊余独稟狂狷性，褊量多言仍薄命。","吞舟可漏豈無恩，負乘自貽非不幸。","一朝削跡爲遷客，旦暮青云千里隔。","離鴻別雁各分飞，折柳攀花兩無色。","盧龙渡口问迷津，瓜步山前送暮春。","白沙江上曾行路，青林花落何紛紛。","漢皇昔幸回中道，極目牛羊臥芳草。","旧宅重游尽隟荒，故人相见多衰老。","禪智寺，山光橋，风瑟瑟兮雨蕭蕭。","行盃已醒殘梦斷，征途未極離魂消。","海陵郡中陶太守，相逢本是隨行旧。","乍申拜起已开眉，却问辛勤還執手。","精廬水榭最清幽，一稅征车聊駐留。","閉门思過謝来客，知恩省分寬離憂。","郡斋勝境有後池，山亭菌閣互參差。","有时虛左来相召，舉白飞觴任所爲。","多才太守能撾鼓，醉送金船间歌舞。","酒酣耳熱眼生花，暫似京华歡會处。","归来旅館還端居，清风朗月夜窗虛。","駸駸流景歲云暮，天涯望斷故人书。","春来憑檻方歎息，仰头忽见南来翼。","足繫紅箋墮我前，引頸长鳴如有言。","开緘試读相思字，乃是多情喬亞元。","短韻三篇皆丽絕，小梅寄意情偏切。","金蘭投分一何堅，銀鉤置袖終难滅。","醉後狂言何足奇，感君知己不相遺。","长卿曾作美人賦，玄成今有責躬诗。","報章欲託還京信，笔拙紙窮情未尽。","珍重芸香陳子喬，亦解貽书远相问。","寧須買藥療羈愁，只恨無书消鄙吝。","游处當时靡不同，歡娛今日兩成空。","天子尚應怜賈誼，时人未要嘲楊雄。","曲終笔閣緘封已，翩翩驛騎行塵起。","寄向中朝謝故人，爲说相思意如此。"]', '诗', 'shi', '', NULL, '亞元舍人不替深知猥貽佳作三篇清絕不敢輕酬因爲長歌聊以爲報未竟復得子喬校書示問故兼寄陳君庶資一笑耳 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f60ae21-86a1-449f-a5f2-e9fe9bf116a7', '送蒯司錄歸京', '送蒯司錄归京', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["早年聞有蒯先生，二十餘年道不行。","抵掌曾論天下事，折腰猶悟俗人情。","老還上國歡娛少，貧聚歸資結束輕。","遷客臨流倍惆悵，冷風黃葉滿山城。"]', '["早年闻有蒯先生，二十餘年道不行。","抵掌曾論天下事，折腰猶悟俗人情。","老還上国歡娛少，貧聚归資結束轻。","遷客臨流倍惆悵，冷风黄葉满山城。"]', '诗', 'shi', '', NULL, '送蒯司錄歸京 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd9cce51-0b70-4f2f-abf9-61fa4a9626d0', '聞查建州陷賊寄鍾郎中', '闻查建州陷賊寄鍾郎中', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["聞道將軍輕壯圖，螺江城下委犀渠。","旌旗零落沉荒服，簪履蕭條返故居。","皓首應全蘇武節，故人誰得李陵書。","自憐放逐無長策，空使盧諶淚滿裾。"]', '["闻道將軍轻壯圖，螺江城下委犀渠。","旌旗零落沉荒服，簪履蕭條返故居。","皓首應全蘇武節，故人誰得李陵书。","自怜放逐無长策，空使盧諶泪满裾。"]', '诗', 'shi', '', NULL, '聞查建州陷賊寄鍾郎中 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9a7c874-776d-4ff5-b801-8799fa267035', '還過東都留守周公筵上贈座客', '還過东都留守周公筵上贈座客', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["賈生三載在長沙，故友相思道路賒。","已分終年甘寂寞，豈知今日還京華。","麟符上相恩偏厚，隋苑留歡日欲斜。","明旦江頭倍惆悵，遠山芳草映殘霞。"]', '["賈生三載在长沙，故友相思道路賒。","已分終年甘寂寞，豈知今日還京华。","麟符上相恩偏厚，隋苑留歡日欲斜。","明旦江头倍惆悵，远山芳草映殘霞。"]', '诗', 'shi', '', NULL, '還過東都留守周公筵上贈座客 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0d4d8fd-669d-448a-ab60-9e54e732e62f', '送楊郎中唐員外奉使湖南', '送楊郎中唐員外奉使湖南', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["江邊微雨柳條新，握節含香二使臣。","兩綬對懸雲夢日，方舟齊汎洞庭春。","今朝草木逢新律，昨日山川滿戰塵。","同是多情懷古客，不妨爲賦弔靈均。"]', '["江邊微雨柳條新，握節含香二使臣。","兩綬对懸云梦日，方舟齊汎洞庭春。","今朝草木逢新律，昨日山川满戰塵。","同是多情懷古客，不妨爲賦弔靈均。"]', '诗', 'shi', '', NULL, '送楊郎中唐員外奉使湖南 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdbe6b5c-d268-424a-9223-502bbcb2727b', '表弟包潁見寄', '表弟包潁见寄', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["常思帝里奉交親，別後光陰屈指頻。","蘭佩却歸綸閣下，荆枝猶寄楚江濱。","十程山水勞幽夢，滿院煙花醉別人。","料得此生強健在，會須重賞昔年春。"]', '["常思帝里奉交親，別後光陰屈指頻。","蘭佩却归綸閣下，荆枝猶寄楚江濱。","十程山水勞幽梦，满院煙花醉別人。","料得此生強健在，會須重賞昔年春。"]', '诗', 'shi', '', NULL, '表弟包潁見寄 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('376402d1-4dce-4044-972b-fb66b355f0c4', '寄蕭給事', '寄蕭給事', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["危言危行古時人，歸向西山臥白雲。","買宅尚尋徐處士，餐霞終訪許真君。","容顏別後應如故，詩詠年來更不聞。","今日城中春又至，落梅愁緒共紛紛。"]', '["危言危行古时人，归向西山臥白云。","買宅尚尋徐处士，餐霞終訪許真君。","容顏別後應如故，诗詠年来更不闻。","今日城中春又至，落梅愁緒共紛紛。"]', '诗', 'shi', '', NULL, '寄蕭給事 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('006330ba-c3c2-46e4-9645-ac915a200272', '賦石奉送鍾德林少尹員外', '賦石奉送鍾德林少尹員外', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["我愛他山石，中含絕代珍。","煙披寒落落，沙淺靜磷磷。","翠色辭文陛，清聲出泗濱。","扁舟載歸去，知是汎槎人。"]', '["我愛他山石，中含絕代珍。","煙披寒落落，沙淺静磷磷。","翠色辞文陛，清声出泗濱。","扁舟載归去，知是汎槎人。"]', '诗', 'shi', '', NULL, '賦石奉送鍾德林少尹員外 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9547f73e-b5a6-44d8-bf15-4fd3bd7387a6', '贈泰州掾令狐克己', '贈泰州掾令狐克己', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["念子才多命且奇，亂中拋擲少年時。","深藏七澤衣如雪，却見中朝鬢似絲。","舊德在人終遠大，扁舟爲吏莫推辭。","孤芳自愛凌霜處，詠取文公白菊詩。"]', '["念子才多命且奇，亂中拋擲少年时。","深藏七澤衣如雪，却见中朝鬢似絲。","旧德在人終远大，扁舟爲吏莫推辞。","孤芳自愛凌霜处，詠取文公白菊诗。"]', '诗', 'shi', '', NULL, '贈泰州掾令狐克己 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('939561ce-a831-4b31-891a-a51744ed3d7b', '送荻栽與秀才朱觀', '送荻栽與秀才朱观', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["羨子清吟處，茅齋面碧流。","解憎蓮豔俗，唯欠荻花幽。","鷺立低枝晚，風驚折葉秋。","贈君須種取，不必樹忘憂。"]', '["羨子清吟处，茅斋面碧流。","解憎蓮豔俗，唯欠荻花幽。","鷺立低枝晚，风驚折葉秋。","贈君須種取，不必樹忘憂。"]', '诗', 'shi', '', NULL, '送荻栽與秀才朱觀 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3d65101-8a2c-4478-99d3-8d0fdd17083a', '使浙西先寄獻燕王侍中', '使浙西先寄獻燕王侍中', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["京江風靜喜乘流，極目遙瞻萬歲樓。","喜氣蘢葱甘露晚，水煙波淡海門秋。","五年不見鸞臺長，明日將陪兔苑遊。","欲問平臺門下吏，相君還許吐茵不。"]', '["京江风静喜乘流，極目遙瞻万歲楼。","喜氣蘢葱甘露晚，水煙波淡海门秋。","五年不见鸾台长，明日將陪兔苑游。","欲问平台门下吏，相君還許吐茵不。"]', '诗', 'shi', '', NULL, '使浙西先寄獻燕王侍中 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27ab48ec-85c4-42b4-8faf-f9f2ef73871e', '常州驛中喜雨', '常州驛中喜雨', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["颯颯旱天雨，涼風一夕迴。","遠尋南畝去，細入驛亭來。","蓑唱牛初牧，漁歌棹正開。","盈庭頓無事，歸思酌金罍。"]', '["颯颯旱天雨，涼风一夕迴。","远尋南畝去，細入驛亭来。","蓑唱牛初牧，漁歌棹正开。","盈庭頓無事，归思酌金罍。"]', '诗', 'shi', '', NULL, '常州驛中喜雨 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f501519-b77a-464a-88a6-4e0ba7e6d220', '驛中七夕', '驛中七夕', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["七夕雨初霽，行人正憶家。","江天望河漢，水館折蓮花。","獨坐涼何甚，微吟月易斜。","今年不乞巧，鈍拙轉堪嗟。"]', '["七夕雨初霽，行人正憶家。","江天望河漢，水館折蓮花。","独坐涼何甚，微吟月易斜。","今年不乞巧，鈍拙轉堪嗟。"]', '诗', 'shi', '', NULL, '驛中七夕 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c222a47-2d1f-4447-b497-8a9fc371a3a6', '贈浙西顧推官', '贈浙西顧推官', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["盛府賓寮八十餘，閉門高臥興無如。","梁王苑裏相逢早，潤浦城中得信疎。","狼藉盃盤重會面，風流才調一如初。","願君百歲猶強健，他日相尋隱士廬。"]', '["盛府賓寮八十餘，閉门高臥兴無如。","梁王苑裏相逢早，潤浦城中得信疎。","狼藉盃盤重會面，风流才調一如初。","願君百歲猶強健，他日相尋隐士廬。"]', '诗', 'shi', '', NULL, '贈浙西顧推官 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('654f1878-571a-4b2d-ad6d-d5b273eba014', '贈浙西妓亞仙', '贈浙西妓亞仙', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["翠黛嚬如怨，朱顏醉更春。","占將南國貌，惱殺別家人。","粉汗沾巡盞，花鈿逐舞茵。","明朝綺窗下，離恨兩殷勤。"]', '["翠黛嚬如怨，朱顏醉更春。","占將南国貌，惱殺別家人。","粉汗沾巡盞，花鈿逐舞茵。","明朝綺窗下，離恨兩殷勤。"]', '诗', 'shi', '', NULL, '贈浙西妓亞仙 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e9cd727-1956-4b3d-b227-a095fd1b64a9', '迴至瓜洲獻侍中', '迴至瓜洲獻侍中', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["紫微垣裏舊賓從，來向吳門謁府公。","奉使謬持嚴助節，登門初識魯王宮。","笙歌隱隱違離後，煙水茫茫悵望中。","日暮瓜洲江北岸，兩行情淚滴西風。"]', '["紫微垣裏旧賓從，来向吳门謁府公。","奉使謬持嚴助節，登门初識魯王宮。","笙歌隐隐違離後，煙水茫茫悵望中。","日暮瓜洲江北岸，兩行情泪滴西风。"]', '诗', 'shi', '', NULL, '迴至瓜洲獻侍中 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d136f3c0-604e-4635-8314-4fbb98060ef3', '邵伯埭下寄高郵陳郎中', '邵伯埭下寄高郵陳郎中', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["故人相別動經年，候館相逢倍慘然。","顧我飲冰難輟櫂，感君扶病爲開筵。","河灣水淺翹秋鷺，柳岸風微噪暮蟬。","欲識酒醒魂斷處，謝公祠畔客亭前。"]', '["故人相別动經年，候館相逢倍慘然。","顧我饮冰难輟櫂，感君扶病爲开筵。","河灣水淺翹秋鷺，柳岸风微噪暮蟬。","欲識酒醒魂斷处，謝公祠畔客亭前。"]', '诗', 'shi', '', NULL, '邵伯埭下寄高郵陳郎中 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1ed858c-45a5-47c8-a67b-874c1a637bc6', '謫居舒州累得韓高二舍人書作此寄之', '謫居舒州累得韓高二舍人书作此寄之', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["三峰煙靄碧臨谿，中有騷人理釣絲。","會友少於分袂日，謫居多却在朝時。","丹心歷歷吾終信，俗慮悠悠爾不知。","珍重韓君與高子，殷勤書札寄相思。"]', '["三峰煙靄碧臨谿，中有騷人理釣絲。","會友少於分袂日，謫居多却在朝时。","丹心歷歷吾終信，俗慮悠悠爾不知。","珍重韓君與高子，殷勤书札寄相思。"]', '诗', 'shi', '', NULL, '謫居舒州累得韓高二舍人書作此寄之 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a8b61e2-dd27-44e4-aa4c-62181765cd71', '和張先輩見寄二首 一', '和張先輩见寄二首 一', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["去國離羣擲歲華，病容憔悴媿丹砂。","谿連舍下衣長潤，山帶城邊日易斜。","幾處垂鉤依野岸，有時披褐到鄰家。","故人書札頻相慰，誰道西京道路賒。"]', '["去国離羣擲歲华，病容憔悴媿丹砂。","谿連舍下衣长潤，山带城邊日易斜。","幾处垂鉤依野岸，有时披褐到鄰家。","故人书札頻相慰，誰道西京道路賒。"]', '诗', 'shi', '', NULL, '和張先輩見寄二首 一 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29db4d85-612a-4333-89f8-bb0b4d43121e', '和張先輩見寄二首 二', '和張先輩见寄二首 二', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["清時淪放在山州，邛竹紗巾處處游。","野日蒼茫悲鵩舍，水風陰濕弊貂裘。","雞鳴候旦寧辭晦，松節凌霜幾換秋。","兩首新詩千里道，感君情分獨知丘。"]', '["清时淪放在山州，邛竹紗巾处处游。","野日蒼茫悲鵩舍，水风陰濕弊貂裘。","雞鳴候旦寧辞晦，松節凌霜幾換秋。","兩首新诗千里道，感君情分独知丘。"]', '诗', 'shi', '', NULL, '和張先輩見寄二首 二 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abbe850b-cf58-4496-b6d8-2ade63a84335', '印秀才至舒州見尋別後寄詩依韻和', '印秀才至舒州见尋別後寄诗依韻和', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["羈游白社身雖屈，高步辭場道不卑。","投分共爲知我者，相尋多媿謫居時。","離懷耿耿年來夢，厚意勤勤別後詩。","今日谿邊正相憶，雪晴山秀柳絲垂。"]', '["羈游白社身雖屈，高步辞場道不卑。","投分共爲知我者，相尋多媿謫居时。","離懷耿耿年来梦，厚意勤勤別後诗。","今日谿邊正相憶，雪晴山秀柳絲垂。"]', '诗', 'shi', '', NULL, '印秀才至舒州見尋別後寄詩依韻和 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0bf247f-1344-48e2-98b6-d1fec55a773e', '行園樹', '行园樹', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["松節凌霜久，蓬根逐吹頻。","羣生各有性，桃李但爭春。"]', '["松節凌霜久，蓬根逐吹頻。","羣生各有性，桃李但爭春。"]', '诗', 'shi', '', NULL, '行園樹 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44967ba5-12cd-40f7-8c73-af62c82a5e89', '題雷公井', '題雷公井', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["揜靄愚公谷，蕭寥羽客家。","俗人知處所，應爲有桃花。"]', '["揜靄愚公谷，蕭寥羽客家。","俗人知处所，應爲有桃花。"]', '诗', 'shi', '', NULL, '題雷公井 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a6cd84a-f7e8-43ee-a575-f7481b7c45f2', '送彭秀才', '送彭秀才', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["賈生去國已三年，短褐閑行皖水邊。","盡日野雲生舍下，有時京信到門前。","無人與和投湘賦，媿子來浮訪戴船。","滿袖新詩好迴去，莫隨騷客醉林泉。"]', '["賈生去国已三年，短褐闲行皖水邊。","尽日野云生舍下，有时京信到门前。","無人與和投湘賦，媿子来浮訪戴船。","满袖新诗好迴去，莫隨騷客醉林泉。"]', '诗', 'shi', '', NULL, '送彭秀才 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba3354a0-2b2b-4b3a-b404-fbff88ca15b6', '移饒州別周使君', '移饒州別周使君', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["正憐東道感賢侯，何幸南冠脫楚囚。","睆伯臺前收別宴，喬公亭下艤行舟。","四年去國身將老，百郡徵兵主尚憂。","更向鄱陽湖上去，青衫憔悴淚交流。"]', '["正怜东道感賢侯，何幸南冠脫楚囚。","睆伯台前收別宴，喬公亭下艤行舟。","四年去国身將老，百郡徵兵主尚憂。","更向鄱陽湖上去，青衫憔悴泪交流。"]', '诗', 'shi', '', NULL, '移饒州別周使君 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('270d19d7-e7b8-4b8a-b337-4d4726983ada', '避難東歸依韻和黃秀才見寄', '避难东归依韻和黄秀才见寄', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["慼慼逢人問所之，東流相送向京畿。","自甘逐客紉蘭佩，不料平民著戰衣。","樹帶荒村春冷落，江澄霽色霧霏微。","時危道喪無才術，空手徘徊不忍歸。"]', '["慼慼逢人问所之，东流相送向京畿。","自甘逐客紉蘭佩，不料平民著戰衣。","樹带荒村春冷落，江澄霽色霧霏微。","时危道喪無才術，空手徘徊不忍归。"]', '诗', 'shi', '', NULL, '避難東歸依韻和黃秀才見寄 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('066e5f06-6d53-47d1-81f8-982462f0281d', '酬郭先輩', '酬郭先輩', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["太原郭夫子，行高文炳蔚。","弱齡負世譽，一舉游月窟。","仙籍第三人，時人故稱屈。","昔余吏西省，傾蓋名籍籍。","及我竄羣舒，向風心鬱鬱。","歸來暮江上，雲霧一披拂。","雷雨不下施，猶作池中物。","念君介然氣，感時思奮發。","示我數篇文，與古爭馳突。","綵褥粲英華，理深刮肌骨。","古詩尤精奧，史論皆宏拔。","舉此措諸民，何憂民不活。","吁嗟吾道薄，與世長迂闊。","顧我徒有心，數奇身正絀。","論兵屬少年，經國須儒術。","夫子無自輕，蒼生正愁疾。"]', '["太原郭夫子，行高文炳蔚。","弱齡負世譽，一舉游月窟。","仙籍第三人，时人故稱屈。","昔余吏西省，傾蓋名籍籍。","及我竄羣舒，向风心鬱鬱。","归来暮江上，云霧一披拂。","雷雨不下施，猶作池中物。","念君介然氣，感时思奮發。","示我數篇文，與古爭驰突。","綵褥粲英华，理深刮肌骨。","古诗尤精奧，史論皆宏拔。","舉此措諸民，何憂民不活。","吁嗟吾道薄，與世长迂闊。","顧我徒有心，數奇身正絀。","論兵屬少年，經国須儒術。","夫子無自轻，蒼生正愁疾。"]', '诗', 'shi', '', NULL, '酬郭先輩 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4ae9ca1-f1ce-42db-aa7f-c30c3e5ab987', '和集賢鍾郎中', '和集賢鍾郎中', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["石渠冊府神仙署，當用明朝第一人。","腰下別懸新印綬，座中皆是故交親。","龍池樹色供清景，浴殿香風接近鄰。","從此翻飛應更遠，徧尋三十六天春。"]', '["石渠冊府神仙署，當用明朝第一人。","腰下別懸新印綬，座中皆是故交親。","龙池樹色供清景，浴殿香风接近鄰。","從此翻飞應更远，徧尋三十六天春。"]', '诗', 'shi', '', NULL, '和集賢鍾郎中 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8124d3a7-5ff6-47df-a138-396462fe3273', '送劉山陽', '送劉山陽', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["舊族知名士，朱衣宰楚城。","所嗟吾道薄，豈是主恩輕。","戰鼓何時息，儒冠獨自行。","此心多感激，相送若爲情。"]', '["旧族知名士，朱衣宰楚城。","所嗟吾道薄，豈是主恩轻。","戰鼓何时息，儒冠独自行。","此心多感激，相送若爲情。"]', '诗', 'shi', '', NULL, '送劉山陽 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6fe6f55-813e-4893-84b8-418a356c69ef', '題伏龜山北隅', '題伏龟山北隅', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["茲山信岑寂，陰崖積蒼翠。","水石何必多，宛有千巖意。","孰知近人境，旦暮含佳氣。","池影搖輕風，林光澹新霽。","支頤藉芳草，自足忘世事。","未得歸去來，聊爲宴居地。"]', '["茲山信岑寂，陰崖積蒼翠。","水石何必多，宛有千巖意。","孰知近人境，旦暮含佳氣。","池影搖轻风，林光澹新霽。","支頤藉芳草，自足忘世事。","未得归去来，聊爲宴居地。"]', '诗', 'shi', '', NULL, '題伏龜山北隅 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0592e7d-3939-4219-be73-9eb117481305', '送黃梅江明府', '送黄梅江明府', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["封疆多難正經綸，臺閣如何不用君。","江上又勞爲小邑，篋中徒自有雄文。","書生膽氣人誰信，遠俗歌謠主不聞。","一首新詩無限意，再三吟味向秋雲。"]', '["封疆多难正經綸，台閣如何不用君。","江上又勞爲小邑，篋中徒自有雄文。","书生膽氣人誰信，远俗歌謠主不闻。","一首新诗無限意，再三吟味向秋云。"]', '诗', 'shi', '', NULL, '送黃梅江明府 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('748d0d2b-0254-492c-9667-6a39b76a600b', '詠梅子真送郭先輩', '詠梅子真送郭先輩', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["忠臣本愛君，仁人本愛民。","寧知貴與賤，豈計名與身。","梅生爲一尉，獻疏來君門。","君門深萬里，金虎重千鈞。","向永且不用，況復論子真。","拂衣遂長往，高節邈無鄰。","至今仙籍中，謂之梅真人。","郭生負逸氣，百代繼遺塵。","進退生自知，得喪吾不陳。","斯民苟有幸，期子一朝伸。"]', '["忠臣本愛君，仁人本愛民。","寧知貴與賤，豈計名與身。","梅生爲一尉，獻疏来君门。","君门深万里，金虎重千鈞。","向永且不用，況复論子真。","拂衣遂长往，高節邈無鄰。","至今仙籍中，謂之梅真人。","郭生負逸氣，百代繼遺塵。","進退生自知，得喪吾不陳。","斯民苟有幸，期子一朝伸。"]', '诗', 'shi', '', NULL, '詠梅子真送郭先輩 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27f0295b-9f57-458e-b6a1-036fe9800ea0', '和蕭郎中午日見寄', '和蕭郎中午日见寄', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["細雨輕風采藥時，褰簾隱几更何爲。","豈知澤畔紉蘭客，來赴城中角黍期。","多罪靜思如剉蘗，赦書纔聽似含飴。","謝公制勝常閑暇，願接西州敵手棊。"]', '["細雨轻风采藥时，褰簾隐几更何爲。","豈知澤畔紉蘭客，来赴城中角黍期。","多罪静思如剉蘗，赦书纔听似含飴。","謝公制勝常闲暇，願接西州敵手棊。"]', '诗', 'shi', '', NULL, '和蕭郎中午日見寄 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86c858b5-6d73-4511-bd0e-c776c13e52e1', '送黃秀才姑孰辟命', '送黄秀才姑孰辟命', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["世亂離情苦，家貧色養難。","水雲孤櫂去，風雨暮春寒。","幕府才方急，騷人淚未乾。","何時王道泰，萬里看鵬摶。"]', '["世亂離情苦，家貧色養难。","水云孤櫂去，风雨暮春寒。","幕府才方急，騷人泪未乾。","何时王道泰，万里看鵬摶。"]', '诗', 'shi', '', NULL, '送黃秀才姑孰辟命 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('650f35ae-fd1e-4d6a-b78f-299069daaf9e', '送王四十五歸東都', '送王四十五归东都', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["海內兵方起，離筵淚易垂。","憐君負米去，惜此落花時。","想憶看來信，相寬指後期。","殷勤手中柳，此是向南枝。"]', '["海內兵方起，離筵泪易垂。","怜君負米去，惜此落花时。","想憶看来信，相寬指後期。","殷勤手中柳，此是向南枝。"]', '诗', 'shi', '', NULL, '送王四十五歸東都 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ee2ecbf-37be-46f3-bb64-c4116751fd03', '和太常蕭少卿近郊馬上偶吟', '和太常蕭少卿近郊马上偶吟', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["田園經雨綠分畦，飛蓋閑行九里堤。","拂袖清風塵不起，滿川芳草路如迷。","林開始覺晴天逈，潮上初驚浦岸齊。","怪得仙郎詩句好，斷霞殘照遠山西。"]', '["田园經雨綠分畦，飞蓋闲行九里堤。","拂袖清风塵不起，满川芳草路如迷。","林开始覺晴天逈，潮上初驚浦岸齊。","怪得仙郎诗句好，斷霞殘照远山西。"]', '诗', 'shi', '', NULL, '和太常蕭少卿近郊馬上偶吟 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c411f8a5-f71e-4e55-b8e1-8bd1309cdfc6', '又和太常蕭少卿近郊馬上偶吟', '又和太常蕭少卿近郊马上偶吟', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["抱甕何人灌藥畦，金銜爲爾駐平堤。","村橋野店景無限，綠水晴天思欲迷。","橫笛乍隨輕吹斷，歸帆疑與遠山齊。","鳳城迴望真堪畫，萬戶千門蔣嶠西。"]', '["抱甕何人灌藥畦，金銜爲爾駐平堤。","村橋野店景無限，綠水晴天思欲迷。","橫笛乍隨轻吹斷，归帆疑與远山齊。","鳳城迴望真堪畫，万戶千门蔣嶠西。"]', '诗', 'shi', '', NULL, '又和太常蕭少卿近郊馬上偶吟 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f5c15d7-fb51-4e1e-ab09-b2a557909a2e', '拋毬樂辭二首 一', '拋毬乐辞二首 一', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["歌舞送飛毬，今觥碧玉籌。","管弦桃李月，簾幕鳳凰樓。","一笑千場醉，浮生任白頭。"]', '["歌舞送飞毬，今觥碧玉籌。","管弦桃李月，簾幕鳳凰楼。","一笑千場醉，浮生任白头。"]', '诗', 'shi', '', NULL, '拋毬樂辭二首 一 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af044393-436b-471b-9b89-52f3d026fa20', '拋毬樂辭二首 二', '拋毬乐辞二首 二', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["灼灼傳花枝，紛紛度畫旗。","不知紅燭下，照見彩毬飛。","借勢因期尅，巫山暮雨歸。"]', '["灼灼傳花枝，紛紛度畫旗。","不知紅燭下，照见彩毬飞。","借勢因期尅，巫山暮雨归。"]', '诗', 'shi', '', NULL, '拋毬樂辭二首 二 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5659dd40-2e53-4060-8051-18f6a9c76a5f', '離歌辭五首 一', '離歌辞五首 一', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["莫折紅芳樹，但知盡意看。","狂風幸無意，那忍折教殘。"]', '["莫折紅芳樹，但知尽意看。","狂风幸無意，那忍折教殘。"]', '诗', 'shi', '', NULL, '離歌辭五首 一 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bca536cb-16fe-464e-85d5-4f517ad8a4d5', '離歌辭五首 二', '離歌辞五首 二', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["朝日城南路，旌旗照綠蕪。","使君何處去，桑下覓羅敷。"]', '["朝日城南路，旌旗照綠蕪。","使君何处去，桑下覓羅敷。"]', '诗', 'shi', '', NULL, '離歌辭五首 二 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dc8e23e-cb42-4c1b-b3f4-61cd30df3cf1', '離歌辭五首 三', '離歌辞五首 三', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["事與年俱往，情將分共深。","莫驚容鬢改，只是舊時心。"]', '["事與年俱往，情將分共深。","莫驚容鬢改，只是旧时心。"]', '诗', 'shi', '', NULL, '離歌辭五首 三 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d4cbe1f-fccc-473e-b9d4-0b1954548ca7', '離歌辭五首 四', '離歌辞五首 四', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["暫別勞相送，佳期願莫違。","朱顏不須老，留取待郎歸。"]', '["暫別勞相送，佳期願莫違。","朱顏不須老，留取待郎归。"]', '诗', 'shi', '', NULL, '離歌辭五首 四 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd77bb34-b7f5-41ff-8768-bdc0ee0f02a5', '離歌辭五首 五', '離歌辞五首 五', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["拂匣收珠佩，迴燈拭薄妝。","莫嫌春夜短，匹似楚襄王。"]', '["拂匣收珠佩，迴灯拭薄妝。","莫嫌春夜短，匹似楚襄王。"]', '诗', 'shi', '', NULL, '離歌辭五首 五 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce1ab385-ac9b-4c73-b63a-b1389c6222f2', '夢游三首 一', '梦游三首 一', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["魂夢悠揚不奈何，夜來還在故人家。","香濛蠟燭時時暗，戶映屏風故故斜。","檀的慢調銀字管，雲鬟低綴折枝花。","天明又作人間別，洞口春深道路賒。"]', '["魂梦悠揚不奈何，夜来還在故人家。","香濛蠟燭时时暗，戶映屏风故故斜。","檀的慢調銀字管，云鬟低綴折枝花。","天明又作人间別，洞口春深道路賒。"]', '诗', 'shi', '', NULL, '夢游三首 一 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e1d1b9f-cd14-4848-b3c3-0404e56a2e22', '夢游三首 二', '梦游三首 二', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["繡幌銀屏杳靄間，若非魂夢到應難。","窗前人靜偏宜夜，戶內春濃不識寒。","蘸甲遰觴纖似玉，含詞忍笑膩於檀。","錦書若要知名字，滿縣花開不姓潘。"]', '["繡幌銀屏杳靄间，若非魂梦到應难。","窗前人静偏宜夜，戶內春濃不識寒。","蘸甲遰觴纖似玉，含词忍笑膩於檀。","錦书若要知名字，满縣花开不姓潘。"]', '诗', 'shi', '', NULL, '夢游三首 二 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('613d1b85-e790-4ad7-89b2-65bfafd5ec41', '夢游三首 三', '梦游三首 三', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["南國佳人字玉兒，芙蓉雙臉遠山眉。","仙郎有約長相憶，阿母何猜不得知。","夢裏行雲還倏忽，暗中攜手乍疑遲。","因思別後閑窗下，織得迴文幾首詩。"]', '["南国佳人字玉兒，芙蓉雙臉远山眉。","仙郎有約长相憶，阿母何猜不得知。","梦裏行云還倏忽，暗中携手乍疑遲。","因思別後闲窗下，织得迴文幾首诗。"]', '诗', 'shi', '', NULL, '夢游三首 三 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('894ac887-5ecf-446e-b51c-a8ea2448e2b9', '和蕭少卿見慶新居', '和蕭少卿见慶新居', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["湘浦懷沙已不疑，京城賜第豈前期。","鼓聲到晚知坊遠，山色來多與靜宜。","簪屨尚應憐故物，稻粱空自媿華池。","新詩問我偏饒思，還念鷦鷯得一枝。"]', '["湘浦懷沙已不疑，京城賜第豈前期。","鼓声到晚知坊远，山色来多與静宜。","簪屨尚應怜故物，稻粱空自媿华池。","新诗问我偏饒思，還念鷦鷯得一枝。"]', '诗', 'shi', '', NULL, '和蕭少卿見慶新居 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1478da3a-f449-4021-bbf0-890eb06c3700', '又和蕭少卿見慶新居', '又和蕭少卿见慶新居', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["驚蓬偶駐知多幸，斷雁重聯愜素期。","當戶小山如舊識，上牆幽蘚最相宜。","清風不去因栽竹，隙地無多也鑿池。","更喜良鄰有嘉樹，綠陰分得近南枝。"]', '["驚蓬偶駐知多幸，斷雁重聯愜素期。","當戶小山如旧識，上牆幽蘚最相宜。","清风不去因栽竹，隙地無多也鑿池。","更喜良鄰有嘉樹，綠陰分得近南枝。"]', '诗', 'shi', '', NULL, '又和蕭少卿見慶新居 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7650d501-76e6-4080-bb06-771540b037a6', '送勳道人之建安', '送勳道人之建安', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["下國兵方起，君家義獨聞。","若爲輕世利，歸去臥溪雲。","挂席衝嵐翠，攜筇破蘚紋。","離情似霜葉，江上正紛紛。"]', '["下国兵方起，君家義独闻。","若爲轻世利，归去臥溪云。","挂席衝嵐翠，携筇破蘚紋。","離情似霜葉，江上正紛紛。"]', '诗', 'shi', '', NULL, '送勳道人之建安 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b8430b1-76b3-4779-a2f2-2103b5a99c4e', '送許郎中歙州判官兼黟縣', '送許郎中歙州判官兼黟縣', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["嘗聞黟縣似桃源，況是優游冠玳筵。","遺愛非遙應臥理，祖風猶在好尋仙。","朝衣舊識熏香史，祿米初營種秫田。","大抵宦游須自適，莫辭離別二三年。"]', '["嘗闻黟縣似桃源，況是優游冠玳筵。","遺愛非遙應臥理，祖风猶在好尋仙。","朝衣旧識熏香史，祿米初營種秫田。","大抵宦游須自適，莫辞離別二三年。"]', '诗', 'shi', '', NULL, '送許郎中歙州判官兼黟縣 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1801a5da-943d-4549-8a89-8eb37000e753', '送彭秀才南游', '送彭秀才南游', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["問君孤櫂去何之，玉笥春風楚水西。","山上斷雲分翠靄，林間晴雲入澄溪。","琴心酒趣神相會，道士仙童手共攜。","他日時清更隨計，莫如劉阮洞中迷。"]', '["问君孤櫂去何之，玉笥春风楚水西。","山上斷云分翠靄，林间晴云入澄溪。","琴心酒趣神相會，道士仙童手共携。","他日时清更隨計，莫如劉阮洞中迷。"]', '诗', 'shi', '', NULL, '送彭秀才南游 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b26bb3dd-61a1-4f44-9a5e-105ef3eb87e1', '和明上人除夜見寄', '和明上人除夜见寄', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["酌酒圍爐久，愁襟默自增。","長年逢歲暮，多病見兵興。","夜色開庭燎，寒威入硯冰。","湯師無別念，吟坐一燈凝。"]', '["酌酒圍爐久，愁襟默自增。","长年逢歲暮，多病见兵兴。","夜色开庭燎，寒威入硯冰。","湯師無別念，吟坐一灯凝。"]', '诗', 'shi', '', NULL, '和明上人除夜見寄 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f08d1d36-3600-43bf-864a-647a95ac2ef2', '正初和鄂州邊郎中見寄', '正初和鄂州邊郎中见寄', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["潦倒含香客，淒涼賦鵩人。","未能全卷舌，終擬學垂綸。","故友暌離久，音書問訊頻。","相思俱老大，又見一年新。"]', '["潦倒含香客，淒涼賦鵩人。","未能全卷舌，終擬学垂綸。","故友暌離久，音书问訊頻。","相思俱老大，又见一年新。"]', '诗', 'shi', '', NULL, '正初和鄂州邊郎中見寄 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe519711-c1b9-4657-addb-f61a1fc8c477', '送劉司直出宰', '送劉司直出宰', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["之子有雄文，風標秀不羣。","低飛從墨綬，逸志在青雲。","柳色臨流動，春光到縣分。","賢人多靜理，未爽醉醺醺。"]', '["之子有雄文，风標秀不羣。","低飞從墨綬，逸志在青云。","柳色臨流动，春光到縣分。","賢人多静理，未爽醉醺醺。"]', '诗', 'shi', '', NULL, '送劉司直出宰 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('198f1dc7-b7a2-4867-bc5d-7966800a2c10', '送從兄赴臨川幕', '送從兄赴臨川幕', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["梁王籍寵就東藩，還召鄒枚坐兔園。","今日好論天下事，昔年同受主人恩。","石頭城下春潮滿，金柅亭邊綠樹繁。","唯有音書慰離別，一盃相送別無言。"]', '["梁王籍寵就东藩，還召鄒枚坐兔园。","今日好論天下事，昔年同受主人恩。","石头城下春潮满，金柅亭邊綠樹繁。","唯有音书慰離別，一盃相送別無言。"]', '诗', 'shi', '', NULL, '送從兄赴臨川幕 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2ef0122-3504-49b1-a9f4-3a610e72f88f', '送龔員外赴江州幕', '送龔員外赴江州幕', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["煩君更上築金臺，世難民勞藉俊才。","自有聲名馳羽檄，不妨談笑奉尊罍。","元規樓迥清風滿，匡俗山春畫障開。","莫忘故人離別恨，海潮迴處寄書來。"]', '["煩君更上築金台，世难民勞藉俊才。","自有声名驰羽檄，不妨談笑奉尊罍。","元規楼迥清风满，匡俗山春畫障开。","莫忘故人離別恨，海潮迴处寄书来。"]', '诗', 'shi', '', NULL, '送龔員外赴江州幕 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bbf3632-36d7-433e-ae3a-6fd8d54d24dd', '送朱先輩尉廬陵', '送朱先輩尉廬陵', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["我重朱夫子，依然見古人。","成名無媿色，得祿及慈親。","莫歎官資屈，寧論活計貧。","平生心氣在，終任靜邊塵。"]', '["我重朱夫子，依然见古人。","成名無媿色，得祿及慈親。","莫歎官資屈，寧論活計貧。","平生心氣在，終任静邊塵。"]', '诗', 'shi', '', NULL, '送朱先輩尉廬陵 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('436420ba-25e7-4b51-be89-b1b9565f9678', '送鍾德林郎中學士赴東府詩 得酒', '送鍾德林郎中学士赴东府诗 得酒', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["酌此盃中物，茱萸滿把秋。","今朝將送別，他日是忘憂。","世亂方多事，年加易得愁。","政成頻一醉，亦未減風流。"]', '["酌此盃中物，茱萸满把秋。","今朝將送別，他日是忘憂。","世亂方多事，年加易得愁。","政成頻一醉，亦未減风流。"]', '诗', 'shi', '', NULL, '送鍾德林郎中學士赴東府詩 得酒 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c21c26c8-2b73-411f-a006-2a8044065681', '送陳先生之洪井寄蕭少卿', '送陳先生之洪井寄蕭少卿', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["聞君仙袂指洪厓，我憶情人別路賒。","知有歡娛游楚澤，更無書札到京華。","雲開驛閣連江靜，春滿西山倚漢斜。","此處相逢應見問，爲言搔首望龍沙。"]', '["闻君仙袂指洪厓，我憶情人別路賒。","知有歡娛游楚澤，更無书札到京华。","云开驛閣連江静，春满西山倚漢斜。","此处相逢應见问，爲言搔首望龙沙。"]', '诗', 'shi', '', NULL, '送陳先生之洪井寄蕭少卿 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4837f8c0-725d-44ff-8056-440f706860d5', '送龔明府九江歸寧', '送龔明府九江归寧', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["茂宰隳官去，扁舟著綵衣。","湓城春酒熟，匡阜野花稀。","解纜垂楊綠，開帆宿鷺飛。","一朝吾道泰，還逐落潮歸。"]', '["茂宰隳官去，扁舟著綵衣。","湓城春酒熟，匡阜野花稀。","解纜垂楊綠，开帆宿鷺飞。","一朝吾道泰，還逐落潮归。"]', '诗', 'shi', '', NULL, '送龔明府九江歸寧 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc824129-49cd-4835-9a1c-75b9efd09e92', '和江西蕭少卿見寄二首 一', '和江西蕭少卿见寄二首 一', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["亡羊岐路媿司南，二紀窮通聚散三。","老去何妨從笑傲，病來看欲嬾朝參。","離腸似線常憂斷，世態如湯不可探。","珍重加餐省思慮，時時斟酒壓山嵐。"]', '["亡羊岐路媿司南，二紀窮通聚散三。","老去何妨從笑傲，病来看欲嬾朝參。","離腸似線常憂斷，世態如湯不可探。","珍重加餐省思慮，时时斟酒壓山嵐。"]', '诗', 'shi', '', NULL, '和江西蕭少卿見寄二首 一 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41380de0-b83c-4100-9f80-9d7c6c554dbd', '和江西蕭少卿見寄二首 二', '和江西蕭少卿见寄二首 二', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["身遙上國三千里，名在朝中二十春。","金印不須辭入幕，麻衣曾此歎迷津。","卷舒由我真齊物，憂喜忘心即養神。","世路風波自飜覆，虛舟無計得沉淪。"]', '["身遙上国三千里，名在朝中二十春。","金印不須辞入幕，麻衣曾此歎迷津。","卷舒由我真齊物，憂喜忘心即養神。","世路风波自飜覆，虛舟無計得沉淪。"]', '诗', 'shi', '', NULL, '和江西蕭少卿見寄二首 二 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3811f14a-e515-4812-bbdd-c002ef38fced', '送薛少卿赴青陽', '送薛少卿赴青陽', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["我愛陶靖節，吏隱從弦歌。","我愛費徵君，高臥歸九華。","清風激頹波，來者無以加。","我志兩不遂，漂淪浩無涯。","數奇時且亂，此圖今愈賒。","賢哉薛夫子，高舉凌晨霞。","安民即是道，投足皆爲家。","功名與權位，悠悠何用誇。","攜朋出遠郊，酌酒藉平沙。","雲收遠天靜，江闊片帆斜。","離懷與企羨，南望長咨嗟。"]', '["我愛陶靖節，吏隐從弦歌。","我愛費徵君，高臥归九华。","清风激頹波，来者無以加。","我志兩不遂，漂淪浩無涯。","數奇时且亂，此圖今愈賒。","賢哉薛夫子，高舉凌晨霞。","安民即是道，投足皆爲家。","功名與權位，悠悠何用誇。","携朋出远郊，酌酒藉平沙。","云收远天静，江闊片帆斜。","離懷與企羨，南望长咨嗟。"]', '诗', 'shi', '', NULL, '送薛少卿赴青陽 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1700c6ac-d3ea-4c25-a2a6-a30b311a9a30', '送高起居之涇縣', '送高起居之涇縣', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["右史罷朝歸，之官句水湄。","別我行千里，送君傾一巵。","酒罷長歎息，此歎君應悲。","亂中吾道薄，卿族舊人稀。","胡爲佩銅墨，去此白玉墀。","吏事豈所堪，民病何可醫。","藏用清其心，此外慎勿爲。","縣郭有佳境，千峰谿水西。","雲樹杳迴合，巖巒互蔽虧。","彈琴坐其中，世事吾不知。","時時寄書札，以慰長相思。"]', '["右史罷朝归，之官句水湄。","別我行千里，送君傾一巵。","酒罷长歎息，此歎君應悲。","亂中吾道薄，卿族旧人稀。","胡爲佩銅墨，去此白玉墀。","吏事豈所堪，民病何可醫。","藏用清其心，此外慎勿爲。","縣郭有佳境，千峰谿水西。","云樹杳迴合，巖巒互蔽虧。","彈琴坐其中，世事吾不知。","时时寄书札，以慰长相思。"]', '诗', 'shi', '', NULL, '送高起居之涇縣 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('979841ff-c472-4438-b55f-d4684c8d8a1a', '宿茅山寄舍弟', '宿茅山寄舍弟', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["茅許稟靈氣，一家同上賓。","仙山空有廟，舉世更無人。","獨往誠違俗，浮名亦累真。","當年各自勉，雲洞鎮長春。"]', '["茅許稟靈氣，一家同上賓。","仙山空有廟，舉世更無人。","独往誠違俗，浮名亦累真。","當年各自勉，云洞鎮长春。"]', '诗', 'shi', '', NULL, '宿茅山寄舍弟 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48e7b842-bbb5-4eeb-a1ed-9034324d098d', '晚憇白鶴廟寄句容張少府', '晚憇白鹤廟寄句容張少府', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["日入林初靜，山空暑更寒。","泉鳴細巖竇，鶴淚眇雲端。","拂榻安棊局，焚香戴道冠。","望君殊不見，終夕憑欄干。"]', '["日入林初静，山空暑更寒。","泉鳴細巖竇，鹤泪眇云端。","拂榻安棊局，焚香戴道冠。","望君殊不见，終夕憑欄干。"]', '诗', 'shi', '', NULL, '晚憇白鶴廟寄句容張少府 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52e35538-5a11-4789-a967-de60c3fa7ab1', '題紫陽觀', '題紫陽观', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["南朝名士富仙才，追步東卿遂不迴。","丹井自深桐暗老，祠宮長在鶴頻來。","巖邊桂樹攀仍倚，洞口桃花落復開。","惆悵霓裳太平事，一函真跡鎖昭臺。"]', '["南朝名士富仙才，追步东卿遂不迴。","丹井自深桐暗老，祠宮长在鹤頻来。","巖邊桂樹攀仍倚，洞口桃花落复开。","惆悵霓裳太平事，一函真跡鎖昭台。"]', '诗', 'shi', '', NULL, '題紫陽觀 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e582ea3-2c9b-4c36-9f8c-5eb1324077ea', '贈奚道士', '贈奚道士', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["先生曾有洞天期，猶傍天壇摘紫芝。","處世自能心混沌，全真誰見德支離。","玉霄塵閉人長在，全鼎功成俗未知。","他日飆輪謁茅許，願同雞犬去相隨。"]', '["先生曾有洞天期，猶傍天壇摘紫芝。","处世自能心混沌，全真誰见德支離。","玉霄塵閉人长在，全鼎功成俗未知。","他日飆輪謁茅許，願同雞犬去相隨。"]', '诗', 'shi', '', NULL, '贈奚道士 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04e02701-4756-4b1f-a48c-606055d6ec56', '題碧巖亭贈孫尊師', '題碧巖亭贈孫尊師', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["絕境何人識，高亭萬象含。","凭軒臨樹杪，送目極天南。","積靄生泉洞，歸雲鎖石龕。","丹霞披翠巘，白鳥帶晴嵐。","仙去留虛室，龍歸漲碧潭。","幽巖君獨愛，玄味我曾耽。","世上愁何限，人間事久諳。","終須脫羈鞅，來此會空談。"]', '["絕境何人識，高亭万象含。","凭軒臨樹杪，送目極天南。","積靄生泉洞，归云鎖石龕。","丹霞披翠巘，白鸟带晴嵐。","仙去留虛室，龙归漲碧潭。","幽巖君独愛，玄味我曾耽。","世上愁何限，人间事久諳。","終須脫羈鞅，来此會空談。"]', '诗', 'shi', '', NULL, '題碧巖亭贈孫尊師 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03a32e51-7918-4afc-9df7-ade594eece09', '題白鶴廟', '題白鹤廟', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["平生心事向玄關，一入仙鄉似舊山。","白鶴淚空晴眇眇，丹沙流澗暮潺潺。","嘗嗟多病嫌中藥，擬問真經乞小還。","滿洞煙霞互陵亂，何峰臺榭是蕭閑。"]', '["平生心事向玄关，一入仙乡似旧山。","白鹤泪空晴眇眇，丹沙流澗暮潺潺。","嘗嗟多病嫌中藥，擬问真經乞小還。","满洞煙霞互陵亂，何峰台榭是蕭闲。"]', '诗', 'shi', '', NULL, '題白鶴廟 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f73cc22-385d-440f-97e6-117507a4313e', '步虛詞五首 一', '步虛词五首 一', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["氣爲還元正，心由抱一靈。","凝神歸罔象，飛步入青冥。","整服乘三素，旋綱躡九星。","瓊章開後學，稽首奉真經。"]', '["氣爲還元正，心由抱一靈。","凝神归罔象，飞步入青冥。","整服乘三素，旋綱躡九星。","瓊章开後学，稽首奉真經。"]', '诗', 'shi', '', NULL, '步虛詞五首 一 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a2a1af4-2dea-420b-bd1e-f67d7ffaa6f1', '步虛詞五首 二', '步虛词五首 二', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["天帝黃金闕，真人紫錦書。","霓裳紛蔽景，羽服迥凌虛。","白鶴能爲使，班麟解駕車。","靈符終願借，轉共世情疎。"]', '["天帝黄金闕，真人紫錦书。","霓裳紛蔽景，羽服迥凌虛。","白鹤能爲使，班麟解駕车。","靈符終願借，轉共世情疎。"]', '诗', 'shi', '', NULL, '步虛詞五首 二 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f650df59-7c25-47c7-a5b9-740660d8a8cb', '步虛詞五首 三', '步虛词五首 三', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["聖主過幽谷，虛皇在蘂宮。","五千宗物母，七字祕神童。","世上金壺遠，人間玉籥空。","唯餘養身法，修此與天通。"]', '["聖主過幽谷，虛皇在蘂宮。","五千宗物母，七字祕神童。","世上金壺远，人间玉籥空。","唯餘養身法，修此與天通。"]', '诗', 'shi', '', NULL, '步虛詞五首 三 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a1e41a2-28af-4124-abf5-2a1863a84a69', '步虛詞五首 四', '步虛词五首 四', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["何處求玄解，人間有洞天。","勤行皆是道，謫下尚爲仙。","蔽景乘朱鳳，排虛駕紫煙。","不嫌園吏傲，願在玉宸前。"]', '["何处求玄解，人间有洞天。","勤行皆是道，謫下尚爲仙。","蔽景乘朱鳳，排虛駕紫煙。","不嫌园吏傲，願在玉宸前。"]', '诗', 'shi', '', NULL, '步虛詞五首 四 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fb969ca-d33e-4959-a258-1537421368a3', '步虛詞五首 五', '步虛词五首 五', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["三素霏霏遠，盟威凜凜寒。","火鈴空滅沒，星斗曉闌干。","佩響流虛殿，爐煙在醮壇。","蕭寥不可極，驂駕上雲端。"]', '["三素霏霏远，盟威凜凜寒。","火鈴空滅沒，星斗晓闌干。","佩响流虛殿，爐煙在醮壇。","蕭寥不可極，驂駕上云端。"]', '诗', 'shi', '', NULL, '步虛詞五首 五 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15319d9e-68fd-4e8e-bfed-683c5898c1e1', '留題仙觀', '留題仙观', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["瑤壇醮罷晚雲開，羽客分飛俗士迴。","爲報移文不須勒，未曾游處待重來。"]', '["瑤壇醮罷晚云开，羽客分飞俗士迴。","爲報移文不須勒，未曾游处待重来。"]', '诗', 'shi', '', NULL, '留題仙觀 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56249038-41cc-4204-b4da-beafc26a9010', '和陳洗馬山莊新泉', '和陳洗马山莊新泉', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["已開山館待抽簪，更要巖泉欲洗心。","常被松聲迷細韻，忽流花片落高岑。","便疏淺瀨穿莎徑，始有清光映竹林。","何日煎茶醞香酒，沙邊同聽暝猨吟。"]', '["已开山館待抽簪，更要巖泉欲洗心。","常被松声迷細韻，忽流花片落高岑。","便疏淺瀨穿莎徑，始有清光映竹林。","何日煎茶醞香酒，沙邊同听暝猨吟。"]', '诗', 'shi', '', NULL, '和陳洗馬山莊新泉 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c196cad-4746-4204-8e01-9e73b9ed11e0', '奉和七夕應令', '奉和七夕應令', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["今宵星漢共晶光，應笑羅敷嫁侍郎。","斗柄易傾離恨促，河流不盡後期長。","靜聞天籟疑鳴佩，醉折荷花想豔妝。","誰見宣猷堂上宴，一篇清韻振金鐺。"]', '["今宵星漢共晶光，應笑羅敷嫁侍郎。","斗柄易傾離恨促，河流不尽後期长。","静闻天籟疑鳴佩，醉折荷花想豔妝。","誰见宣猷堂上宴，一篇清韻振金鐺。"]', '诗', 'shi', '', NULL, '奉和七夕應令 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0473eff7-13cb-446a-a88c-efa71721c4d1', '又和八日', '又和八日', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["微雲疎雨淡新秋，曉夢依稀十二樓。","故作別離應有以，擬延更漏共無由。","那教人世長多恨，未必天仙不解愁。","博望苑中殘酒醒，香風佳氣獨遲留。"]', '["微云疎雨淡新秋，晓梦依稀十二楼。","故作別離應有以，擬延更漏共無由。","那教人世长多恨，未必天仙不解愁。","博望苑中殘酒醒，香风佳氣独遲留。"]', '诗', 'shi', '', NULL, '又和八日 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49bbcbdc-447f-46d3-a949-1cf5fb0491ab', '和印先輩及第後獻座主朱舍人郊居之作', '和印先輩及第後獻座主朱舍人郊居之作', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["成名郊外掩柴扉，樹影蟬聲共息機。","積雨暗封青蘚徑，好風輕透白{糹朿}衣。","嘉魚始賦人爭誦，荆玉頻收國自肥。","獨坐公廳正煩暑，喜吟新詠見玄微。"]', '["成名郊外掩柴扉，樹影蟬声共息機。","積雨暗封青蘚徑，好风轻透白{糹朿}衣。","嘉鱼始賦人爭誦，荆玉頻收国自肥。","独坐公廳正煩暑，喜吟新詠见玄微。"]', '诗', 'shi', '', NULL, '和印先輩及第後獻座主朱舍人郊居之作 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('917cea25-0fcd-4642-aa95-efb0627c6636', '和致仕張尚書新創道院', '和致仕張尚书新創道院', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["梓澤成新致，金丹有舊情。","挂冠朝睡足，隱几暮江清。","藥圃分輕綠，松窗起細聲。","養高寧厭病，默坐對諸生。"]', '["梓澤成新致，金丹有旧情。","挂冠朝睡足，隐几暮江清。","藥圃分轻綠，松窗起細声。","養高寧厭病，默坐对諸生。"]', '诗', 'shi', '', NULL, '和致仕張尚書新創道院 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3949a1fe-943b-4534-8388-18e594f57c80', '和尉遲贊善秋暮僻居', '和尉遲贊善秋暮僻居', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["登高節物最堪憐，小嶺疎林對檻前。","輕吹斷時雲縹緲，夕陽明處水澄鮮。","江城秋早催寒事，望苑朝稀足晏眠。","庭有菊花尊有酒，若方陶令媿前賢。"]', '["登高節物最堪怜，小嶺疎林对檻前。","轻吹斷时云縹緲，夕陽明处水澄鲜。","江城秋早催寒事，望苑朝稀足晏眠。","庭有菊花尊有酒，若方陶令媿前賢。"]', '诗', 'shi', '', NULL, '和尉遲贊善秋暮僻居 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebe7a94b-449b-442b-b180-65268641ba3b', '和陳贊善致仕還京口', '和陳贊善致仕還京口', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["海門山下一漁舟，中有高人未白頭。","已駕安車歸故里，尚通閨籍在龍樓。","泉聲漱玉窗前落，江色和煙檻外流。","今日君臣厚終始，不須辛苦畫雙牛。"]', '["海门山下一漁舟，中有高人未白头。","已駕安车归故里，尚通閨籍在龙楼。","泉声漱玉窗前落，江色和煙檻外流。","今日君臣厚終始，不須辛苦畫雙牛。"]', '诗', 'shi', '', NULL, '和陳贊善致仕還京口 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28f23d8f-40ca-46ad-b09e-fde005322898', '京使迴自臨川得從兄書寄詩依韻和', '京使迴自臨川得從兄书寄诗依韻和', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["珍重還京使，殷勤話故人。","別離長挂夢，寵祿不關身。","趣向今成道，聲華舊絕塵。","莫嗟客鬢老，詩句逐時新。"]', '["珍重還京使，殷勤話故人。","別離长挂梦，寵祿不关身。","趣向今成道，声华旧絕塵。","莫嗟客鬢老，诗句逐时新。"]', '诗', 'shi', '', NULL, '京使迴自臨川得從兄書寄詩依韻和 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfd40774-c6d4-4068-823c-7ae5546f7694', '陪鄭王相公賦筵前垂冰應教依韻', '陪鄭王相公賦筵前垂冰應教依韻', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["窗外虛明雪乍晴，簷前垂霤盡成冰。","長廊瓦疊行行密，晚院風高寸寸增。","玉指乍拈簪尚媿，金階時墜磬難勝。","晨餐堪醒曹參酒，自恨空腸病不能。"]', '["窗外虛明雪乍晴，簷前垂霤尽成冰。","长廊瓦叠行行密，晚院风高寸寸增。","玉指乍拈簪尚媿，金階时墜磬难勝。","晨餐堪醒曹參酒，自恨空腸病不能。"]', '诗', 'shi', '', NULL, '陪鄭王相公賦筵前垂冰應教依韻 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17e63a26-31d8-4b39-9211-8962b8e463de', '送禮部潘尚書致仕還建安', '送禮部潘尚书致仕還建安', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["名遂功成累復輕，鱸魚因起舊鄉情。","履聲初下金華省，帆影看離石首城。","化劒津頭尋故老，同亭會上問仙卿。","冥鴻高舉真難事，相送何須淚滿纓。"]', '["名遂功成累复轻，鱸鱼因起旧乡情。","履声初下金华省，帆影看離石首城。","化劒津头尋故老，同亭會上问仙卿。","冥鴻高舉真难事，相送何須泪满纓。"]', '诗', 'shi', '', NULL, '送禮部潘尚書致仕還建安 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cb8c0e9-4917-48ee-829e-6a39c4cf838f', '和尉遲贊善病中見寄', '和尉遲贊善病中见寄', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["仙郎移病暑天過，却似冥鴻避罻羅。","晝夢乍驚風動竹，夜吟時覺露霑莎。","情親稍喜貧居近，性嬾猶嫌上直多。","望苑恩深期勿藥，青雲岐路未蹉跎。"]', '["仙郎移病暑天過，却似冥鴻避罻羅。","晝梦乍驚风动竹，夜吟时覺露霑莎。","情親稍喜貧居近，性嬾猶嫌上直多。","望苑恩深期勿藥，青云岐路未蹉跎。"]', '诗', 'shi', '', NULL, '和尉遲贊善病中見寄 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da6b1336-d7a6-462b-be11-97ba89365cde', '池州陳使君見示游齊山詩因寄', '池州陳使君见示游齊山诗因寄', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["往歲曾游弄水亭，齊峰濃翠暮軒橫。","哀猨出檻心雖喜，傷鳥聞弦勢易驚。","病後簪纓殊寡興，老來泉石倍關情。","今朝池口風波靜，遙賀山前有頌聲。"]', '["往歲曾游弄水亭，齊峰濃翠暮軒橫。","哀猨出檻心雖喜，傷鸟闻弦勢易驚。","病後簪纓殊寡兴，老来泉石倍关情。","今朝池口风波静，遙賀山前有頌声。"]', '诗', 'shi', '', NULL, '池州陳使君見示游齊山詩因寄 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d713cdb5-e584-49c5-a66c-c879cb8ea192', '再領制誥和王明府見賀', '再領制誥和王明府见賀', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["蹇步還依列宿邊，拱辰重認舊雲天。","自嗟多難飄零困，不似當年膽氣全。","雞樹晚花疎向日，龍池輕浪細含煙。","從來不解爲身計，一葉悠悠任大川。"]', '["蹇步還依列宿邊，拱辰重認旧云天。","自嗟多难飄零困，不似當年膽氣全。","雞樹晚花疎向日，龙池轻浪細含煙。","從来不解爲身計，一葉悠悠任大川。"]', '诗', 'shi', '', NULL, '再領制誥和王明府見賀 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36ec9510-4972-452b-9b4e-4735f0004400', '送高舍人使嶺南', '送高舍人使嶺南', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["西掖官曹近，南溟道路遙。","使星將渡漢，仙櫂乍乘潮。","柳映靈和折，梅依大庾飄。","江帆風淅淅，山館雨蕭蕭。","陸賈真迂闊，終童久寂寥。","送君何限意，把酒一長謠。"]', '["西掖官曹近，南溟道路遙。","使星將渡漢，仙櫂乍乘潮。","柳映靈和折，梅依大庾飄。","江帆风淅淅，山館雨蕭蕭。","陸賈真迂闊，終童久寂寥。","送君何限意，把酒一长謠。"]', '诗', 'shi', '', NULL, '送高舍人使嶺南 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa136d3a-d5ec-46ca-9811-4c6e8122141d', '和王明府見寄', '和王明府见寄', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["時情世難消吾道，薄宦流年危此身。","莫歎京華同寂寞，曾經兵革共漂淪。","對山開戶唯求靜，貰酒留賓不道貧。","善政空多尚淹屈，不知誰是解憂民。"]', '["时情世难消吾道，薄宦流年危此身。","莫歎京华同寂寞，曾經兵革共漂淪。","对山开戶唯求静，貰酒留賓不道貧。","善政空多尚淹屈，不知誰是解憂民。"]', '诗', 'shi', '', NULL, '和王明府見寄 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6e122c0-60da-4c74-ac6d-0e70eb314b25', '和方泰州見寄', '和方泰州见寄', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["逐客悽悽重入京，舊愁新恨兩難勝。","雲收楚塞千山雪，風結秦淮一尺冰。","置醴筵空情豈盡，投湘文就思如凝。","更殘月落知孤坐，遙望船窗一點星。"]', '["逐客悽悽重入京，旧愁新恨兩难勝。","云收楚塞千山雪，风結秦淮一尺冰。","置醴筵空情豈尽，投湘文就思如凝。","更殘月落知孤坐，遙望船窗一点星。"]', '诗', 'shi', '', NULL, '和方泰州見寄 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69cca25d-18d1-4793-a06e-604880a23be0', '文獻太子挽歌詞五首 一', '文獻太子挽歌词五首 一', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["國有承祧重，人知秉哲尊。","清風來望苑，遺烈在東藩。","此日升緱嶺，何因到寢門。","天高不可問，煙靄共昏昏。"]', '["国有承祧重，人知秉哲尊。","清风来望苑，遺烈在东藩。","此日升緱嶺，何因到寢门。","天高不可问，煙靄共昏昏。"]', '诗', 'shi', '', NULL, '文獻太子挽歌詞五首 一 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89777efb-ae9d-4ee3-9176-90d396a8b660', '文獻太子挽歌詞五首 二', '文獻太子挽歌词五首 二', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["夏啓吾君子，周儲上帝賓。","音容一飄忽，功業自紛綸。","露泣承華月，風驚麗正塵。","空餘商嶺客，行淚下宜春。"]', '["夏啓吾君子，周儲上帝賓。","音容一飄忽，功業自紛綸。","露泣承华月，风驚丽正塵。","空餘商嶺客，行泪下宜春。"]', '诗', 'shi', '', NULL, '文獻太子挽歌詞五首 二 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d90f7b1-7943-4e36-9d37-88856a2180f9', '文獻太子挽歌詞五首 三', '文獻太子挽歌词五首 三', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["出處成交讓，經綸有大功。","淚碑瓜步北，棠樹蒜山東。","百揆方時敘，重離遂不融。","故臣偏感咽，曾是歎三窮。"]', '["出处成交讓，經綸有大功。","泪碑瓜步北，棠樹蒜山东。","百揆方时敘，重離遂不融。","故臣偏感咽，曾是歎三窮。"]', '诗', 'shi', '', NULL, '文獻太子挽歌詞五首 三 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c18f4071-2e78-42f5-946f-bf23d73457cb', '文獻太子挽歌詞五首 四', '文獻太子挽歌词五首 四', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["甲觀光陰促，園陵天地長。","簫笳咽無韻，賓御哭相將。","盛烈傳彝鼎，遺文被樂章。","君臣知己分，零淚亂無行。"]', '["甲观光陰促，园陵天地长。","簫笳咽無韻，賓御哭相將。","盛烈傳彝鼎，遺文被乐章。","君臣知己分，零泪亂無行。"]', '诗', 'shi', '', NULL, '文獻太子挽歌詞五首 四 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6360316-739d-4a9f-b76b-d9864105845e', '文獻太子挽歌詞五首 五', '文獻太子挽歌词五首 五', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["綵仗清晨出，非同齒胄時。","愁煙鎖平甸，朔吹繞寒枝。","楚客來何補，緱山去莫追。","迴瞻飛蓋處，掩袂不勝悲。"]', '["綵仗清晨出，非同齒胄时。","愁煙鎖平甸，朔吹繞寒枝。","楚客来何補，緱山去莫追。","迴瞻飞蓋处，掩袂不勝悲。"]', '诗', 'shi', '', NULL, '文獻太子挽歌詞五首 五 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19a16376-720f-4dc6-ab80-6011988e368d', '送王員外宰德安', '送王員外宰德安', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["家世朱門貴，官資粉署優。","今爲百里長，應好五峰游。","柳影連彭澤，湖光接庾樓。","承明須再入，官滿莫淹留。"]', '["家世朱门貴，官資粉署優。","今爲百里长，應好五峰游。","柳影連彭澤，湖光接庾楼。","承明須再入，官满莫淹留。"]', '诗', 'shi', '', NULL, '送王員外宰德安 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f58a1b4-3e9d-49ba-9a4c-045ad3dde435', '以端谿硯酬張員外水精珠兼和來篇', '以端谿硯酬張員外水精珠兼和来篇', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["請以端谿潤，酬君水玉明。","方圓雖異器，功用信俱呈。","自得山川秀，能分日月精。","巾箱各珍重，所貴在交情。"]', '["請以端谿潤，酬君水玉明。","方圓雖異器，功用信俱呈。","自得山川秀，能分日月精。","巾箱各珍重，所貴在交情。"]', '诗', 'shi', '', NULL, '以端谿硯酬張員外水精珠兼和來篇 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c90ba907-6132-4cad-a81d-37b2a7413e87', '奉使九華山中途遇青陽薛郎中', '奉使九华山中途遇青陽薛郎中', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["故人相別動相思，此地相逢豈素期。","九子峰前閑未得，五谿橋上坐多時。","甘泉從幸余知忝，宣室徵還子未遲。","且飲一盃消別恨，野花風起漸離披。"]', '["故人相別动相思，此地相逢豈素期。","九子峰前闲未得，五谿橋上坐多时。","甘泉從幸余知忝，宣室徵還子未遲。","且饮一盃消別恨，野花风起漸離披。"]', '诗', 'shi', '', NULL, '奉使九華山中途遇青陽薛郎中 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de6f64dd-f04e-4620-a646-f68c7bdb9778', '奉命南使經彭澤', '奉命南使經彭澤', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["遠使程途未一分，離心常要醉醺醺。","那堪彭澤門前立，黃菊蕭疎不見君。"]', '["远使程途未一分，離心常要醉醺醺。","那堪彭澤门前立，黄菊蕭疎不见君。"]', '诗', 'shi', '', NULL, '奉命南使經彭澤 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adee5df9-b6e2-4040-bd7e-795018a65293', '南都遇前嘉魚劉令言游閩嶺作此與之', '南都遇前嘉鱼劉令言游閩嶺作此與之', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["我持使節經韶石，君作閑游過武夷。","兩地山光成獨賞，隔年鄉思暗相知。","洪厓壇上長岑寂，孺子亭前自別離。","珍重分岐一盃酒，強加餐飯數吟詩。"]', '["我持使節經韶石，君作闲游過武夷。","兩地山光成独賞，隔年乡思暗相知。","洪厓壇上长岑寂，孺子亭前自別離。","珍重分岐一盃酒，強加餐飯數吟诗。"]', '诗', 'shi', '', NULL, '南都遇前嘉魚劉令言游閩嶺作此與之 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6d0c77b-5307-45b7-b11f-707de7db4eb8', '閣皁山', '閣皁山', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["殿影高低雲掩映，松陰繚繞步徘徊。","從今莫厭簪裾累，不是乘軺不得來。"]', '["殿影高低云掩映，松陰繚繞步徘徊。","從今莫厭簪裾累，不是乘軺不得来。"]', '诗', 'shi', '', NULL, '閣皁山 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efca8adc-8a81-4453-88ac-be385d18d83f', '玉笥山留題', '玉笥山留題', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["仙鄉會應遠，王事知何極。","征傳莫辭勞，玉峰聊一息。","形骸已銷散，心想都凝寂。","真氣自清虛，非關好松石。","九仙皆積學，洞壑多遺跡。","游子歸去來，胡爲但征役。"]', '["仙乡會應远，王事知何極。","征傳莫辞勞，玉峰聊一息。","形骸已銷散，心想都凝寂。","真氣自清虛，非关好松石。","九仙皆積学，洞壑多遺跡。","游子归去来，胡爲但征役。"]', '诗', 'shi', '', NULL, '玉笥山留題 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d46d156-ae59-41e3-9953-3e6469ac8b1b', '廬陵別朱觀先輩', '廬陵別朱观先輩', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["桂籍知名有幾人，翻飛相續上青雲。","解憐才子寧唯我，遠作卑官尚見君。","嶺外獨持嚴助節，宮中誰薦長卿文。","新詩試爲重高詠，朝漢臺前不可聞。"]', '["桂籍知名有幾人，翻飞相續上青云。","解怜才子寧唯我，远作卑官尚见君。","嶺外独持嚴助節，宮中誰薦长卿文。","新诗試爲重高詠，朝漢台前不可闻。"]', '诗', 'shi', '', NULL, '廬陵別朱觀先輩 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eec11621-65b0-4bc9-b09a-727d8402979a', '文彧少卿文山郎中交好深至二紀已餘暌別數年二子長逝奉使嶺表途次南康弔孫氏之孤於其家覩文彧手書於僧室慷慨悲歎留題此詩', '文彧少卿文山郎中交好深至二紀已餘暌別數年二子长逝奉使嶺表途次南康弔孫氏之孤於其家覩文彧手书於僧室慷慨悲歎留題此诗', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["孫家虛坐弔諸孤，張叟僧房見手書。","二紀歡游今若此，滿衣零淚欲何如。","腰間金印從如斗，鏡裏霜華已滿梳。","珍重遠公應笑我，塵心唯此未能除。"]', '["孫家虛坐弔諸孤，張叟僧房见手书。","二紀歡游今若此，满衣零泪欲何如。","腰间金印從如斗，镜裏霜华已满梳。","珍重远公應笑我，塵心唯此未能除。"]', '诗', 'shi', '', NULL, '文彧少卿文山郎中交好深至二紀已餘暌別數年二子長逝奉使嶺表途次南康弔孫氏之孤於其家覩文彧手書於僧室慷慨悲歎留題此詩 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6f800a0-9799-4101-8879-aefeedae2fb4', '朱處士相與有山水之願見送至南康作此以別之', '朱处士相與有山水之願见送至南康作此以別之', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["憐君送我至南康，更憶梅花庾嶺芳。","多少仙山共遊在，願君百歲尚康強。"]', '["怜君送我至南康，更憶梅花庾嶺芳。","多少仙山共游在，願君百歲尚康強。"]', '诗', 'shi', '', NULL, '朱處士相與有山水之願見送至南康作此以別之 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a27233e-bddd-458e-9307-3bfd0ee29a26', '清明日清遠峽作', '清明日清远峽作', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["嶺外春過半，途中火又新。","殷勤清遠峽，留戀北歸人。"]', '["嶺外春過半，途中火又新。","殷勤清远峽，留戀北归人。"]', '诗', 'shi', '', NULL, '清明日清遠峽作 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b66c765-3223-4567-afeb-453e0c543da8', '迴至南康題紫極宮裏道士房', '迴至南康題紫極宮裏道士房', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["王事信靡盬，飲冰安足辭。","胡爲擁征傳，乃至天南陲。","天南非我鄉，留滯忽踰時。","還經羽人家，豁若雲霧披。","何以寬吾懷，老莊有微詞。","達士無不可，至人豈偏爲。","客愁勿復道，爲君吟此詩。"]', '["王事信靡盬，饮冰安足辞。","胡爲擁征傳，乃至天南陲。","天南非我乡，留滯忽踰时。","還經羽人家，豁若云霧披。","何以寬吾懷，老莊有微词。","達士無不可，至人豈偏爲。","客愁勿复道，爲君吟此诗。"]', '诗', 'shi', '', NULL, '迴至南康題紫極宮裏道士房 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57e77fa9-6785-44a8-a469-a9899489e2ba', '和歙州陳使君見寄', '和歙州陳使君见寄', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["新安風景好，時令肅轅門。","身貴心彌下，功多口不言。","韜鈐家法在，儒雅素風存。","簪履陪游盛，鄉閭俗化敦。","臨窗山色秀，繞郭水聲喧。","織絡文章麗，矜嚴道義尊。","樓臺秋月靜，京庾晚雲屯。","曉吹傳衙鼓，晴陽展信旛。","一篇貽友好，千里倍心論。","未見歸驂動，空能役夢魂。"]', '["新安风景好，时令肅轅门。","身貴心彌下，功多口不言。","韜鈐家法在，儒雅素风存。","簪履陪游盛，乡閭俗化敦。","臨窗山色秀，繞郭水声喧。","织絡文章丽，矜嚴道義尊。","楼台秋月静，京庾晚云屯。","晓吹傳衙鼓，晴陽展信旛。","一篇貽友好，千里倍心論。","未见归驂动，空能役梦魂。"]', '诗', 'shi', '', NULL, '和歙州陳使君見寄 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41fb0aed-7aca-41f5-bc55-02de8afb4197', '和賈員外戩見贈玉蘂花栽', '和賈員外戩见贈玉蘂花栽', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["瓊瑤一簇帶花來，便斸蒼苔手自栽。","喜見唐昌舊顏色，爲君判病酌金罍。"]', '["瓊瑤一簇带花来，便斸蒼苔手自栽。","喜见唐昌旧顏色，爲君判病酌金罍。"]', '诗', 'shi', '', NULL, '和賈員外戩見贈玉蘂花栽 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('938e761f-ef00-4b60-a759-987977885f08', '光穆皇后挽歌三首 一', '光穆皇后挽歌三首 一', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["仙馭期難改，坤儀道自光。","閟宮新表德，沙麓舊膺祥。","素帟堯門掩，凝笳畢陌長。","東風慘陵樹，無復見親桑。"]', '["仙馭期难改，坤儀道自光。","閟宮新表德，沙麓旧膺祥。","素帟堯门掩，凝笳畢陌长。","东风慘陵樹，無复见親桑。"]', '诗', 'shi', '', NULL, '光穆皇后挽歌三首 一 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bde1bb7-e04d-4817-91f2-9d7d61486fb9', '光穆皇后挽歌三首 二', '光穆皇后挽歌三首 二', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["永樂留虛位，長陵啓夕扉。","返虞嚴吉杖，復土掩空衣。","功業投三母，光靈極四妃。","唯應彤史在，不與露花晞。"]', '["永乐留虛位，长陵啓夕扉。","返虞嚴吉杖，复土掩空衣。","功業投三母，光靈極四妃。","唯應彤史在，不與露花晞。"]', '诗', 'shi', '', NULL, '光穆皇后挽歌三首 二 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62d40532-d242-4a6a-9d50-6b3579da4041', '光穆皇后挽歌三首 三', '光穆皇后挽歌三首 三', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["隱隱閶門路，煙雲曉更愁。","空瞻金輅出，非是濯龍游。","德感人倫正，風行內職修。","還隨偶物化，同此思軒丘。"]', '["隐隐閶门路，煙云晓更愁。","空瞻金輅出，非是濯龙游。","德感人倫正，风行內職修。","還隨偶物化，同此思軒丘。"]', '诗', 'shi', '', NULL, '光穆皇后挽歌三首 三 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edef0aad-d0b9-4a38-a9d6-bdeb2864d8e4', '嚴相公宅牡丹', '嚴相公宅牡丹', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["但是豪家重牡丹，爭如丞相閣前看。","鳳樓日暖開偏早，雞樹陰濃謝更難。","數朵已應迷國豔，一枝何幸上塵冠。","不知更許憑欄否，爛熳春光未肯殘。"]', '["但是豪家重牡丹，爭如丞相閣前看。","鳳楼日暖开偏早，雞樹陰濃謝更难。","數朵已應迷国豔，一枝何幸上塵冠。","不知更許憑欄否，爛熳春光未肯殘。"]', '诗', 'shi', '', NULL, '嚴相公宅牡丹 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86316174-9edc-45f1-9611-779d507942da', '侍宴賦得歸鴈', '侍宴賦得归鴈', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["夜靜羣動息，翩翩一鴈歸。","清音天際遠，寒影月中微。","何處雲同宿，長空雪共飛。","陽和常借便，免與素心違。"]', '["夜静羣动息，翩翩一鴈归。","清音天際远，寒影月中微。","何处云同宿，长空雪共飞。","陽和常借便，免與素心違。"]', '诗', 'shi', '', NULL, '侍宴賦得歸鴈 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd96a47b-4060-405d-8565-efab7d72de94', '又賦早春書事', '又賦早春书事', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["苑裏芳華早，皇家勝事多。","弓聲達春氣，弈思養天和。","煖酒紅爐火，浮舟綠水波。","雪晴農事起，擊壤聽賡歌。"]', '["苑裏芳华早，皇家勝事多。","弓声達春氣，弈思養天和。","煖酒紅爐火，浮舟綠水波。","雪晴農事起，擊壤听賡歌。"]', '诗', 'shi', '', NULL, '又賦早春書事 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1b8d31e-3825-4e36-aa15-e29dc9fc381b', '依韻和令公大王薔薇詩', '依韻和令公大王薔薇诗', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["綠樹成陰後，羣芳稍歇時。","誰將新濯錦，挂向最長枝。","卷箔香先入，憑欄影任移。","賞頻嫌酒渴，吟苦怕霜髭。","架迥籠雲幄，庭虛展繡帷。","有情縈舞袖，無力罥遊絲。","嫩蘂鶯偷采，柔條柳伴垂。","荀池波自照，梁苑客嘗窺。","玉李尋皆謝，金桃亦暗衰。","花中應獨貴，庭下故開遲。","委豔妝苔砌，分華借槿籬。","低昂勻灼爍，濃淡疊參差。","幸植王宮裏，仍逢宰府知。","芳心向誰許，醉態不能支。","芍藥天教避，玫瑰衆共嗤。","光明烘晝景，潤膩裛輕𩅰。","麗似期神女，珍如重衛姬。","君王偏屬詠，七子盡搜奇。"]', '["綠樹成陰後，羣芳稍歇时。","誰將新濯錦，挂向最长枝。","卷箔香先入，憑欄影任移。","賞頻嫌酒渴，吟苦怕霜髭。","架迥籠云幄，庭虛展繡帷。","有情縈舞袖，無力罥游絲。","嫩蘂鶯偷采，柔條柳伴垂。","荀池波自照，梁苑客嘗窺。","玉李尋皆謝，金桃亦暗衰。","花中應独貴，庭下故开遲。","委豔妝苔砌，分华借槿籬。","低昂勻灼爍，濃淡叠參差。","幸植王宮裏，仍逢宰府知。","芳心向誰許，醉態不能支。","芍藥天教避，玫瑰衆共嗤。","光明烘晝景，潤膩裛轻𩅰。","丽似期神女，珍如重衛姬。","君王偏屬詠，七子尽搜奇。"]', '诗', 'shi', '', NULL, '依韻和令公大王薔薇詩 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c7e2906-dd7f-40f8-9ac7-b5487984292e', '和門下殷侍郎新茶二十韻', '和门下殷侍郎新茶二十韻', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["暖吹入春園，新芽競粲然。","才教鷹觜拆，未放雪花妍。","荷杖青林下，攜筐旭景前。","孕靈資雨露，鍾秀自山川。","碾後香彌遠，烹來色更香。","名隨土地貴，味逐水泉遷。","力藉流黃暖，形模紫筍圓。","正當鑽柳火，遙想湧金泉。","任道時新物，須依古法煎。","輕甌浮綠乳，孤竈散餘煙。","甘薺非予匹，宮槐讓我先。","竹孤空冉冉，荷弱謾田田。","解渴消殘酒，清神感夜眠。","十漿何足饋，百榼盡堪捐。","采擷唯憂晚，營求不計錢。","任公因焙顯，陸氏有經傳。","愛甚真成癖，嘗多合得仙。","亭臺虛靜處，風月豔陽天。","自可臨泉石，何妨雜管弦。","東山似蒙頂，願得從諸賢。"]', '["暖吹入春园，新芽競粲然。","才教鷹觜拆，未放雪花妍。","荷杖青林下，携筐旭景前。","孕靈資雨露，鍾秀自山川。","碾後香彌远，烹来色更香。","名隨土地貴，味逐水泉遷。","力藉流黄暖，形模紫筍圓。","正當鑽柳火，遙想湧金泉。","任道时新物，須依古法煎。","轻甌浮綠乳，孤竈散餘煙。","甘薺非予匹，宮槐讓我先。","竹孤空冉冉，荷弱謾田田。","解渴消殘酒，清神感夜眠。","十漿何足饋，百榼尽堪捐。","采擷唯憂晚，營求不計錢。","任公因焙显，陸氏有經傳。","愛甚真成癖，嘗多合得仙。","亭台虛静处，风月豔陽天。","自可臨泉石，何妨杂管弦。","东山似蒙頂，願得從諸賢。"]', '诗', 'shi', '', NULL, '和門下殷侍郎新茶二十韻 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f02f360-38cf-497e-bc77-4e1650197f29', '春雪應制', '春雪應制', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["繁陰連曙景，瑞雪灑芳辰。","勢密猶疑臘，風和始覺春。","縈林開玉蘂，飄座裛香塵。","欲識宸心悅，雲謠慰兆人。"]', '["繁陰連曙景，瑞雪灑芳辰。","勢密猶疑臘，风和始覺春。","縈林开玉蘂，飄座裛香塵。","欲識宸心悅，云謠慰兆人。"]', '诗', 'shi', '', NULL, '春雪應制 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('139b8a53-0975-494d-ba27-7c52e75ba740', '進雪詩', '進雪诗', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["欲使新正識有年，故飄輕絮伴春還。","近看瓊樹籠銀闕，遠想瑤池帶玉關。","潤逐麳麰鋪綠野，暖隨杯酒上朱顏。","朝來花萼樓中宴，數曲賡歌雅頌間。"]', '["欲使新正識有年，故飄轻絮伴春還。","近看瓊樹籠銀闕，远想瑤池带玉关。","潤逐麳麰鋪綠野，暖隨杯酒上朱顏。","朝来花萼楼中宴，數曲賡歌雅頌间。"]', '诗', 'shi', '', NULL, '進雪詩 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c4afd70-dc6a-4a44-ab68-8fc93d6911fb', '自題山亭三首 一', '自題山亭三首 一', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["簪組非無累，園林未是歸。","世喧長不到，何必故山薇。"]', '["簪組非無累，园林未是归。","世喧长不到，何必故山薇。"]', '诗', 'shi', '', NULL, '自題山亭三首 一 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba134a53-5d3f-42d6-9e0e-1ef27f6edb76', '自題山亭三首 二', '自題山亭三首 二', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["小舫行乘月，高齋臥看山。","退公聊自足，爭敢望長閑。"]', '["小舫行乘月，高斋臥看山。","退公聊自足，爭敢望长闲。"]', '诗', 'shi', '', NULL, '自題山亭三首 二 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c05fbb51-61be-4637-8bcc-9b982c863dda', '自題山亭三首 三', '自題山亭三首 三', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["跂石仍臨水，披襟復挂冠。","機心忘未得，棊局與魚竿。"]', '["跂石仍臨水，披襟复挂冠。","機心忘未得，棊局與鱼竿。"]', '诗', 'shi', '', NULL, '自題山亭三首 三 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c753550f-debc-4e5d-9af4-ea5c8c99aa9c', '和陳表用員外求酒', '和陳表用員外求酒', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["暑天頻雨亦頻晴，簾外閑雲重復輕。","珍重一壺酬絕唱，向風遙想醉吟聲。"]', '["暑天頻雨亦頻晴，簾外闲云重复轻。","珍重一壺酬絕唱，向风遙想醉吟声。"]', '诗', 'shi', '', NULL, '和陳表用員外求酒 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a42fee4-161a-4046-83a4-b98f8df54b00', '奉和右省僕射西亭高臥作', '奉和右省僕射西亭高臥作', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["院靜蒼苔積，庭幽怪石欹。","蟬聲當檻急，虹影向簷垂。","晝漏猶憐永，叢蘭未覺衰。","疎篁巢翡翠，折葦覆鸕鷀。","對酒襟懷曠，圍棊旨趣遲。","景皆隨所尚，物各遂其宜。","道與時相會，才非世所羇。","賦詩貽座客，秋事爾何悲。"]', '["院静蒼苔積，庭幽怪石欹。","蟬声當檻急，虹影向簷垂。","晝漏猶怜永，叢蘭未覺衰。","疎篁巢翡翠，折葦覆鸕鷀。","对酒襟懷曠，圍棊旨趣遲。","景皆隨所尚，物各遂其宜。","道與时相會，才非世所羇。","賦诗貽座客，秋事爾何悲。"]', '诗', 'shi', '', NULL, '奉和右省僕射西亭高臥作 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf82ef7c-37ae-4d97-8300-108550244b2d', '憶新淦觴池寄孟賓于員外', '憶新淦觴池寄孟賓于員外', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["往年淦水駐行軒，引得清流似月圓。","自有谿光還碧甃，不勞人力遞金船。","潤滋苔蘚欺茵席，聲入杉松當管弦。","珍重詩人頻管領，莫教塵土咽潺潺。"]', '["往年淦水駐行軒，引得清流似月圓。","自有谿光還碧甃，不勞人力遞金船。","潤滋苔蘚欺茵席，声入杉松當管弦。","珍重诗人頻管領，莫教塵土咽潺潺。"]', '诗', 'shi', '', NULL, '憶新淦觴池寄孟賓于員外 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1837feb2-a799-41ef-a114-0bf26f63af79', '右省僕射後湖亭閑宴鉉以宿直先歸賦詩留獻', '右省僕射後湖亭闲宴鉉以宿直先归賦诗留獻', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["湖上一陽生，虛亭啓高宴。","楓林煙際出，白鳥波心見。","主人忘貴達，座客容疵賤。","獨慙殘照催，歸宿明光殿。"]', '["湖上一陽生，虛亭啓高宴。","楓林煙際出，白鸟波心见。","主人忘貴達，座客容疵賤。","独慙殘照催，归宿明光殿。"]', '诗', 'shi', '', NULL, '右省僕射後湖亭閑宴鉉以宿直先歸賦詩留獻 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9b13d28-ffca-4a64-97db-9ccf725d1972', '送孟賓于員外還新淦', '送孟賓于員外還新淦', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["暫來城闕不從容，却佩銀魚隱玉峰。","雙澗水邊欹醉石，九仙臺下聽風松。","題詩翠壁稱逋客，采藥春畦狎老農。","野鶴乘軒雲出岫，不知何日再相逢。"]', '["暫来城闕不從容，却佩銀鱼隐玉峰。","雙澗水邊欹醉石，九仙台下听风松。","題诗翠壁稱逋客，采藥春畦狎老農。","野鹤乘軒云出岫，不知何日再相逢。"]', '诗', 'shi', '', NULL, '送孟賓于員外還新淦 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('154091f0-621d-4f23-9e89-1556d972a9b0', '孟君別後相續寄書作此酬之', '孟君別後相續寄书作此酬之', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["多病怯煩暑，短才憂近職。","跂足北窗風，遙懷浩無極。","故人易成別，詩句空相憶。","尺素寄天涯，淦江秋水色。"]', '["多病怯煩暑，短才憂近職。","跂足北窗风，遙懷浩無極。","故人易成別，诗句空相憶。","尺素寄天涯，淦江秋水色。"]', '诗', 'shi', '', NULL, '孟君別後相續寄書作此酬之 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a8a5937-9527-4995-a740-ef9d611ba5e9', '納后夕侍宴', '納后夕侍宴', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["天上軒星正，雲間湛露垂。","禮容過渭水，宴喜勝瑤池。","彩霧籠花燭，升龍肅羽儀。","君臣歡樂日，文物盛明時。","簾捲銀河轉，香凝玉漏遲。","華封傾祝意，觴酒與聲詩。"]', '["天上軒星正，云间湛露垂。","禮容過渭水，宴喜勝瑤池。","彩霧籠花燭，升龙肅羽儀。","君臣歡乐日，文物盛明时。","簾捲銀河轉，香凝玉漏遲。","华封傾祝意，觴酒與声诗。"]', '诗', 'shi', '', NULL, '納后夕侍宴 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18cc1c05-3eff-4c21-895c-e09e1827ee81', '又三絕 一', '又三絕 一', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["時平物茂歲功成，重翟排雲到玉京。","四海未知春色至，今宵先入九重城。"]', '["时平物茂歲功成，重翟排云到玉京。","四海未知春色至，今宵先入九重城。"]', '诗', 'shi', '', NULL, '又三絕 一 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c67fbee-952d-4044-9722-0f92c0393634', '又三絕 二', '又三絕 二', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["銀燭金爐禁漏移，月輪初照萬年枝。","造舟已似文王事，卜世應同八百期。"]', '["銀燭金爐禁漏移，月輪初照万年枝。","造舟已似文王事，卜世應同八百期。"]', '诗', 'shi', '', NULL, '又三絕 二 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25b64840-c9db-4f79-bb31-d489da132f98', '又三絕 三', '又三絕 三', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["漢主承乾帝道光，天家花燭宴昭陽。","六衣盛禮如金屋，彩筆分題似柏梁。"]', '["漢主承乾帝道光，天家花燭宴昭陽。","六衣盛禮如金屋，彩笔分題似柏梁。"]', '诗', 'shi', '', NULL, '又三絕 三 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('921582a6-e4ba-4c72-9f59-e218c05eda5e', '北苑侍宴雜詠詩 竹', '北苑侍宴杂詠诗 竹', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["勁節生宮苑，虛心奉豫遊。","自然名價重，不羨渭川侯。"]', '["勁節生宮苑，虛心奉豫游。","自然名價重，不羨渭川侯。"]', '诗', 'shi', '', NULL, '北苑侍宴雜詠詩 竹 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58629206-d491-451b-a17d-9a9fbe11eb62', '北苑侍宴雜詠詩 松', '北苑侍宴杂詠诗 松', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["細韻風中遠，寒青雪後濃。","繁陰堪避雨，効用待東封。"]', '["細韻风中远，寒青雪後濃。","繁陰堪避雨，効用待东封。"]', '诗', 'shi', '', NULL, '北苑侍宴雜詠詩 松 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a11faf7a-a60f-42f9-91b4-d109d7d4816c', '北苑侍宴雜詠詩 水', '北苑侍宴杂詠诗 水', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["碧草垂低岸，東風起細波。","橫汾從遊宴，何謝到天河。"]', '["碧草垂低岸，东风起細波。","橫汾從游宴，何謝到天河。"]', '诗', 'shi', '', NULL, '北苑侍宴雜詠詩 水 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70a22830-405f-4181-8a42-d56f6d3420f1', '北苑侍宴雜詠詩 風', '北苑侍宴杂詠诗 风', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["昨朝纔解凍，今日又開花。","帝力無人識，誰知玩物華。"]', '["昨朝纔解凍，今日又开花。","帝力無人識，誰知玩物华。"]', '诗', 'shi', '', NULL, '北苑侍宴雜詠詩 風 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dc8dcfa-125d-49c5-aaed-4183d6a45f46', '北苑侍宴雜詠詩 菊', '北苑侍宴杂詠诗 菊', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["細麗披金彩，氛氳散遠馨。","汎杯頻奉賜，緣解制頹齡。"]', '["細丽披金彩，氛氳散远馨。","汎杯頻奉賜，緣解制頹齡。"]', '诗', 'shi', '', NULL, '北苑侍宴雜詠詩 菊 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf18512a-9624-4d72-b460-700834b9d5e0', '柳枝詞十首 一', '柳枝词十首 一', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["金馬辭臣賦小詩，梨園弟子唱新詞。","君恩還似東風意，先入靈和蜀柳枝。"]', '["金马辞臣賦小诗，梨园弟子唱新词。","君恩還似东风意，先入靈和蜀柳枝。"]', '诗', 'shi', '', NULL, '柳枝詞十首 一 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d231dbb4-bb96-44fa-b945-7e721226b964', '柳枝詞十首 二', '柳枝词十首 二', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["百草千花共待春，綠楊顏色最驚人。","天邊雨露年年在，上苑芳華歲歲新。"]', '["百草千花共待春，綠楊顏色最驚人。","天邊雨露年年在，上苑芳华歲歲新。"]', '诗', 'shi', '', NULL, '柳枝詞十首 二 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c2702f5-2433-4479-8e9e-4d81ca038169', '柳枝詞十首 三', '柳枝词十首 三', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["長愛龍池二月時，𣯶𣯶金線弄春姿。","假饒葉落枝空後，更有梨園笛裏吹。"]', '["长愛龙池二月时，𣯶𣯶金線弄春姿。","假饒葉落枝空後，更有梨园笛裏吹。"]', '诗', 'shi', '', NULL, '柳枝詞十首 三 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04b32110-3d0d-489a-8894-04b939b281b6', '柳枝詞十首 四', '柳枝词十首 四', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["綠水成文柳帶搖，東風初到不鳴條。","龍舟欲過偏留戀，萬縷輕絲拂御橋。"]', '["綠水成文柳带搖，东风初到不鳴條。","龙舟欲過偏留戀，万縷轻絲拂御橋。"]', '诗', 'shi', '', NULL, '柳枝詞十首 四 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5c1b256-5df0-4351-bbe6-8b16c719571a', '柳枝詞十首 五', '柳枝词十首 五', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["百尺長條婉麴塵，詩題不盡畫難真。","憑君折向人間種，還似君恩處處春。"]', '["百尺长條婉麴塵，诗題不尽畫难真。","憑君折向人间種，還似君恩处处春。"]', '诗', 'shi', '', NULL, '柳枝詞十首 五 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f402b09f-8792-465b-9283-346c2d97301a', '柳枝詞十首 六', '柳枝词十首 六', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["風暖雲開晚照明，翠條深映鳳皇城。","人間欲識靈和態，聽取新詞玉管聲。"]', '["风暖云开晚照明，翠條深映鳳皇城。","人间欲識靈和態，听取新词玉管声。"]', '诗', 'shi', '', NULL, '柳枝詞十首 六 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac704b30-e0c6-4ca0-9dac-6b378709a5d2', '柳枝詞十首 七', '柳枝词十首 七', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["醉折垂楊唱柳枝，金城三月走金羈。","年年爲愛新條好，不覺蒼華也似絲。"]', '["醉折垂楊唱柳枝，金城三月走金羈。","年年爲愛新條好，不覺蒼华也似絲。"]', '诗', 'shi', '', NULL, '柳枝詞十首 七 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbdcc25d-8f96-4698-bd5f-7c27b141a2ed', '柳枝詞十首 八', '柳枝词十首 八', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["新春花柳競芳姿，偏愛垂楊拂地枝。","天子徧教詞客賦，宮中要唱洞簫詞。"]', '["新春花柳競芳姿，偏愛垂楊拂地枝。","天子徧教词客賦，宮中要唱洞簫词。"]', '诗', 'shi', '', NULL, '柳枝詞十首 八 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('072151e9-bc50-4577-98b3-ac44208600aa', '柳枝詞十首 九', '柳枝词十首 九', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["凝碧池頭蘸翠漣，鳳皇樓畔簇晴煙。","新詞欲詠知難詠，說與雙成入管弦。"]', '["凝碧池头蘸翠漣，鳳皇楼畔簇晴煙。","新词欲詠知难詠，说與雙成入管弦。"]', '诗', 'shi', '', NULL, '柳枝詞十首 九 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d21708e8-11f8-4505-b346-896c8c940613', '柳枝詞十首 十', '柳枝词十首 十', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["侍從甘泉與未央，移舟偏要近垂楊。","櫻桃未綻梅花老，折得柔條百尺長。"]', '["侍從甘泉與未央，移舟偏要近垂楊。","櫻桃未綻梅花老，折得柔條百尺长。"]', '诗', 'shi', '', NULL, '柳枝詞十首 十 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5919bfe9-7f9c-4115-a56a-47efeba1154c', '奉和宮傅相公懷舊見寄四十韻', '奉和宮傅相公懷旧见寄四十韻', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["謝傅功成德望全，鸞臺初下正蕭然。","摶風乍息三千里，感舊重懷四十年。","西掖新官同賈馬，南朝興運似開天。","文辭職業分工拙，流輩班資讓後先。","每愧陋容勞刻畫，長慙頑石費彫鐫。","晨趨綸掖吟春永，夕會精廬待月圓。","立馬有時同草昭，聯鑣幾處共成篇。","閑歌柳葉翻新曲，醉詠桃花促綺筵。","少壯況逢時世好，經過寧慮歲華遷。","雲龍得路須騰躍，社櫟非材合棄捐。","再謁湘江猶是幸，兩還宣室竟何緣。","已知瑕玷勞磨瑩，又有官司重接連。","聽漏分宵趨建禮，從遊同召赴甘泉。","雲開閶闔分臺殿，風過華林度管弦。","行止不離宮仗影，衣裾嘗惹御爐煙。","師資稷契論中禮，依止山公典小銓。","多謝天波垂赤管，敢教晨景過華塼。","翾飛附驥方經遠，巨楫垂風遂濟川。","玉燭調時鈞軸正，台階平處德星懸。","巖廊禮絕威容肅，布素情深友好偏。","長擬營巢安大廈，忽驚操鉞領中權。","吳門日麗龍銜節，京口沙晴鷁畫船。","蓋代名高方赫赫，戀恩心切更乾乾。","袁安辭氣忠仍懇，吳漢精誠直且專。","却許丘明師紀傳，更容疎廣奉周旋。","朱門自得施行馬，厚祿何妨食萬錢。","密疏尚應勞獻替，清談唯見論空玄。","東山妓樂供閑步，北牖風涼足晏眠。","玄武湖邊林隱見，五城橋下櫂洄沿。","曾移苑樹開紅藥，新鑿家池種白蓮。","不遣前騶妨野逸，別尋逋客互招延。","棊枰寂靜陳虛閣，詩筆沉吟劈彩牋。","往事偶來春夢裏，閑愁因動落花前。","青雲舊侶嗟誰在，白首親情倍見憐。","盡日凝思殊悵望，一章追敘信精研。","韶顏莫與年爭競，世慮須憑道節宣。","幸喜書生爲將相，定由陰德致神仙。","羊公剩有登臨興，尚子都無嫁娶牽。","退象天山鎮浮競，起爲霖雨潤原田。","從容自保君臣契，何必扁舟始是賢。"]', '["謝傅功成德望全，鸾台初下正蕭然。","摶风乍息三千里，感旧重懷四十年。","西掖新官同賈马，南朝兴運似开天。","文辞職業分工拙，流輩班資讓後先。","每愧陋容勞刻畫，长慙頑石費彫鐫。","晨趨綸掖吟春永，夕會精廬待月圓。","立马有时同草昭，聯鑣幾处共成篇。","闲歌柳葉翻新曲，醉詠桃花促綺筵。","少壯況逢时世好，經過寧慮歲华遷。","云龙得路須腾躍，社櫟非材合棄捐。","再謁湘江猶是幸，兩還宣室竟何緣。","已知瑕玷勞磨瑩，又有官司重接連。","听漏分宵趨建禮，從游同召赴甘泉。","云开閶闔分台殿，风過华林度管弦。","行止不離宮仗影，衣裾嘗惹御爐煙。","師資稷契論中禮，依止山公典小銓。","多謝天波垂赤管，敢教晨景過华塼。","翾飞附驥方經远，巨楫垂风遂濟川。","玉燭調时鈞軸正，台階平处德星懸。","巖廊禮絕威容肅，布素情深友好偏。","长擬營巢安大廈，忽驚操鉞領中權。","吳门日丽龙銜節，京口沙晴鷁畫船。","蓋代名高方赫赫，戀恩心切更乾乾。","袁安辞氣忠仍懇，吳漢精誠直且專。","却許丘明師紀傳，更容疎廣奉周旋。","朱门自得施行马，厚祿何妨食万錢。","密疏尚應勞獻替，清談唯见論空玄。","东山妓乐供闲步，北牖风涼足晏眠。","玄武湖邊林隐见，五城橋下櫂洄沿。","曾移苑樹开紅藥，新鑿家池種白蓮。","不遣前騶妨野逸，別尋逋客互招延。","棊枰寂静陳虛閣，诗笔沉吟劈彩牋。","往事偶来春梦裏，闲愁因动落花前。","青云旧侶嗟誰在，白首親情倍见怜。","尽日凝思殊悵望，一章追敘信精研。","韶顏莫與年爭競，世慮須憑道節宣。","幸喜书生爲將相，定由陰德致神仙。","羊公剩有登臨兴，尚子都無嫁娶牽。","退象天山鎮浮競，起爲霖雨潤原田。","從容自保君臣契，何必扁舟始是賢。"]', '诗', 'shi', '', NULL, '奉和宮傅相公懷舊見寄四十韻 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('096e5a2b-25a4-40f5-8c4c-c59de8d5a571', '右省僕射相公垂覽和詩復貽長句輙次來韻', '右省僕射相公垂覽和诗复貽长句輙次来韻', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["西院春歸道思深，披衣閑聽暝猨吟。","鋪陳政事留黃閣，偃息神機在素琴。","玉柄暫時疎末座，瑤華頻復惠清音。","開晴便作東山約，共賞煙霞放曠心。"]', '["西院春归道思深，披衣闲听暝猨吟。","鋪陳政事留黄閣，偃息神機在素琴。","玉柄暫时疎末座，瑤华頻复惠清音。","开晴便作东山約，共賞煙霞放曠心。"]', '诗', 'shi', '', NULL, '右省僕射相公垂覽和詩復貽長句輙次來韻 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ee2fbbd-30af-42fa-b169-a15f55098b49', '九日落星山登高', '九日落星山登高', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["秋暮天高稻穟成，落星山上會諸賓。","黃花汎酒依流俗，白髮滿頭思古人。","巖影晚看雲出岫，湖光遙見客垂綸。","風煙不改年長度，終待林泉老此身。"]', '["秋暮天高稻穟成，落星山上會諸賓。","黄花汎酒依流俗，白髮满头思古人。","巖影晚看云出岫，湖光遙见客垂綸。","风煙不改年长度，終待林泉老此身。"]', '诗', 'shi', '', NULL, '九日落星山登高 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a817b037-7723-498e-aeea-5a47dccab5e8', '十日和張少監', '十日和張少監', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["重陽高會古平臺，吟徧秋光始下來。","黃菊後期香未減，新詩捧得眼還開。","每因佳節知身老，却憶前歡似夢迴。","且喜清時屢行樂，是非名利盡悠哉。"]', '["重陽高會古平台，吟徧秋光始下来。","黄菊後期香未減，新诗捧得眼還开。","每因佳節知身老，却憶前歡似梦迴。","且喜清时屢行乐，是非名利尽悠哉。"]', '诗', 'shi', '', NULL, '十日和張少監 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bebcfa42-b2e1-45e1-97c4-1794e8ec2709', '御筵送鄧王', '御筵送鄧王', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["禁裏秋光似水清，林煙池影共離情。","暫移黃閣只三載，却望紫垣都數程。","滿座清風天子送，隨車甘雨郡人迎。","綺霞閣上詩題在，從此還應有頌聲。"]', '["禁裏秋光似水清，林煙池影共離情。","暫移黄閣只三載，却望紫垣都數程。","满座清风天子送，隨车甘雨郡人迎。","綺霞閣上诗題在，從此還應有頌声。"]', '诗', 'shi', '', NULL, '御筵送鄧王 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1675125f-a6e8-40d1-976a-f26cadf15f62', '和張少監晚菊', '和張少監晚菊', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["憶共庭蘭倚砌裁，柔條輕吹獨依隈。","自知佳節終堪賞，爲惜流光未忍開。","采擷也須盈掌握，馨香還解滿尊罍。","今朝旬假猶無事，更好登臨汎一盃。"]', '["憶共庭蘭倚砌裁，柔條轻吹独依隈。","自知佳節終堪賞，爲惜流光未忍开。","采擷也須盈掌握，馨香還解满尊罍。","今朝旬假猶無事，更好登臨汎一盃。"]', '诗', 'shi', '', NULL, '和張少監晚菊 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e50d9d9-2809-4650-ab6e-71a253a60beb', '送馮侍郎', '送馮侍郎', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["聞君竹馬戲毘陵，誰道觀風自六卿。","今日聲明光舊物，共看旌斾擁書生。","斬蛟橋下谿煙碧，射虎亭邊草路清。","應念筵中倍離恨，老來偏重十年兄。"]', '["闻君竹马戲毘陵，誰道观风自六卿。","今日声明光旧物，共看旌斾擁书生。","斬蛟橋下谿煙碧，射虎亭邊草路清。","應念筵中倍離恨，老来偏重十年兄。"]', '诗', 'shi', '', NULL, '送馮侍郎 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf2140b9-df12-4522-adef-86708ec89f93', '又絕句寄題毘陵驛', '又絕句寄題毘陵驛', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["曾持使節駐毘陵，長與州人有舊情。","爲向驛橋風月道，舍人髭鬢白千莖。"]', '["曾持使節駐毘陵，长與州人有旧情。","爲向驛橋风月道，舍人髭鬢白千莖。"]', '诗', 'shi', '', NULL, '又絕句寄題毘陵驛 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d944d802-48d3-4c6f-b997-1f198d250c51', '陳侍郎宅觀花燭', '陳侍郎宅观花燭', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["今夜銀河萬里秋，人言織女嫁牽牛。","佩聲寥亮和金奏，燭影熒煌映玉鉤。","座客亦從天子賜，更籌須爲主人留。","世間盛事君知否，朝下鸞臺夕鳳樓。"]', '["今夜銀河万里秋，人言织女嫁牽牛。","佩声寥亮和金奏，燭影熒煌映玉鉤。","座客亦從天子賜，更籌須爲主人留。","世间盛事君知否，朝下鸾台夕鳳楼。"]', '诗', 'shi', '', NULL, '陳侍郎宅觀花燭 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d48d8a8d-54a1-4ef1-bc99-fe161cbbcf74', '送蕭尚書致仕歸廬陵', '送蕭尚书致仕归廬陵', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["江海分飛二十春，重論前事不堪聞。","主憂臣辱誰非我，曲突徙薪唯有君。","金紫滿身皆外物，雪霜垂領便離羣。","鶴歸華表望不盡，玉笥山頭多白雲。"]', '["江海分飞二十春，重論前事不堪闻。","主憂臣辱誰非我，曲突徙薪唯有君。","金紫满身皆外物，雪霜垂領便離羣。","鹤归华表望不尽，玉笥山头多白云。"]', '诗', 'shi', '', NULL, '送蕭尚書致仕歸廬陵 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec431828-346d-41f1-a957-60e6ed4cec62', '賦得秋江晚照', '賦得秋江晚照', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["落日照平流，晴空萬里秋。","輕明動楓葉，點的亂沙鷗。","罾網魚梁靜，籉簦稻穗收。","不教行樂倦，冉冉下城樓。"]', '["落日照平流，晴空万里秋。","轻明动楓葉，点的亂沙鷗。","罾網鱼梁静，籉簦稻穗收。","不教行乐倦，冉冉下城楼。"]', '诗', 'shi', '', NULL, '賦得秋江晚照 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3448ac9a-c1fd-47cf-a54d-cda9525c084e', '奉和子龍大監與舍弟贈答之什', '奉和子龙大監與舍弟贈答之什', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["石渠東觀兩優賢，明主知臣豈偶然。","鴛鷺分行皆接武，金蘭同好共忘年。","懷恩未遂林泉約，竊位空慙組綬懸。","多少深情知不盡，好音相慰強成篇。"]', '["石渠东观兩優賢，明主知臣豈偶然。","鴛鷺分行皆接武，金蘭同好共忘年。","懷恩未遂林泉約，竊位空慙組綬懸。","多少深情知不尽，好音相慰強成篇。"]', '诗', 'shi', '', NULL, '奉和子龍大監與舍弟贈答之什 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bb18d8e-45e3-4b05-8c2f-6c13deec02b9', '史館庭梅見其毫末歷載三十今已半枯嘗僚諸公唯相公與鉉在耳覩物興感率成短篇謹書獻上伏惟垂覽', '史館庭梅见其毫末歷載三十今已半枯嘗僚諸公唯相公與鉉在耳覩物兴感率成短篇謹书獻上伏惟垂覽', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["東觀婆娑樹，曾憐甲坼時。","繁英共攀折，芳歲幾推移。","往事皆陳迹，清香亦暗衰。","相看宜自喜，雙鬢合垂絲。"]', '["东观婆娑樹，曾怜甲坼时。","繁英共攀折，芳歲幾推移。","往事皆陳迹，清香亦暗衰。","相看宜自喜，雙鬢合垂絲。"]', '诗', 'shi', '', NULL, '史館庭梅見其毫末歷載三十今已半枯嘗僚諸公唯相公與鉉在耳覩物興感率成短篇謹書獻上伏惟垂覽 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a3e574c-5d1b-4f89-8a38-2f5f91583d01', '太傅相公深感庭梅再成絕唱曲垂借示倍認知憐謹用舊韻攀和', '太傅相公深感庭梅再成絕唱曲垂借示倍認知怜謹用旧韻攀和', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["禁省繁華地，含芳自一時。","雪英開復落，紅藥植還移。","靜想分今昔，頻吟歎盛衰。","多情共如此，爭免鬢成絲。"]', '["禁省繁华地，含芳自一时。","雪英开复落，紅藥植還移。","静想分今昔，頻吟歎盛衰。","多情共如此，爭免鬢成絲。"]', '诗', 'shi', '', NULL, '太傅相公深感庭梅再成絕唱曲垂借示倍認知憐謹用舊韻攀和 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6fb39cd-311b-4076-910f-fdaeae3cef03', '太傅相公以庭梅二篇許舍弟同賦再迂藻思曲有虛稱謹依韻奉和庶申感謝', '太傅相公以庭梅二篇許舍弟同賦再迂藻思曲有虛稱謹依韻奉和庶申感謝', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["舊眷終無替，流光自足悲。","攀條感花萼，和曲許塤篪。","前會成春夢，和人更己知。","緣情聊借喻，爭取道言詩。"]', '["旧眷終無替，流光自足悲。","攀條感花萼，和曲許塤篪。","前會成春梦，和人更己知。","緣情聊借喻，爭取道言诗。"]', '诗', 'shi', '', NULL, '太傅相公以庭梅二篇許舍弟同賦再迂藻思曲有虛稱謹依韻奉和庶申感謝 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ae8e60e-ccc7-4ec4-ad49-17f265adc2d3', '和鍾大監汎舟同游見示', '和鍾大監汎舟同游见示', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["潮溝橫趣北山阿，一月三游未是多。","老去交親難暫捨，閑中滋味更無過。","谿橋樹映行人渡，村徑風飄牧豎歌。","孤櫂亂流偏有興，滿川晴日弄微波。"]', '["潮溝橫趣北山阿，一月三游未是多。","老去交親难暫捨，闲中滋味更無過。","谿橋樹映行人渡，村徑风飄牧豎歌。","孤櫂亂流偏有兴，满川晴日弄微波。"]', '诗', 'shi', '', NULL, '和鍾大監汎舟同游見示 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3426813e-83aa-4d25-8851-785c456de00c', '又和游光睦院', '又和游光睦院', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["寺門山水際，清淺照孱顏。","客櫂晚維岸，僧房猶掩關。","日華穿竹靜，雲影過堦閑。","箕踞一長嘯，忘懷物我間。"]', '["寺门山水際，清淺照孱顏。","客櫂晚維岸，僧房猶掩关。","日华穿竹静，云影過堦闲。","箕踞一长嘯，忘懷物我间。"]', '诗', 'shi', '', NULL, '又和游光睦院 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5a84d32-ef18-4ac9-8270-457e2b18d47f', '和張少監舟中望蔣山', '和張少監舟中望蔣山', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["谿路向還背，前山高復重。","紛披紅葉樹，間斷白雲峰。","盡日慵移櫂，何年醉倚松。","自知閑未得，不敢笑周顒。"]', '["谿路向還背，前山高复重。","紛披紅葉樹，间斷白云峰。","尽日慵移櫂，何年醉倚松。","自知闲未得，不敢笑周顒。"]', '诗', 'shi', '', NULL, '和張少監舟中望蔣山 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1cbc223-a4fb-4faf-9774-9f4a15def66a', '茱萸詩', '茱萸诗', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["萬物慶西成，茱萸獨擅名。","芳排紅結小，香透夾衣輕。","宿露霑猶重，朝陽照更明。","長和菊花酒，高宴奉西清。"]', '["万物慶西成，茱萸独擅名。","芳排紅結小，香透夾衣轻。","宿露霑猶重，朝陽照更明。","长和菊花酒，高宴奉西清。"]', '诗', 'shi', '', NULL, '茱萸詩 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58463373-cbd8-476b-a00e-68dc942965fe', '奉和御製茱萸', '奉和御製茱萸', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["臺畔西風御果新，芳香精彩麗蕭辰。","柔條細葉妝治好，紫蔕紅芳點綴勻。","幾朵得陪天上宴，千株長作洞中春。","今朝聖藻偏流詠，黃菊無由更敢鄰。"]', '["台畔西风御果新，芳香精彩丽蕭辰。","柔條細葉妝治好，紫蔕紅芳点綴勻。","幾朵得陪天上宴，千株长作洞中春。","今朝聖藻偏流詠，黄菊無由更敢鄰。"]', '诗', 'shi', '', NULL, '奉和御製茱萸 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('438d4a8b-b0e9-45f0-905a-5c4b8a0df19d', '蒙恩賜酒旨令醉進詩以謝', '蒙恩賜酒旨令醉進诗以謝', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["明光殿裏夜迢迢，多病逢秋自寂寥。","蠟炬乍傳丹鳳詔，御題初認白雲謠。","今宵幸識衢尊味，明日知停入閤朝。","爲感君恩判一醉，不煩辛苦解金貂。"]', '["明光殿裏夜迢迢，多病逢秋自寂寥。","蠟炬乍傳丹鳳詔，御題初認白云謠。","今宵幸識衢尊味，明日知停入閤朝。","爲感君恩判一醉，不煩辛苦解金貂。"]', '诗', 'shi', '', NULL, '蒙恩賜酒旨令醉進詩以謝 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b407b9d8-6d1e-4a43-ac33-a9c6819a2372', '秋日汎舟賦蘋花', '秋日汎舟賦蘋花', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["素豔擁行舟，清香覆碧流。","遠煙分的的，輕浪汎悠悠。","雨歇平湖滿，風涼運瀆秋。","今朝流詠處，即是白蘋洲。"]', '["素豔擁行舟，清香覆碧流。","远煙分的的，轻浪汎悠悠。","雨歇平湖满，风涼運瀆秋。","今朝流詠处，即是白蘋洲。"]', '诗', 'shi', '', NULL, '秋日汎舟賦蘋花 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31bd2318-729d-45dc-b979-84f0e462deb6', '題梁王舊園', '題梁王旧园', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["梁王舊館枕潮溝，共引垂藤繫小舟。","樹倚荒臺風淅淅，草埋欹石[雨]修修。","門前不見鄒枚醉，池上時聞鴈鶩愁。","節士逢秋多感激，不須頻向此中游。"]', '["梁王旧館枕潮溝，共引垂藤繫小舟。","樹倚荒台风淅淅，草埋欹石[雨]修修。","门前不见鄒枚醉，池上时闻鴈鶩愁。","節士逢秋多感激，不須頻向此中游。"]', '诗', 'shi', '', NULL, '題梁王舊園 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('257162d3-d669-44a7-a8dd-66f54bca50b4', '奉酬度支陳員外', '奉酬度支陳員外', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["古來賢達士，馳鶩唯羣書。","非禮誓弗習，違道無與居。","儒家若迂闊，遂將世情疎。","吾友嗣世德，古風藹有餘。","幸遇漢文皇，握蘭佩金魚。","俯視長沙賦，悽悽將焉如。"]', '["古来賢達士，驰鶩唯羣书。","非禮誓弗習，違道無與居。","儒家若迂闊，遂將世情疎。","吾友嗣世德，古风藹有餘。","幸遇漢文皇，握蘭佩金鱼。","俯視长沙賦，悽悽將焉如。"]', '诗', 'shi', '', NULL, '奉酬度支陳員外 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a1b7b4e-27e9-44b8-af51-491d3f6f40c5', '明道人歸西林求題院額作此送之', '明道人归西林求題院額作此送之', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["昔從岐陽狩，簪纓滿翠微。","十年勞我夢，今日送師歸。","曳尾龜應樂，乘軒鶴謾肥。","含情題小篆，將去挂巖扉。"]', '["昔從岐陽狩，簪纓满翠微。","十年勞我梦，今日送師归。","曳尾龟應乐，乘軒鹤謾肥。","含情題小篆，將去挂巖扉。"]', '诗', 'shi', '', NULL, '明道人歸西林求題院額作此送之 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ba95940-f556-48af-8cdc-1a12bef149cf', '送宣州丘判官', '送宣州丘判官', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["憲署游從阻，平臺道路賒。","喜君馳後乘，於此會仙槎。","緩酌遲飛蓋，微吟望綺霞。","相迎在春渚，暫別莫咨嗟。"]', '["憲署游從阻，平台道路賒。","喜君驰後乘，於此會仙槎。","緩酌遲飞蓋，微吟望綺霞。","相迎在春渚，暫別莫咨嗟。"]', '诗', 'shi', '', NULL, '送宣州丘判官 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b96f294d-3da1-463d-80b6-9ca3734f9b79', '北使還襄邑道中作', '北使還襄邑道中作', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["九月三十日，獨行梁宋道。","河流激似飛，林葉翻如掃。","程遙苦晝短，野逈知寒早。","還家亦不閑，要且還家了。"]', '["九月三十日，独行梁宋道。","河流激似飞，林葉翻如掃。","程遙苦晝短，野逈知寒早。","還家亦不闲，要且還家了。"]', '诗', 'shi', '', NULL, '北使還襄邑道中作 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51d1077c-926f-4def-ab5e-1dc1c7029e09', '禁中新月', '禁中新月', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["今夕拜新月，沈沈禁署中。","玉繩疎間彩，金掌靜無風。","節換知身老，時平見歲功。","吟看北墀暝，蘭燼墜微紅。"]', '["今夕拜新月，沈沈禁署中。","玉繩疎间彩，金掌静無风。","節換知身老，时平见歲功。","吟看北墀暝，蘭燼墜微紅。"]', '诗', 'shi', '', NULL, '禁中新月 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d93af8ae-752e-432c-b230-479984b15e73', '觀吉王從謙花燭', '观吉王從謙花燭', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["王門嘉禮萬人觀，況是新承置醴歡。","花燭喧闐丞相府，星辰搖動遠遊冠。","歌聲暫闋聞宮漏，雲影初開見露盤。","帝里佳期頻賦頌，長留故事在金鑾。"]', '["王门嘉禮万人观，況是新承置醴歡。","花燭喧闐丞相府，星辰搖动远游冠。","歌声暫闋闻宮漏，云影初开见露盤。","帝里佳期頻賦頌，长留故事在金鑾。"]', '诗', 'shi', '', NULL, '觀吉王從謙花燭 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb68fe81-b62c-4f80-8adc-f3e30cd071cf', '棊賭賦詩輸劉起居', '棊賭賦诗輸劉起居', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["刻燭知無取，爭先素未精。","本圖忘物我，何必計輸贏。","賭墅終規利，焚囊亦近名。","不如相視笑，高詠兩三聲。"]', '["刻燭知無取，爭先素未精。","本圖忘物我，何必計輸贏。","賭墅終規利，焚囊亦近名。","不如相視笑，高詠兩三声。"]', '诗', 'shi', '', NULL, '棊賭賦詩輸劉起居 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73322167-4096-4faa-b3de-7ba30a9f0dc7', '春盡日游後湖贈劉起居', '春尽日游後湖贈劉起居', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["今朝湖上送春歸，萬頃澄波照白髭。"]', '["今朝湖上送春归，万頃澄波照白髭。"]', '诗', 'shi', '', NULL, '春盡日游後湖贈劉起居 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bed660c3-f848-441b-8d9b-00388a16360e', '送察院李侍御使廬陵因寄孟員外', '送察院李侍御使廬陵因寄孟員外', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["繡衣乘驛急如星，山水何妨寄野情。","肯向九仙臺下歇，閑聽孟叟醉吟聲。"]', '["繡衣乘驛急如星，山水何妨寄野情。","肯向九仙台下歇，闲听孟叟醉吟声。"]', '诗', 'shi', '', NULL, '送察院李侍御使廬陵因寄孟員外 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd54c32e-5332-44c9-9bb0-b7ef21ca609b', '後湖訪古各賦一題得西邸', '後湖訪古各賦一題得西邸', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["南朝藩閫地，八友舊招尋。","事往山光在，春晴草色深。","曲池魚自樂，叢桂鳥頻吟。","今日中興運，猶懷翰墨林。"]', '["南朝藩閫地，八友旧招尋。","事往山光在，春晴草色深。","曲池鱼自乐，叢桂鸟頻吟。","今日中兴運，猶懷翰墨林。"]', '诗', 'shi', '', NULL, '後湖訪古各賦一題得西邸 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('708eb6d6-bb17-43b0-9f6a-ff632c968fcf', '送德邁道人之豫章', '送德邁道人之豫章', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["禪靈橋畔落殘花，橋上離情對日斜。","顧我乘軒慙組綬，羨師飛錫指煙霞。","樓中西嶺真君宅，門外南州處士家。","莫道空談便無事，碧雲詩思更無涯。"]', '["禪靈橋畔落殘花，橋上離情对日斜。","顧我乘軒慙組綬，羨師飞錫指煙霞。","楼中西嶺真君宅，门外南州处士家。","莫道空談便無事，碧云诗思更無涯。"]', '诗', 'shi', '', NULL, '送德邁道人之豫章 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85d88083-5e91-4ea9-b2d6-747242b8046b', '送陳祕監歸泉州', '送陳祕監归泉州', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["風滿潮溝木葉飛，水邊行客駐驂騑。","三朝恩澤馮唐老，萬里鄉關賀監歸。","世路窮通前事遠，半生談笑此心違。","離歌不識高堂慶，特地令人淚滿衣。"]', '["风满潮溝木葉飞，水邊行客駐驂騑。","三朝恩澤馮唐老，万里乡关賀監归。","世路窮通前事远，半生談笑此心違。","離歌不識高堂慶，特地令人泪满衣。"]', '诗', 'shi', '', NULL, '送陳祕監歸泉州 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0814f079-0743-44c5-ab9e-632d711f4787', '又聽霓裳羽衣曲送陳君', '又听霓裳羽衣曲送陳君', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["清商一曲遠人行，桃葉津頭月正明。","此是開元太平曲，莫教偏作別離聲。"]', '["清商一曲远人行，桃葉津头月正明。","此是开元太平曲，莫教偏作別離声。"]', '诗', 'shi', '', NULL, '又聽霓裳羽衣曲送陳君 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dbdcd37-8aea-473d-9a10-7d16a666babf', '又題白鷺洲江鷗送陳君', '又題白鷺洲江鷗送陳君', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["白鷺洲邊江路斜，輕鷗按翼滿平沙。","吾徒來送遠行客，停舟爲爾長歎息。","酒旗魚艇兩無猜，月影蘆花鎮相得。","離筵一曲怨復清，滿座銷魂鳥不驚。","人生不及水禽樂，安用虛名上麟閣。","同心攜手今如此，金鼎丹砂何寂寞。","天涯後會眇難期，從此又應添白髭。","願君不忘分飛處，長保翩翩潔白姿。"]', '["白鷺洲邊江路斜，轻鷗按翼满平沙。","吾徒来送远行客，停舟爲爾长歎息。","酒旗鱼艇兩無猜，月影蘆花鎮相得。","離筵一曲怨复清，满座銷魂鸟不驚。","人生不及水禽乐，安用虛名上麟閣。","同心携手今如此，金鼎丹砂何寂寞。","天涯後會眇难期，從此又應添白髭。","願君不忘分飞处，长保翩翩潔白姿。"]', '诗', 'shi', '', NULL, '又題白鷺洲江鷗送陳君 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed5a4082-d507-4d8a-a9a5-d6679d8d766c', '哭刑部侍郎喬公詩', '哭刑部侍郎喬公诗', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["舉世重文雅，夫君更質真。","曾嗟混雞鶴，終日異淄磷。","詞賦離騷客，封章諫諍臣。","襟懷道家侶，標格古時人。","逸老誠云福，遺形未免貧。","求文空得草，埋玉遂爲塵。","靜想忘年契，冥思按武晨。","連宵洽杯酒，分日掌絲綸。","蠹簡書陳事，遺孤託世親。","前賢同此歎，非我獨霑巾。"]', '["舉世重文雅，夫君更質真。","曾嗟混雞鹤，終日異淄磷。","词賦離騷客，封章諫諍臣。","襟懷道家侶，標格古时人。","逸老誠云福，遺形未免貧。","求文空得草，埋玉遂爲塵。","静想忘年契，冥思按武晨。","連宵洽杯酒，分日掌絲綸。","蠹簡书陳事，遺孤託世親。","前賢同此歎，非我独霑巾。"]', '诗', 'shi', '', NULL, '哭刑部侍郎喬公詩 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4eff3617-229a-4315-94c4-980093a0d504', '送程德琳郎中學士', '送程德琳郎中学士', '036ab585-fef7-4b7b-af4c-0ef99830865a', '唐', '["瓜步妖氛滅，崑岡草樹青。","終朝空望極，今日送君行。","報政秋雲靜，微吟曉月生。","樓中長可見，特用滅離情。"]', '["瓜步妖氛滅，崑岡草樹青。","終朝空望極，今日送君行。","報政秋云静，微吟晓月生。","楼中长可见，特用滅離情。"]', '诗', 'shi', '', NULL, '送程德琳郎中學士 徐鍇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9dbd321-84eb-4dc1-baf4-1daa7a4321fe', '太傅相公以東觀庭梅西垣舊植昔陪盛賞今獨家兄唱和之餘俾令攀和輙依本韻伏愧斐然', '太傅相公以东观庭梅西垣旧植昔陪盛賞今独家兄唱和之餘俾令攀和輙依本韻伏愧斐然', '036ab585-fef7-4b7b-af4c-0ef99830865a', '唐', '["靜對含章樹，閑思共有時。","香隨荀令在，根異武昌移。","物性雖搖落，人心豈變衰。","唱酬勝笛曲，來往韻朱[絲]。"]', '["静对含章樹，闲思共有时。","香隨荀令在，根異武昌移。","物性雖搖落，人心豈变衰。","唱酬勝笛曲，来往韻朱[絲]。"]', '诗', 'shi', '', NULL, '太傅相公以東觀庭梅西垣舊植昔陪盛賞今獨家兄唱和之餘俾令攀和輙依本韻伏愧斐然 徐鍇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66ae3878-36e2-44f7-ae6f-d24d5976a7ac', '太傅相公與家兄梅花詶唱許綴末篇再賜新詩俯光拙句謹奉清韻用感鈞私伏惟采覽', '太傅相公與家兄梅花詶唱許綴末篇再賜新诗俯光拙句謹奉清韻用感鈞私伏惟采覽', '036ab585-fef7-4b7b-af4c-0ef99830865a', '唐', '["重歎梅花落，非關塞笛悲。","論文叨接萼，末曲愧吹篪。","枝逐清風動，香因白雪知。","陶鈞敷左悌，更賦邵公詩。"]', '["重歎梅花落，非关塞笛悲。","論文叨接萼，末曲愧吹篪。","枝逐清风动，香因白雪知。","陶鈞敷左悌，更賦邵公诗。"]', '诗', 'shi', '', NULL, '太傅相公與家兄梅花詶唱許綴末篇再賜新詩俯光拙句謹奉清韻用感鈞私伏惟采覽 徐鍇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c342681c-c0e4-4c44-90f7-d247d228fd0e', '同家兄哭喬侍郎', '同家兄哭喬侍郎', '036ab585-fef7-4b7b-af4c-0ef99830865a', '唐', '["諸公長者鄭當時，事事無心性坦夷。","但是登臨皆有作，未嘗相見不伸眉。","生前適意無過酒，身後遺言只要詩。","三日笑談成理命，一篇投弔尚應知。"]', '["諸公长者鄭當时，事事無心性坦夷。","但是登臨皆有作，未嘗相见不伸眉。","生前適意無過酒，身後遺言只要诗。","三日笑談成理命，一篇投弔尚應知。"]', '诗', 'shi', '', NULL, '同家兄哭喬侍郎 徐鍇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62a59127-ec42-4ead-a8dc-9a7eaf5b6e12', '秋詞', '秋词', '036ab585-fef7-4b7b-af4c-0ef99830865a', '唐', '["井梧紛墮砌，寒雁遠橫空。","雨久[莓]苔紫，霜濃薜荔紅。"]', '["井梧紛墮砌，寒雁远橫空。","雨久[莓]苔紫，霜濃薜荔紅。"]', '诗', 'shi', '', NULL, '秋詞 徐鍇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('749502c2-a0f7-4be8-a7e9-8a19f30596b2', '和徐鼎臣見寄', '和徐鼎臣见寄', '98ee86fb-7359-4e63-9022-58d561e9e7b4', '唐', '["平生中表最情親，浮世那堪聚散頻。","謝朓去吟歸省閣，劉楨猶自臥漳濱。","舊游半似前生事，要路多逢後進人。","且喜新吟報強健，明年相望杏園春。"]', '["平生中表最情親，浮世那堪聚散頻。","謝朓去吟归省閣，劉楨猶自臥漳濱。","旧游半似前生事，要路多逢後進人。","且喜新吟報強健，明年相望杏园春。"]', '诗', 'shi', '', NULL, '和徐鼎臣見寄 包頴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9afc707f-0640-4b4a-b740-769420d099c2', '貽耀州將', '貽耀州將', '6184a4c7-a8b0-4561-be83-c1c147c2ca82', '唐', '["翩翩歸盡塞垣鴻，隱隱驚開蟄戶蟲。","渭北離愁春色裏，江南家事戰塵中。","還同逐客紉蘭佩，誰聽縲囚奏土風。","多謝賢侯振吾道，免令搔首泣途窮。"]', '["翩翩归尽塞垣鴻，隐隐驚开蟄戶蟲。","渭北離愁春色裏，江南家事戰塵中。","還同逐客紉蘭佩，誰听縲囚奏土风。","多謝賢侯振吾道，免令搔首泣途窮。"]', '诗', 'shi', '', NULL, '貽耀州將 鍾謨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3972438-28fb-4d53-ba32-319a79fa0319', '獻周世宗', '獻周世宗', '6184a4c7-a8b0-4561-be83-c1c147c2ca82', '唐', '["三年耀武羣雄服，一日回鑾萬國春。","南北通歡永無事，謝恩歸去老陪臣。"]', '["三年耀武羣雄服，一日回鑾万国春。","南北通歡永無事，謝恩归去老陪臣。"]', '诗', 'shi', '', NULL, '獻周世宗 鍾謨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8db7eb16-3521-47c6-b489-d6844aa1c81a', '代京妓越賓荅徐鉉', '代京妓越賓荅徐鉉', '6184a4c7-a8b0-4561-be83-c1c147c2ca82', '唐', '["一幅輕綃寄海濱，越姑長感昔時恩。","欲知別後情多少，點點憑君看淚痕。"]', '["一幅轻綃寄海濱，越姑长感昔时恩。","欲知別後情多少，点点憑君看泪痕。"]', '诗', 'shi', '', NULL, '代京妓越賓荅徐鉉 鍾謨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10690ae2-a50f-407b-aa9e-4f3b3b9e9f8c', '寄麻姑仙壇道士', '寄麻姑仙壇道士', '08a5b1c6-c456-485f-aaba-74a8deb2a0f5', '唐', '["別後相思鶴信稀，郡樓南望遠峰迷。","人歸仙洞雲連地，花落春林水滿溪。","白髮只應悲鏡鑷，丹砂猶待寄刀圭。","方平車駕今何在，常苦塵中日易西。"]', '["別後相思鹤信稀，郡楼南望远峰迷。","人归仙洞云連地，花落春林水满溪。","白髮只應悲镜鑷，丹砂猶待寄刀圭。","方平车駕今何在，常苦塵中日易西。"]', '诗', 'shi', '', NULL, '寄麻姑仙壇道士 查文徽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6084b90d-8dd5-4cde-92de-f0b7b59e7959', '贈韓定辭', '贈韓定辞', '8a053c83-551f-4390-89c1-251045912ed7', '唐', '["燧林芳草綿綿思，盡日相攜陟麗譙。","別後巏嵍山上望，羨君時復見王喬。"]', '["燧林芳草綿綿思，尽日相携陟丽譙。","別後巏嵍山上望，羨君时复见王喬。"]', '诗', 'shi', '', NULL, '贈韓定辭 馬彧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7b374ca-5c3a-4568-9060-0cd9721accfe', '答馬彧', '答马彧', '0de9b6cf-1777-42ae-bd08-9bc94f32e575', '唐', '["崇霞臺上神仙客，學辨癡龍藝最多。","盛德好將銀管述，麗詞堪與雪兒歌。"]', '["崇霞台上神仙客，学辨癡龙藝最多。","盛德好將銀管述，丽词堪與雪兒歌。"]', '诗', 'shi', '', NULL, '答馬彧 韓定辭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db652f85-1276-487d-814e-796920f26d98', '題楊克儉池館', '題楊克儉池館', 'b9d611a1-3f45-4255-874b-112315fdb4c2', '唐', '["經旬因雨不重來，門有蛛絲徑有苔。","再向白蓮亭上望，不知花木爲誰開。"]', '["經旬因雨不重来，门有蛛絲徑有苔。","再向白蓮亭上望，不知花木爲誰开。"]', '诗', 'shi', '', NULL, '題楊克儉池館 何昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4798acb6-7d38-4d65-8696-033fadc34f56', '獻江淮郡守盧公', '獻江淮郡守盧公', '7525d3d8-0e01-498d-b933-08cffdc0e066', '唐', '["塞詔東來淝水濱，時情惟望秉陶鈞。","將軍一陣爲功業，忍見沙塲百戰人。"]', '["塞詔东来淝水濱，时情惟望秉陶鈞。","將軍一陣爲功業，忍见沙塲百戰人。"]', '诗', 'shi', '', NULL, '獻江淮郡守盧公 李羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b005625f-2fa7-457f-97f0-6c8fc22ba6b4', '南山池', '南山池', '8c04ed61-2a6c-4f32-b5ba-5c6c8390aa27', '唐', '["翡翠戲翻荷葉雨，鷺鷥飛破竹林煙。","時沽村酒臨軒酌，擬摘新茶靠石煎。"]', '["翡翠戲翻荷葉雨，鷺鷥飞破竹林煙。","时沽村酒臨軒酌，擬摘新茶靠石煎。"]', '诗', 'shi', '', NULL, '南山池 梁藻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0e441fe-8fac-4ae5-b493-f54e7fbfaa04', '嘲廬山道士', '嘲廬山道士', 'bad237a1-c753-4fde-af0c-fd059f94d065', '唐', '["啖肉先生欲上昇，黃雲踏破紫雲崩。","龍腰鶴背無多力，傳與麻姑借大鵬。"]', '["啖肉先生欲上昇，黄云踏破紫云崩。","龙腰鹤背無多力，傳與麻姑借大鵬。"]', '诗', 'shi', '', NULL, '嘲廬山道士 陳沆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8845da3-c254-498d-8481-8d5bd05c2c95', '句', '句', 'bad237a1-c753-4fde-af0c-fd059f94d065', '唐', '["罷却兒女戲，放他花木生。","掃地雲黏箒，耕山鳥怕牛。","點入旱雲千國仰，力浮塵世一毫輕。"]', '["罷却兒女戲，放他花木生。","掃地云黏箒，耕山鸟怕牛。","点入旱云千国仰，力浮塵世一毫轻。"]', '诗', 'shi', '', NULL, '句 陳沆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd30d356-9c60-4689-afe6-df65886a2c68', '贈織錦人', '贈织錦人', 'b1794e7c-51fb-4e1d-a137-cbc5ded86ddb', '唐', '["札札機聲曉復晡，眼穿力盡竟何如。","美人一曲成千賜，心裏猶嫌花樣疎。"]', '["札札機声晓复晡，眼穿力尽竟何如。","美人一曲成千賜，心裏猶嫌花樣疎。"]', '诗', 'shi', '', NULL, '贈織錦人 李詢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d80bf62a-7a94-4009-ab3e-b61adc86797d', '題金山', '題金山', 'c8367420-0914-4ae2-8ef9-01113b5ce13f', '唐', '["靈山一峰秀，岌然殊衆山。","盤根大江底，插影浮雲間。","雷霆常間作，風雨時往還。","象外懸清影，千載長躋攀。"]', '["靈山一峰秀，岌然殊衆山。","盤根大江底，插影浮云间。","雷霆常间作，风雨时往還。","象外懸清影，千載长躋攀。"]', '诗', 'shi', '', NULL, '題金山 韓垂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('551d99e1-9262-4c84-bd8a-f77183a44c93', '後湖', '後湖', 'bad50f1f-7129-472c-8ad2-4ebcd3d9d710', '唐', '["雷轟疊鼓火翻旗，三異翩翩試水師。","驚起黑龍眠不得，狂風猛雨不多時。"]', '["雷轟叠鼓火翻旗，三異翩翩試水師。","驚起黑龙眠不得，狂风猛雨不多时。"]', '诗', 'shi', '', NULL, '後湖 朱存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('750b38aa-fea0-4378-89a1-81367990b222', '和徐舍人九月十一日見寄', '和徐舍人九月十一日见寄', 'be6bda6e-535e-4277-8cfa-85d950567d32', '唐', '["衡門寂寂逢迎少，不見仙郎向五旬。","莫問龍山前日事，菊花開却爲閑人。"]', '["衡门寂寂逢迎少，不见仙郎向五旬。","莫问龙山前日事，菊花开却爲闲人。"]', '诗', 'shi', '', NULL, '和徐舍人九月十一日見寄 陳彥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58ef9510-fde1-41ce-adbf-9fe5fad72f81', '登游齊山', '登游齊山', 'e879fc35-2d86-4612-84bd-850252ad2888', '唐', '["星使南馳入楚重，此山偏得駐行蹤。","落花滿地月華冷，寂寞舊山三四峰。"]', '["星使南驰入楚重，此山偏得駐行蹤。","落花满地月华冷，寂寞旧山三四峰。"]', '诗', 'shi', '', NULL, '登游齊山 許堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9b773c4-38f6-45fa-a92a-22721e3b8b5a', '遊溧陽下山寺', '游溧陽下山寺', 'e879fc35-2d86-4612-84bd-850252ad2888', '唐', '["地枕吳溪與越峰，前朝恩錫靈泉額。","竹林晴見雁塔高，石室曾棲幾禪伯。","荒碑字沒秋苔深，古池香泛荷花白。","客有經年說別林，落日啼猨情脈脈。"]', '["地枕吳溪與越峰，前朝恩錫靈泉額。","竹林晴见雁塔高，石室曾棲幾禪伯。","荒碑字沒秋苔深，古池香泛荷花白。","客有經年说別林，落日啼猨情脈脈。"]', '诗', 'shi', '', NULL, '遊溧陽下山寺 許堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e1a5951-1619-41c7-9efe-91df3e38e555', '題幽棲觀', '題幽棲观', 'e879fc35-2d86-4612-84bd-850252ad2888', '唐', '["仙翁上昇去，丹井寄晴壑。","山色接天台，湖光照寥廓。","玉洞絕無人，老檜猶棲鶴。","我欲掣青蛇，他時沖碧落。"]', '["仙翁上昇去，丹井寄晴壑。","山色接天台，湖光照寥廓。","玉洞絕無人，老檜猶棲鹤。","我欲掣青蛇，他时沖碧落。"]', '诗', 'shi', '', NULL, '題幽棲觀 許堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61dadf1b-572e-49d4-8e33-893efc780576', '上舍人徐鉉', '上舍人徐鉉', 'e879fc35-2d86-4612-84bd-850252ad2888', '唐', '["幾宵煙月鎖樓臺，欲寄侯門薦下才。","滿面塵埃人不識，謾隨流水出山來。"]', '["幾宵煙月鎖楼台，欲寄侯门薦下才。","满面塵埃人不識，謾隨流水出山来。"]', '诗', 'shi', '', NULL, '上舍人徐鉉 許堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da8d379c-6683-40c7-8bcd-5d26351ac27b', '題茅山觀', '題茅山观', 'e879fc35-2d86-4612-84bd-850252ad2888', '唐', '["常恨清風千載鬱，洞天令得恣遊遨。","松楸古色玉壇靜，鸞鶴不來青漢高。","茅氏井寒丹已化，玄宗碑斷夢仍勞。","分明有箇長生路，休向紅塵嘆二毛。"]', '["常恨清风千載鬱，洞天令得恣游遨。","松楸古色玉壇静，鸾鹤不来青漢高。","茅氏井寒丹已化，玄宗碑斷梦仍勞。","分明有箇长生路，休向紅塵嘆二毛。"]', '诗', 'shi', '', NULL, '題茅山觀 許堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('800c2286-cd08-4e5d-98dc-22d44e73bb4f', '建州節帥更代筵上獻詩', '建州節帥更代筵上獻诗', '23e26056-a794-42a7-9a68-d081bb0092da', '唐', '["旌旗赴天臺，溪山曉色開。","萬家悲更喜，迎佛送如來。"]', '["旌旗赴天台，溪山晓色开。","万家悲更喜，迎佛送如来。"]', '诗', 'shi', '', NULL, '建州節帥更代筵上獻詩 王感化 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c7a8ac1-5430-4fc6-8bd4-ee614d350e95', '奉元宗命詠苑中白野鵲', '奉元宗命詠苑中白野鵲', '23e26056-a794-42a7-9a68-d081bb0092da', '唐', '["碧岩深洞恣遊遨，天與蘆花作羽毛。","要識此來棲宿處，上林瓊樹一枝高。"]', '["碧岩深洞恣游遨，天與蘆花作羽毛。","要識此来棲宿处，上林瓊樹一枝高。"]', '诗', 'shi', '', NULL, '奉元宗命詠苑中白野鵲 王感化 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f71327c2-8221-4a34-b813-45c0700e55d0', '句', '句', '23e26056-a794-42a7-9a68-d081bb0092da', '唐', '["草中誤認將軍虎，山上曾爲道士羊。"]', '["草中誤認將軍虎，山上曾爲道士羊。"]', '诗', 'shi', '', NULL, '句 王感化 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a65863f-894e-40a2-8082-e2196d82c77c', '元宗釣魚無獲進詩', '元宗釣鱼無獲進诗', '01ff7fc2-3f09-41c6-8aab-0bcb281ce445', '唐', '["玉甃垂鉤興正濃，碧池春暖水溶溶。","凡鱗不敢吞香[餌]，知是君王合釣龍。"]', '["玉甃垂鉤兴正濃，碧池春暖水溶溶。","凡鱗不敢吞香[餌]，知是君王合釣龙。"]', '诗', 'shi', '', NULL, '元宗釣魚無獲進詩 李家明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7c48e94-5c96-49b6-b07a-41440693a8e8', '詠臥牛', '詠臥牛', '01ff7fc2-3f09-41c6-8aab-0bcb281ce445', '唐', '["曾遭甯戚鞭敲角，又被田單火燎身。","閑向斜陽嚼枯草，近來問喘爲無人。"]', '["曾遭甯戚鞭敲角，又被田單火燎身。","闲向斜陽嚼枯草，近来问喘爲無人。"]', '诗', 'shi', '', NULL, '詠臥牛 李家明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfcb2873-5911-42b5-b375-357186a48928', '題紙鳶止宋齊丘哭子', '題紙鳶止宋齊丘哭子', '01ff7fc2-3f09-41c6-8aab-0bcb281ce445', '唐', '["安排唐祚革強吳，盡是先生作計謨。","一個孩兒{扌棄}不得，讓皇百口合何如。"]', '["安排唐祚革強吳，尽是先生作計謨。","一個孩兒{扌棄}不得，讓皇百口合何如。"]', '诗', 'shi', '', NULL, '題紙鳶止宋齊丘哭子 李家明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20a5cacf-2dd1-4d01-8e16-ef9de428f825', '詠皖公山', '詠皖公山', '01ff7fc2-3f09-41c6-8aab-0bcb281ce445', '唐', '["龍舟輕颭錦帆風，正值宸游望遠空。","迴首皖公山色翠，影斜不到壽杯中。"]', '["龙舟轻颭錦帆风，正值宸游望远空。","迴首皖公山色翠，影斜不到壽杯中。"]', '诗', 'shi', '', NULL, '詠皖公山 李家明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e2d26a1-d095-4897-95da-315233ab853a', '奉和聖制送鄧王牧宣城', '奉和聖制送鄧王牧宣城', 'c21e5c6a-4c30-4b4a-ba04-7edc4ca13e0e', '唐', '["千里陵陽同[陝]服，鑿門胙土寄親賢。","曙煙已別黃金殿，晚照重登白玉筵。","江上浮光宜雨後，郡中遠岫列窗前。","天心待報期年政，留與工師播管弦。"]', '["千里陵陽同[陝]服，鑿门胙土寄親賢。","曙煙已別黄金殿，晚照重登白玉筵。","江上浮光宜雨後，郡中远岫列窗前。","天心待報期年政，留與工師播管弦。"]', '诗', 'shi', '', NULL, '奉和聖制送鄧王牧宣城 湯悅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d363820-7f8c-4bca-b922-cc0d6e25e1fd', '早春寄華下同志', '早春寄华下同志', 'c21e5c6a-4c30-4b4a-ba04-7edc4ca13e0e', '唐', '["正是花時節，思君寢復興。","市沽終不醉，春夢亦無憑。","嶽面懸清雨，河心走濁冰。","東門一條路，離恨正相仍。"]', '["正是花时節，思君寢复兴。","市沽終不醉，春梦亦無憑。","嶽面懸清雨，河心走濁冰。","东门一條路，離恨正相仍。"]', '诗', 'shi', '', NULL, '早春寄華下同志 湯悅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab9fc52c-8748-4653-8cd6-9aa1a1808a92', '鼎臣學士侍郎以東館庭梅昔翰苑之毫末今復半枯向時同僚零落都盡素𩬇垂領茲唯二人感舊傷懷發於吟詠惠然好我不能無言輙次來韻攀和', '鼎臣学士侍郎以东館庭梅昔翰苑之毫末今复半枯向时同僚零落都尽素𩬇垂領茲唯二人感旧傷懷發於吟詠惠然好我不能無言輙次来韻攀和', 'c21e5c6a-4c30-4b4a-ba04-7edc4ca13e0e', '唐', '["憶見萌芽日，還憐合抱時。","舊歡如夢想，物態暗還移。","素豔今無幾，朱顏亦自衰。","樹將人共老，何暇更悲絲。"]', '["憶见萌芽日，還怜合抱时。","旧歡如梦想，物態暗還移。","素豔今無幾，朱顏亦自衰。","樹將人共老，何暇更悲絲。"]', '诗', 'shi', '', NULL, '鼎臣學士侍郎以東館庭梅昔翰苑之毫末今復半枯向時同僚零落都盡素𩬇垂領茲唯二人感舊傷懷發於吟詠惠然好我不能無言輙次來韻攀和 湯悅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fddd2f11-7ef7-4229-9a95-dcbfab35e2ea', '再次前韻代梅荅', '再次前韻代梅荅', 'c21e5c6a-4c30-4b4a-ba04-7edc4ca13e0e', '唐', '["託植經多稔，頃筐向盛時。","枝條雖已故，情分不曾移。","莫向堦前老，還同鏡裏衰。","更應憐墮葉，殘吹挂蟲絲。"]', '["託植經多稔，頃筐向盛时。","枝條雖已故，情分不曾移。","莫向堦前老，還同镜裏衰。","更應怜墮葉，殘吹挂蟲絲。"]', '诗', 'shi', '', NULL, '再次前韻代梅荅 湯悅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f746f91a-f0f9-4b89-bc69-f9f525fb9550', '鼎臣學士侍郎楚金舍人學士以再傷庭梅詩同垂寵和清絕感歎情致俱深因成四十字陳謝', '鼎臣学士侍郎楚金舍人学士以再傷庭梅诗同垂寵和清絕感歎情致俱深因成四十字陳謝', 'c21e5c6a-4c30-4b4a-ba04-7edc4ca13e0e', '唐', '["人物同遷謝，重成念舊悲。","連華得瓊玖，合奏發塤篪。","餘枿雖無取，殘芳尚獲知。","問君何所似，珍重杜[秋]詩。"]', '["人物同遷謝，重成念旧悲。","連华得瓊玖，合奏發塤篪。","餘枿雖無取，殘芳尚獲知。","问君何所似，珍重杜[秋]诗。"]', '诗', 'shi', '', NULL, '鼎臣學士侍郎楚金舍人學士以再傷庭梅詩同垂寵和清絕感歎情致俱深因成四十字陳謝 湯悅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e23f91ac-0f02-4281-8323-20aca4df7e10', '送鍾員外', '送鍾員外', 'fbe4f4dc-b2f8-4c02-bc15-c06bc4dce703', '唐', '["麗漢金波滿，當筵玉斚傾。","因思頻聚散，幾復換虧盈。","光徹離襟冷，聲符別管清。","那堪還目此，兩地倚樓情。"]', '["丽漢金波满，當筵玉斚傾。","因思頻聚散，幾复換虧盈。","光徹離襟冷，声符別管清。","那堪還目此，兩地倚楼情。"]', '诗', 'shi', '', NULL, '送鍾員外 蕭彧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03134fb5-0a60-4b7c-86b4-67bd53ef0ff0', '送德林郎中學士赴東府', '送德林郎中学士赴东府', 'fbe4f4dc-b2f8-4c02-bc15-c06bc4dce703', '唐', '["離情折楊柳，此別異春哉。","含露東籬豔，汎香南浦杯。","惜持行次贈，留插醉中迴。","暮齒如能制，玉山甘判頹。"]', '["離情折楊柳，此別異春哉。","含露东籬豔，汎香南浦杯。","惜持行次贈，留插醉中迴。","暮齒如能制，玉山甘判頹。"]', '诗', 'shi', '', NULL, '送德林郎中學士赴東府 蕭彧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23347f25-c769-4d8e-b2f6-97a28433bfc3', '送鍾員外', '送鍾員外', 'eb049fac-d4da-4453-bed0-6832a3616753', '唐', '["萬物中蕭灑，修篁獨逸羣。","貞姿曾冒雪，高節欲凌雲。","細韻風初發，濃煙日正曛。","因題偏惜別，不可暫無君。"]', '["万物中蕭灑，修篁独逸羣。","貞姿曾冒雪，高節欲凌云。","細韻风初發，濃煙日正曛。","因題偏惜別，不可暫無君。"]', '诗', 'shi', '', NULL, '送鍾員外 孫峴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae996842-f73a-49d2-8b43-b6857c121f45', '送鍾員外', '送鍾員外', '44153ee9-2a0b-4f37-86dd-c66d1a211493', '唐', '["送人多折柳，唯我獨吟松。","若保歲寒在，何妨霜雪重。","森梢逢靜境，廓落見孤峰。","還似君高節，亭亭尠繼蹤。"]', '["送人多折柳，唯我独吟松。","若保歲寒在，何妨霜雪重。","森梢逢静境，廓落见孤峰。","還似君高節，亭亭尠繼蹤。"]', '诗', 'shi', '', NULL, '送鍾員外 謝仲宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcecfc1f-3f0a-4043-80f9-3e0b807cac2c', '別諸同志', '別諸同志', 'a6fcee11-a4c5-4245-a010-a5d9d47c68e6', '唐', '["隨陽來萬里，點點度遙空。","影落長江水，聲悲半夜風。","殘秋辭絕漠，無定似驚蓬。","我有離羣恨，飄飄類此鴻。"]', '["隨陽来万里，点点度遙空。","影落长江水，声悲半夜风。","殘秋辞絕漠，無定似驚蓬。","我有離羣恨，飄飄類此鴻。"]', '诗', 'shi', '', NULL, '別諸同志 鍾蒨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('044bdca9-a368-4d15-a60b-68a1123bbce7', '送德林郎中學士赴東府', '送德林郎中学士赴东府', '64fd6d9a-5dff-4e2c-94eb-487a0376e530', '唐', '["摻袂向江頭，朝宗勢未休。","何人乘桂楫，之子過揚州。","颯颯翹沙鴈，漂漂逐浪鷗。","欲知離別恨，半是淚和流。"]', '["摻袂向江头，朝宗勢未休。","何人乘桂楫，之子過揚州。","颯颯翹沙鴈，漂漂逐浪鷗。","欲知離別恨，半是泪和流。"]', '诗', 'shi', '', NULL, '送德林郎中學士赴東府 喬舜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ae9cded-664d-415c-b303-e8ffa24f9d74', '送鍾員外', '送鍾員外', '36b53fd4-f67e-49ad-828f-6e3f42796514', '唐', '["靜追蘋末興，況復值蕭條。","猛勢資新鴈，寒聲伴暮潮。","過山雲散亂，經樹葉飄颻。","今日煙江上，征帆望望遙。"]', '["静追蘋末兴，況复值蕭條。","猛勢資新鴈，寒声伴暮潮。","過山云散亂，經樹葉飄颻。","今日煙江上，征帆望望遙。"]', '诗', 'shi', '', NULL, '送鍾員外 王沂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('273ea6f9-df47-4565-8c57-9cfba4c95046', '送德林郎中學士赴東府', '送德林郎中学士赴东府', '844579cf-45ae-463e-8052-2885d1f01904', '唐', '["上善湛然秋，恩波洽帝猷。","謾言生險浪，豈爽見安流。","汎去星槎遠，澄來月練浮。","滔滔對離酌，入洛稱仙舟。"]', '["上善湛然秋，恩波洽帝猷。","謾言生險浪，豈爽见安流。","汎去星槎远，澄来月練浮。","滔滔对離酌，入洛稱仙舟。"]', '诗', 'shi', '', NULL, '送德林郎中學士赴東府 陳元裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('623f0477-a29a-425f-831a-d4497e6e1c5a', '宿山寺', '宿山寺', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["溪山盡日行，方聽遠鐘聲。","入院逢僧定，登樓見月生。","露垂群木潤，泉落一岩清。","此景關吾事，通宵寐不成。"]', '["溪山尽日行，方听远鐘声。","入院逢僧定，登楼见月生。","露垂群木潤，泉落一岩清。","此景关吾事，通宵寐不成。"]', '诗', 'shi', '', NULL, '宿山寺 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c723c4e4-958e-47f7-843f-2920a4228413', '贈棲隱洞譚先生', '贈棲隐洞譚先生', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["先生雙鬢華，深谷臥雲霞。","不伐有巢樹，多移無主花。","石泉春釀酒，松火夜煎茶。","因問山中事，如君有幾家。"]', '["先生雙鬢华，深谷臥云霞。","不伐有巢樹，多移無主花。","石泉春釀酒，松火夜煎茶。","因问山中事，如君有幾家。"]', '诗', 'shi', '', NULL, '贈棲隱洞譚先生 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d74e332-3dc0-4c1d-89b1-798d2b32cfd8', '歸鴈', '归鴈', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["春至衡陽鴈，思歸塞路長。","汀洲齊奮翼，霄漢共成行。","雪盡翻風暖，寒收度月涼。","直應到秋日，依舊返瀟湘。"]', '["春至衡陽鴈，思归塞路长。","汀洲齊奮翼，霄漢共成行。","雪尽翻风暖，寒收度月涼。","直應到秋日，依旧返瀟湘。"]', '诗', 'shi', '', NULL, '歸鴈 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9db58b5-7a49-416c-9d28-d881795a0c04', '春江送人', '春江送人', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["春江多去情，相去枕長汀。","數鴈別湓浦，片帆離洞庭。","雨餘沙草綠，雲散岸峰青。","誰共觀明月，漁歌夜好聽。"]', '["春江多去情，相去枕长汀。","數鴈別湓浦，片帆離洞庭。","雨餘沙草綠，云散岸峰青。","誰共观明月，漁歌夜好听。"]', '诗', 'shi', '', NULL, '春江送人 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c4b724a-98fd-44df-a837-f48763f6cb40', '過秦嶺', '過秦嶺', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["古今傳此嶺，高下勢崢嶸。","安得青山路，化爲平地行。","蒼苔留虎跡，碧樹障溪聲。","欲過一回首，踟躕無限情。"]', '["古今傳此嶺，高下勢崢嶸。","安得青山路，化爲平地行。","蒼苔留虎跡，碧樹障溪声。","欲過一回首，踟躕無限情。"]', '诗', 'shi', '', NULL, '過秦嶺 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cc88451-6931-4e93-b669-0c2b7bf69b34', '送吳夢誾歸閩', '送吳梦誾归閩', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["甌閩在天末，此去整行衣。","久客逢春盡，思家冒暑歸。","海雲添晚景，山瘴滅晴暉。","相憶吟偏苦，不堪書信稀。"]', '["甌閩在天末，此去整行衣。","久客逢春尽，思家冒暑归。","海云添晚景，山瘴滅晴暉。","相憶吟偏苦，不堪书信稀。"]', '诗', 'shi', '', NULL, '送吳夢誾歸閩 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e11b22c6-a621-44a7-8f7d-fdd28cf9b0d6', '山中夏日', '山中夏日', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["深山宜避暑，門戶映嵐光。","夏木蔭溪路，晝雲埋石牀。","心源澄道靜，衣葛蘸泉涼。","算得紅塵裏，誰知此興長。"]', '["深山宜避暑，门戶映嵐光。","夏木蔭溪路，晝云埋石牀。","心源澄道静，衣葛蘸泉涼。","算得紅塵裏，誰知此兴长。"]', '诗', 'shi', '', NULL, '山中夏日 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9b8f564-151c-49e1-be47-2b051da14307', '宿故人江居', '宿故人江居', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["渡口樹冥冥，南山漸隱青。","漁舟歸舊浦，鷗鳥宿前汀。","靜榻懸燈坐，閑門對浪扃。","相思頻到此，幾番醉還醒。"]', '["渡口樹冥冥，南山漸隐青。","漁舟归旧浦，鷗鸟宿前汀。","静榻懸灯坐，闲门对浪扃。","相思頻到此，幾番醉還醒。"]', '诗', 'shi', '', NULL, '宿故人江居 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04c539e6-5dfa-406a-848d-99f109cf578b', '寄伍喬', '寄伍喬', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["蹉跎春又晚，天末信來遲。","長憶分攜日，正當搖落時。","獨遊饒旅恨，多事失歸期。","君看前溪樹，山禽巢幾枝。"]', '["蹉跎春又晚，天末信来遲。","长憶分携日，正當搖落时。","独游饒旅恨，多事失归期。","君看前溪樹，山禽巢幾枝。"]', '诗', 'shi', '', NULL, '寄伍喬 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f35e245-1e06-4b64-acbf-8b6848925da7', '山中訪人不遇', '山中訪人不遇', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["負琴兼杖藜，特地過巖西。","已見竹軒閉，又聞山鳥啼。","長松寒倚谷，細草暗連溪。","久立無人事，煙霞歸路迷。"]', '["負琴兼杖藜，特地過巖西。","已见竹軒閉，又闻山鸟啼。","长松寒倚谷，細草暗連溪。","久立無人事，煙霞归路迷。"]', '诗', 'shi', '', NULL, '山中訪人不遇 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef6e2036-87e4-48b8-a530-989e1366a1a8', '贈隱者', '贈隐者', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["世路爭名利，深山獨結茅。","安情自得所，非道豈相交。","百尺松當戶，千年鶴在巢。","知君於此景，未欲等閑拋。"]', '["世路爭名利，深山独結茅。","安情自得所，非道豈相交。","百尺松當戶，千年鹤在巢。","知君於此景，未欲等闲拋。"]', '诗', 'shi', '', NULL, '贈隱者 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20dc452e-c782-4507-bf4d-3e7f999d28b2', '寄暹上人', '寄暹上人', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["聞罷城中講，來安頂上禪。","夜燈明石室，清磐出巖泉。","欲訪慙多事，相思恨隔年。","終期息塵慮，接話虎溪邊。"]', '["闻罷城中講，来安頂上禪。","夜灯明石室，清磐出巖泉。","欲訪慙多事，相思恨隔年。","終期息塵慮，接話虎溪邊。"]', '诗', 'shi', '', NULL, '寄暹上人 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20e2c5f8-2d12-4251-8af4-0021dcb56cc7', '江邊閑步', '江邊闲步', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["閑來南渡口，迤邐看江楓。","一路波濤畔，數家蘆葦中。","遠汀排晚樹，深浦漾寒鴻。","吟罷慵回首，此情誰與同。"]', '["闲来南渡口，迤邐看江楓。","一路波濤畔，數家蘆葦中。","远汀排晚樹，深浦漾寒鴻。","吟罷慵回首，此情誰與同。"]', '诗', 'shi', '', NULL, '江邊閑步 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06c7d5bd-7e3e-4b48-b81b-f10192ec994e', '過王逸人園林', '過王逸人园林', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["谷口何時住，煙霞一徑深。","水聲離遠洞，山色出疎林。","雪彩從沾鬢，年光不計心。","自言人少到，猶喜我來尋。"]', '["谷口何时住，煙霞一徑深。","水声離远洞，山色出疎林。","雪彩從沾鬢，年光不計心。","自言人少到，猶喜我来尋。"]', '诗', 'shi', '', NULL, '過王逸人園林 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f08c487-bac5-4525-a8c5-3b433e3c6715', '寄李處士', '寄李处士', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["僧話磻溪叟，平生重赤松。","夜堂悲蟋蟀，秋水老芙蓉。","吟坐倦垂釣，閑行多倚筇。","聞名來已久，未得一相逢。"]', '["僧話磻溪叟，平生重赤松。","夜堂悲蟋蟀，秋水老芙蓉。","吟坐倦垂釣，闲行多倚筇。","闻名来已久，未得一相逢。"]', '诗', 'shi', '', NULL, '寄李處士 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f664c812-ecd9-4246-bdc0-36d9e8f910a4', '夏日寄史處士', '夏日寄史处士', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["掩關苔滿地，終日坐騰騰。","暑氣冷衣葛，暮雲催燭燈。","寂寥知得趣，疎嬾似無能。","還憶舊遊否，何年別杜陵。"]', '["掩关苔满地，終日坐腾腾。","暑氣冷衣葛，暮云催燭灯。","寂寥知得趣，疎嬾似無能。","還憶旧游否，何年別杜陵。"]', '诗', 'shi', '', NULL, '夏日寄史處士 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a9b6a4b-ce02-4c02-91a7-6f2028438df2', '夏日登瀑頂寺因寄諸知己', '夏日登瀑頂寺因寄諸知己', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["曾於塵裏望，此景在煙霄。","巖靜水聲近，山深暑氣遙。","杖藜青石路，煮茗白雲樵。","寄語爲郎者，誰能訪寂寥。"]', '["曾於塵裏望，此景在煙霄。","巖静水声近，山深暑氣遙。","杖藜青石路，煮茗白云樵。","寄語爲郎者，誰能訪寂寥。"]', '诗', 'shi', '', NULL, '夏日登瀑頂寺因寄諸知己 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7cfba21-ad4c-4d1a-bac1-890660849074', '懷果上人', '懷果上人', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["擁錫南遊去，名香幾處焚。","別來無遠信，多恐在深雲。","好月曾同步，幽香省共聞。","相思不相見，林下葉紛紛。"]', '["擁錫南游去，名香幾处焚。","別来無远信，多恐在深云。","好月曾同步，幽香省共闻。","相思不相见，林下葉紛紛。"]', '诗', 'shi', '', NULL, '懷果上人 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8b1b4bf-7453-465e-944a-1fbafa8b8069', '寄故園兄弟', '寄故园兄弟', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["久與鄉關阻，風塵損舊衣。","水思和月泛，山憶共僧歸。","林想添鄰舍，溪應改釣磯。","弟兄無苦事，不用別庭闈。"]', '["久與乡关阻，风塵損旧衣。","水思和月泛，山憶共僧归。","林想添鄰舍，溪應改釣磯。","弟兄無苦事，不用別庭闈。"]', '诗', 'shi', '', NULL, '寄故園兄弟 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23db21d3-d86d-42e5-a0db-dc43301cc6bb', '早秋吟眺', '早秋吟眺', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["新秋初雨後，獨立對遙山。","去鳥望中沒，好雲吟裏還。","長年慙道薄，明代取身閑。","從有西征思，園林嬾閉關。"]', '["新秋初雨後，独立对遙山。","去鸟望中沒，好云吟裏還。","长年慙道薄，明代取身闲。","從有西征思，园林嬾閉关。"]', '诗', 'shi', '', NULL, '早秋吟眺 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4056ef9a-8c23-47ee-868e-48596a7a3721', '送江爲歸嶺南', '送江爲归嶺南', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["舊山臨海色，歸路到天涯。","此別各多事，重逢是幾時。","江行晴望遠，嶺宿夜吟遲。","珍重南方客，清風失所思。"]', '["旧山臨海色，归路到天涯。","此別各多事，重逢是幾时。","江行晴望远，嶺宿夜吟遲。","珍重南方客，清风失所思。"]', '诗', 'shi', '', NULL, '送江爲歸嶺南 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae06ee63-7a6a-483c-9ef8-701a5a7ed15b', '山中荅友人', '山中荅友人', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["偶愛春山在，因循值暑時。","風塵非所願，泉石本相宜。","坐久松陰轉，吟餘蟬韻移。","自慙疎野甚，多失故人期。"]', '["偶愛春山在，因循值暑时。","风塵非所願，泉石本相宜。","坐久松陰轉，吟餘蟬韻移。","自慙疎野甚，多失故人期。"]', '诗', 'shi', '', NULL, '山中荅友人 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e66e7b51-5572-434f-9dc0-e631f7838f73', '山齋早秋雨中', '山斋早秋雨中', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["深居少往還，卷箔早秋間。","雨灑吟蟬樹，雲藏嘯狖山。","炎蒸如便退，衣葛亦堪閑。","靜坐得無事，酒巵聊暢顏。"]', '["深居少往還，卷箔早秋间。","雨灑吟蟬樹，云藏嘯狖山。","炎蒸如便退，衣葛亦堪闲。","静坐得無事，酒巵聊暢顏。"]', '诗', 'shi', '', NULL, '山齋早秋雨中 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3d91d9e-6933-4ec4-a883-8560ac99d2f1', '送人遊南越', '送人游南越', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["孑然南越去，替爾畏前程。","見說路岐嶮，不通車馬行。","瘴煙迷海色，嶺樹帶猨聲。","獨向山家宿，多應鄉思生。"]', '["孑然南越去，替爾畏前程。","见说路岐嶮，不通车马行。","瘴煙迷海色，嶺樹带猨声。","独向山家宿，多應乡思生。"]', '诗', 'shi', '', NULL, '送人遊南越 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08041cb7-e94d-49e2-8bd4-b9ea7e140e85', '酬東溪史處士', '酬东溪史处士', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["咫尺東溪路，年來偶訪遲。","泉聲迷夜雨，花片落空枝。","石徑逢僧出，山牀見鶴移。","貧齋有琴酒，曾許月圓期。"]', '["咫尺东溪路，年来偶訪遲。","泉声迷夜雨，花片落空枝。","石徑逢僧出，山牀见鹤移。","貧斋有琴酒，曾許月圓期。"]', '诗', 'shi', '', NULL, '酬東溪史處士 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6906983-cde2-46ca-8bea-4acb667434cb', '秋江送客', '秋江送客', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["秋風楚江上，送子話遊遨。","遠水宿何處，孤舟春夜濤。","浦雲沈鴈影，山月照猨嗥。","莫爲飢寒苦，便成名利勞。"]', '["秋风楚江上，送子話游遨。","远水宿何处，孤舟春夜濤。","浦云沈鴈影，山月照猨嗥。","莫爲飢寒苦，便成名利勞。"]', '诗', 'shi', '', NULL, '秋江送客 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3131504c-7888-4f19-bdd2-af70edc51814', '寄山中高逸人', '寄山中高逸人', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["煙霞多放曠，吟嘯是尋常。","猨共摘山果，僧鄰住石房。","躡雲雙屐冷，採藥一身香。","我憶相逢夜，松潭月色涼。"]', '["煙霞多放曠，吟嘯是尋常。","猨共摘山果，僧鄰住石房。","躡云雙屐冷，採藥一身香。","我憶相逢夜，松潭月色涼。"]', '诗', 'shi', '', NULL, '寄山中高逸人 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9494fca-97a0-4480-9605-cc6dad7cea80', '懷友人', '懷友人', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["浮世況多事，飄流每歎君。","路岐何處去，消息幾時聞。","吟裏落秋葉，望中生暮雲。","孤懷誰慰我，夕鳥自成群。"]', '["浮世況多事，飄流每歎君。","路岐何处去，消息幾时闻。","吟裏落秋葉，望中生暮云。","孤懷誰慰我，夕鸟自成群。"]', '诗', 'shi', '', NULL, '懷友人 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72a9c6b6-d314-4205-8c3e-365c9f2878eb', '送人歸別業', '送人归別業', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["別業五湖上，春殘去路賒。","還尋舊山水，重到故人家。","門徑掩芳草，園林落異花。","君知釣磯在，猶喜有生涯。"]', '["別業五湖上，春殘去路賒。","還尋旧山水，重到故人家。","门徑掩芳草，园林落異花。","君知釣磯在，猶喜有生涯。"]', '诗', 'shi', '', NULL, '送人歸別業 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f30fc2c2-f211-4207-b4fb-4aa7a97d8d04', '冬日登江樓', '冬日登江楼', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["高樓臨古岸，野步晚來登。","江水因寒落，山雲爲雪凝。","遠村雖入望，危檻不堪憑。","親老未歸去，鄉愁徒自興。"]', '["高楼臨古岸，野步晚来登。","江水因寒落，山云爲雪凝。","远村雖入望，危檻不堪憑。","親老未归去，乡愁徒自兴。"]', '诗', 'shi', '', NULL, '冬日登江樓 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('709fb6d7-36b2-42f6-925a-bbccf91965a1', '寄張山人', '寄張山人', 'db0e08a1-b5bf-4df4-a5df-68262a8cec0a', '唐', '["草堂南澗邊，有客嘯雲煙。","掃葉林風後，拾薪山雨前。","野橋通竹徑，流水入芝田。","琴月相親夜，更深戀不眠。"]', '["草堂南澗邊，有客嘯云煙。","掃葉林风後，拾薪山雨前。","野橋通竹徑，流水入芝田。","琴月相親夜，更深戀不眠。"]', '诗', 'shi', '', NULL, '寄張山人 孟貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('783b48e9-b456-4c72-a816-fb78ec2b4a1e', '杜鵑花', '杜鵑花', 'a4a29e2c-10fc-461c-aa65-efe03e2d869c', '唐', '["杜鵑花與鳥，怨豔兩何賒。","疑是口中血，滴成枝上花。","一聲寒食夜，數朵野僧家。","謝豹出不出，日遲遲又斜。"]', '["杜鵑花與鸟，怨豔兩何賒。","疑是口中血，滴成枝上花。","一声寒食夜，數朵野僧家。","謝豹出不出，日遲遲又斜。"]', '诗', 'shi', '', NULL, '杜鵑花 成彥雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('768e3bac-d59d-4602-a470-80a34f966006', '江上楓', '江上楓', 'a4a29e2c-10fc-461c-aa65-efe03e2d869c', '唐', '["江楓自蓊鬱，不競松筠力。","一葉落漁家，殘陽帶秋色。"]', '["江楓自蓊鬱，不競松筠力。","一葉落漁家，殘陽带秋色。"]', '诗', 'shi', '', NULL, '江上楓 成彥雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bdd9246-d1c6-41b0-9350-0af8d67cb577', '夜夜曲', '夜夜曲', 'a4a29e2c-10fc-461c-aa65-efe03e2d869c', '唐', '["自從君去夜，錦幌孤蘭麝。","欹枕對銀缸，秦箏綠窗下。"]', '["自從君去夜，錦幌孤蘭麝。","欹枕对銀缸，秦箏綠窗下。"]', '诗', 'shi', '', NULL, '夜夜曲 成彥雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40604fe3-1589-4c10-a501-07aec34ce4fc', '村行', '村行', 'a4a29e2c-10fc-461c-aa65-efe03e2d869c', '唐', '["曖曖村煙暮，牧童出深塢。","騎牛不顧人，吹笛尋山去。"]', '["曖曖村煙暮，牧童出深塢。","騎牛不顧人，吹笛尋山去。"]', '诗', 'shi', '', NULL, '村行 成彥雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21877f45-1a57-4807-9421-b7d934d573ac', '煎茶', '煎茶', 'a4a29e2c-10fc-461c-aa65-efe03e2d869c', '唐', '["岳寺春深睡起時，虎跑泉畔思遲遲。","蜀茶倩箇雲僧碾，自拾枯松三四枝。"]', '["岳寺春深睡起时，虎跑泉畔思遲遲。","蜀茶倩箇云僧碾，自拾枯松三四枝。"]', '诗', 'shi', '', NULL, '煎茶 成彥雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ae3e7d6-4525-4f7e-b1fb-f00b54dfb1f9', '松', '松', 'a4a29e2c-10fc-461c-aa65-efe03e2d869c', '唐', '["大夫名價古今聞，盤屈孤貞更出羣。","將謂嶺頭閑得了，夕陽猶挂數枝雲。"]', '["大夫名價古今闻，盤屈孤貞更出羣。","將謂嶺头闲得了，夕陽猶挂數枝云。"]', '诗', 'shi', '', NULL, '松 成彥雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7aa27ae8-0d08-440c-a0bb-f84aa1b6b3ed', '新燕', '新燕', 'a4a29e2c-10fc-461c-aa65-efe03e2d869c', '唐', '["纔離海島宿江濱，應夢笙歌作近鄰。","減省雕梁竝頭語，畫堂中有未歸人。"]', '["纔離海島宿江濱，應梦笙歌作近鄰。","減省雕梁竝头語，畫堂中有未归人。"]', '诗', 'shi', '', NULL, '新燕 成彥雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b959da0b-41f2-4e71-96c7-1a673e3d13f8', '會友不至', '會友不至', 'a4a29e2c-10fc-461c-aa65-efe03e2d869c', '唐', '["王孫還是負佳期，玉馬追遊日漸西。","獨上郊原人不見，鷓鴣飛過落花溪。"]', '["王孫還是負佳期，玉马追游日漸西。","独上郊原人不见，鷓鴣飞過落花溪。"]', '诗', 'shi', '', NULL, '會友不至 成彥雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d745918-a733-4461-90c0-ba05f77f2b75', '惜花', '惜花', 'a4a29e2c-10fc-461c-aa65-efe03e2d869c', '唐', '["忘餐爲戀滿枝紅，錦障頻移護晚風。","客散酒酣歸未得，欄邊獨立月明中。"]', '["忘餐爲戀满枝紅，錦障頻移護晚风。","客散酒酣归未得，欄邊独立月明中。"]', '诗', 'shi', '', NULL, '惜花 成彥雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('974f2ad8-33b5-4b1a-8eca-b6bf03a1bad7', '中秋月', '中秋月', 'a4a29e2c-10fc-461c-aa65-efe03e2d869c', '唐', '["王母粧成鏡未收，倚欄人在水精樓。","笙歌莫占清光盡，留與溪翁一釣舟。"]', '["王母粧成镜未收，倚欄人在水精楼。","笙歌莫占清光尽，留與溪翁一釣舟。"]', '诗', 'shi', '', NULL, '中秋月 成彥雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32947a7f-2073-4b93-8be4-b2d4349466fb', '暮春日宴溪亭', '暮春日宴溪亭', 'a4a29e2c-10fc-461c-aa65-efe03e2d869c', '唐', '["寒食尋芳遊不足，溪亭還醉綠楊煙。","誰家花落臨流樹，數片殘紅到檻前。"]', '["寒食尋芳游不足，溪亭還醉綠楊煙。","誰家花落臨流樹，數片殘紅到檻前。"]', '诗', 'shi', '', NULL, '暮春日宴溪亭 成彥雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c63c156e-182d-4b65-9689-b5aa857e7e86', '曉', '晓', 'a4a29e2c-10fc-461c-aa65-efe03e2d869c', '唐', '["列宿回元朝北極，爽神晞露滴樓臺。","佳人卷箔臨階砌，笑指庭花昨夜開。"]', '["列宿回元朝北極，爽神晞露滴楼台。","佳人卷箔臨階砌，笑指庭花昨夜开。"]', '诗', 'shi', '', NULL, '曉 成彥雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('980c8a82-9fda-43be-a276-7ab9e28cb5cc', '夕', '夕', 'a4a29e2c-10fc-461c-aa65-efe03e2d869c', '唐', '["臺榭沈沈禁漏初，麝煙紅蠟透蝦鬚。","雕籠鸚鵡將棲宿，不許鵶鬟轉轆轤。"]', '["台榭沈沈禁漏初，麝煙紅蠟透蝦鬚。","雕籠鸚鵡將棲宿，不許鵶鬟轉轆轤。"]', '诗', 'shi', '', NULL, '夕 成彥雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('177fd90a-473f-4e98-8b2f-d8e9af8f72b7', '露', '露', 'a4a29e2c-10fc-461c-aa65-efe03e2d869c', '唐', '["銀河昨夜降醍醐，灑遍坤維萬象蘇。","疑是鮫人曾泣處，滿池荷葉捧真珠。"]', '["銀河昨夜降醍醐，灑遍坤維万象蘇。","疑是鮫人曾泣处，满池荷葉捧真珠。"]', '诗', 'shi', '', NULL, '露 成彥雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('348a013e-552a-461d-a2d3-5499d4043881', '遊紫陽宮', '游紫陽宮', 'a4a29e2c-10fc-461c-aa65-efe03e2d869c', '唐', '["古殿煙霞簇畫屏，直疑踪跡到蓬瀛。","碧桃滿地眠花鹿，深院松窗擣藥聲。"]', '["古殿煙霞簇畫屏，直疑踪跡到蓬瀛。","碧桃满地眠花鹿，深院松窗擣藥声。"]', '诗', 'shi', '', NULL, '遊紫陽宮 成彥雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adfdb8fb-548d-41c7-af61-0ca0aeb11e96', '除夜', '除夜', 'a4a29e2c-10fc-461c-aa65-efe03e2d869c', '唐', '["銅龍看却送春來，莫惜顛狂酒百杯。","吟鬢就中專擬白，那堪更被二更催。"]', '["銅龙看却送春来，莫惜顛狂酒百杯。","吟鬢就中專擬白，那堪更被二更催。"]', '诗', 'shi', '', NULL, '除夜 成彥雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39b0f2b2-7e38-49ad-9273-fa6bdf685354', '元日', '元日', 'a4a29e2c-10fc-461c-aa65-efe03e2d869c', '唐', '["戴星先捧祝堯觴，鏡裏堪驚兩鬢霜。","好是燈前偷失笑，屠蘇應不得先嘗。"]', '["戴星先捧祝堯觴，镜裏堪驚兩鬢霜。","好是灯前偷失笑，屠蘇應不得先嘗。"]', '诗', 'shi', '', NULL, '元日 成彥雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae74b612-2fdf-4565-aa46-e385520b397d', '寒夜吟', '寒夜吟', 'a4a29e2c-10fc-461c-aa65-efe03e2d869c', '唐', '["洞房脉脉寒宵永，燭影香消金鳳冷。","猧兒睡魘喚不醒，滿窗撲落銀蟾影。"]', '["洞房脉脉寒宵永，燭影香消金鳳冷。","猧兒睡魘喚不醒，满窗撲落銀蟾影。"]', '诗', 'shi', '', NULL, '寒夜吟 成彥雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf0bd1a2-70c2-470a-8495-0c578fd77966', '柳枝辭九首 一', '柳枝辞九首 一', 'a4a29e2c-10fc-461c-aa65-efe03e2d869c', '唐', '["輕籠小徑近誰家，玉馬追風翠影斜。","愛把長條惱公子，惹他頭上海棠花。"]', '["轻籠小徑近誰家，玉马追风翠影斜。","愛把长條惱公子，惹他头上海棠花。"]', '诗', 'shi', '', NULL, '柳枝辭九首 一 成彥雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51b73ef4-8018-424d-923c-c6fc4cbbf10b', '柳枝辭九首 二', '柳枝辞九首 二', 'a4a29e2c-10fc-461c-aa65-efe03e2d869c', '唐', '["鵝黃剪出小花鈿，綴上芳枝色轉鮮。","飲散無人收拾得，月明階下伴鞦韆。"]', '["鵝黄剪出小花鈿，綴上芳枝色轉鲜。","饮散無人收拾得，月明階下伴鞦韆。"]', '诗', 'shi', '', NULL, '柳枝辭九首 二 成彥雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cd52503-19d8-4253-a57d-dec6cc70f21a', '柳枝辭九首 三', '柳枝辞九首 三', 'a4a29e2c-10fc-461c-aa65-efe03e2d869c', '唐', '["東君愛惜與先春，草澤無人處也新。","委囑露華幷細雨，莫教遲日惹風塵。"]', '["东君愛惜與先春，草澤無人处也新。","委囑露华幷細雨，莫教遲日惹风塵。"]', '诗', 'shi', '', NULL, '柳枝辭九首 三 成彥雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24371f88-4e8c-4406-a28b-60e334804faf', '柳枝辭九首 四', '柳枝辞九首 四', 'a4a29e2c-10fc-461c-aa65-efe03e2d869c', '唐', '["句踐初迎西子年，琉璃爲箒掃溪煙。","至今不改當時色，留與王孫繫酒船。"]', '["句踐初迎西子年，琉璃爲箒掃溪煙。","至今不改當时色，留與王孫繫酒船。"]', '诗', 'shi', '', NULL, '柳枝辭九首 四 成彥雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43a4bb3f-1ec9-4e63-9ca1-3cdd7b4c9c1d', '柳枝辭九首 五', '柳枝辞九首 五', 'a4a29e2c-10fc-461c-aa65-efe03e2d869c', '唐', '["綠楊移傍小亭栽，便擁穠煙撥不開。","誰把金刀爲刪掠，放教明月入窗來。"]', '["綠楊移傍小亭栽，便擁穠煙撥不开。","誰把金刀爲刪掠，放教明月入窗来。"]', '诗', 'shi', '', NULL, '柳枝辭九首 五 成彥雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15fa0df4-8fb4-4c1c-8e5d-6d18e10a023d', '柳枝辭九首 六', '柳枝辞九首 六', 'a4a29e2c-10fc-461c-aa65-efe03e2d869c', '唐', '["遠接關河高接雲，雨餘洗出半天津。","牡丹不用相輕薄，自有清陰覆得人。"]', '["远接关河高接云，雨餘洗出半天津。","牡丹不用相轻薄，自有清陰覆得人。"]', '诗', 'shi', '', NULL, '柳枝辭九首 六 成彥雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('febb03a8-720d-4281-91ab-3e77b3df58aa', '柳枝辭九首 七', '柳枝辞九首 七', 'a4a29e2c-10fc-461c-aa65-efe03e2d869c', '唐', '["掩映鶯花媚有餘，風流才調比應無。","朝朝奉御臨池上，不羨青松拜大夫。"]', '["掩映鶯花媚有餘，风流才調比應無。","朝朝奉御臨池上，不羨青松拜大夫。"]', '诗', 'shi', '', NULL, '柳枝辭九首 七 成彥雄 shi');
